local config = {
  ui_story_5031_50310101_1_dialog_content = "Ladies, gentlemen, and guests of all walks of life! Welcome to <color=#FFB400>The Illusionist & Old Bill's Circus</color>! My name is <color=#FFB400>Rainbow</color>, and I'll be your host for tonight's show!",
  ui_story_5031_50310101_2_dialog_content = "All who have joined us aboard the Emerald this splendid evening are the most distinguished guests of our circus.",
  ui_story_5031_50310101_3_dialog_content = "Please set your worries aside and enjoy our marvelous performance.",
  ui_story_5031_50310101_4_dialog_content = "The spectacular performances offered by the Illusionist & Old Bill's Circus are meant to defy all reason and exceed your wildest imagination!",
  ui_story_5031_50310101_5_dialog_content = "This magical moment belongs to you, to me, to the entire world!",
  ui_story_5031_50310101_6_dialog_content = "Without further ado, let us welcome our first act: the high-flying acrobatics of three sisters who have mastered the art of trapeze! Please give a warm welcome to Merylt—",
  ui_story_5031_50310101_7_dialog_content = "Subli—",
  ui_story_5031_50310101_8_dialog_content = "And Frimet—",
  ui_story_5031_50310101_9_dialog_content = "As they take the stage!",
  ui_story_5031_50310101_10_dialog_content = "U-uh, Rainbow...? Isn't the trapeze equipment still being repaired right now?",
  ui_story_5031_50310101_11_dialog_content = "Yeah, even we're not capable of just flying around on our own.",
  ui_story_5031_50310101_12_dialog_content = "Heehee... Actually, I've been training with the circus strongman for a while now.",
  ui_story_5031_50310101_13_dialog_content = "I might even be able to hurl the two of you into the air by myself!",
  ui_story_5031_50310101_14_dialog_content = "H-How about not, that's too dangerous... Besides, there might be collateral damage...",
  ui_story_5031_50310101_15_dialog_content = "Hey Boss, you could put in a few cents, you know.",
  ui_story_5031_50310101_16_dialog_content = "We can't do a dress rehearsal if our equipment isn't ready!",
  ui_story_5031_50310101_17_dialog_content = "Considering how talented we are, I doubt we even need to rehearse!",
  ui_story_5031_50310101_18_dialog_content = "Subli... That's not a very nice way to talk to Ringmaster Jeno.",
  ui_story_5031_50310101_19_dialog_content = "Hmm? We're working on it as we speak.",
  ui_story_5031_50310101_20_dialog_content = "Elvis' supplies finally came in. They're putting the finishing touches on your equipment right now.",
  ui_story_5031_50310101_21_dialog_content = "If you three don't feel like rehearsing, go on and find a place to get some rest.",
  ui_story_5031_50310101_22_dialog_content = "Rainbow, go find that extra who claimed to be able to talk to animals and bring her over.",
  ui_story_5031_50310101_23_dialog_content = "She can fill in for the beast tamer whose still sick from eating shaved ice.",
  ui_story_5031_50310101_24_dialog_content = "Roger that!",
  ui_story_5031_50310101_25_dialog_content = "Are you ready, Miss Fia?",
  ui_story_5031_50310101_26_dialog_content = "J-Just a minute!",
  ui_story_5031_50310101_27_dialog_content = "Come, Bica! Over here, please!",
  ui_story_5031_50310101_28_dialog_content = "Hai.",
  ui_story_5031_50310101_29_dialog_content = "Just like I said, Bica. Jump and do a somersault, okay?",
  ui_story_5031_50310101_30_dialog_content = "Hai!",
  ui_story_5031_50310101_31_dialog_content = "Please, Bica! Just this once, would you please listen to me? That scary-looking ringmaster is still watching!",
  ui_story_5031_50310101_32_dialog_content = "Hai!!",
  ui_story_5031_50310101_33_dialog_content = "Ow! Calm down, I'll apologize, just stop biting me!",
  ui_story_5031_50310101_34_dialog_content = "Stop, stop, stop!!",
  ui_story_5031_50310101_35_dialog_content = "What's going on up there? Resolve your issues off-stage, don't interrupt the rehearsal!",
  ui_story_5031_50310101_36_dialog_content = "Ringmaster Jeno!",
  ui_story_5031_50310101_37_dialog_content = "What? Are you and your little friend finally done with the chitchat?",
  ui_story_5031_50310101_38_dialog_content = "It won't listen to a word I say, Ringmaster Jeno! It's been totally spoiled rotten!",
  ui_story_5031_50310101_39_dialog_content = "Spoiled rotten, you say?",
  ui_story_5031_50310101_40_dialog_content = "That's right! And it bit me really hard just now, too!",
  ui_story_5031_50310101_41_dialog_content = "Oh, that's perfectly normal.",
  ui_story_5031_50310101_42_dialog_content = "Normal?!",
  ui_story_5031_50310101_43_dialog_content = "As part of the circus, they're entitled to the same privileges as everyone else. Namely, they're free to refuse any work whenever they don't feel like working.",
  ui_story_5031_50310101_44_dialog_content = "Whaaaat?!",
  ui_story_5031_50310101_45_dialog_content = "This circus is nothing like the ones I've read about! Not even close!",
  ui_story_5031_50310101_46_dialog_content = "All of the circuses in books treat their animals cruelly and use fear to make them perform. You mean to tell me your circus doesn't do that?",
  ui_story_5031_50310101_47_dialog_content = "And what on earth ever gave you that idea?",
  ui_story_5031_50310101_48_dialog_content = "I've never heard of any such methods... Why would I, or anyone else, hurt them? After all, they're not just our fellow performers, but our dear and important friends.",
  ui_story_5031_50310101_49_dialog_content = "Just look at this Bica, and its soft and fluffy fur. Why would anyone hurt something so precious?",
  ui_story_5031_50310101_50_dialog_content = "Hai!",
  ui_story_5031_50310101_51_dialog_content = "In any case, my circus would never mistreat our animal performers like that. Not now, not ever.",
  ui_story_5031_50310101_52_dialog_content = "Every tamer that came before you was able to find a way to lead them through their performances. You'll have to find your own way, as well.",
  ui_story_5031_50310101_53_dialog_content = "W-Who do you think you're talking to?!",
  ui_story_5031_50310101_54_dialog_content = "*Sobbing* I'll have you know, my name is Fia, the world's greatest extrozoologist! My connection with wondrous beasts is stronger than anyone else's!",
  ui_story_5031_50310101_55_dialog_content = "How... How could I possibly lose...",
  ui_story_5031_50310101_56_dialog_content = "Don't worry, PlayerName. A ballet performance is no challenge for me.",
  ui_story_5031_50310101_57_dialog_content = "I never thought I'd get to see you dance ballet, Carleen.",
  ui_story_5031_50310101_58_dialog_content = "On the Colossus, I've heard other Lumopolis Aurorians talk about your impressive ballet skills. Someone once said you even blew away a professional instructor with your performance!",
  ui_story_5031_50310101_59_dialog_content = "Is that true? If so, I can't help but feel excited to see it, too!",
  ui_story_5031_50310101_60_dialog_content = "PlayerName!!",
  ui_story_5031_50310101_61_dialog_content = "Fia? Aren't you supposed to be practicing your beast-taming performance? What are you doing here?",
  ui_story_5031_50310101_62_dialog_content = "*Sobbing*... Those rotten little monsters are driving me crazy! They don't listen because they're allowed to not work whenever they feel like it!",
  ui_story_5031_50310101_63_dialog_content = "When I think of that... and how my own master bosses me around... I... I... Waaaaaaaah!!!",
  ui_story_5031_50310101_64_dialog_content = "H-Hey, now! Don't cry, Fia...",
  ui_story_5031_50310101_65_dialog_content = "You're supposed to be the world's greatest extrozoologist, remember?",
  ui_story_5031_50310101_66_dialog_content = "I know that! So why does the \"world's greatest extrozoologist\" still have to bustle about all day doing her master's bidding?!",
  ui_story_5031_50310101_67_dialog_content = "Try not to think about it, okay? Remember the way you usually taunt me? You need that kind of energy right now!",
  ui_story_5031_50310101_68_dialog_content = "WHAT!?",
  ui_story_5031_50310101_69_dialog_content = "Well, I mean... Remember all of those hardships we overcame together? It was all to realize your greatest dream!",
  ui_story_5031_50310101_70_dialog_content = "Wah... My greatest dream... and the hardships we overcame...",
  ui_story_5031_50310101_71_dialog_content = "<color=#e8d9bb>Just after arriving in Harbor City</color>",
  ui_story_5031_50310101_72_dialog_content = "Thanks for inviting Vice and me to Harbor City, Carleen.",
  ui_story_5031_50310101_73_dialog_content = "This place is really nice, isn't it? So calm and peaceful... A perfect place for some rest and relaxation!",
  ui_story_5031_50310101_74_dialog_content = "I'm so glad everyone is able to come along, too!",
  ui_story_5031_50310101_75_dialog_content = "It's my pleasure. Everyone has been working so hard lately, so I thought we could all use a small break to recover our bodies and minds.",
  ui_story_5031_50310101_76_dialog_content = "I was just a little girl the last time I came to Harbor City, but it left a profound impression on me all the same.",
  ui_story_5031_50310101_77_dialog_content = "I never thought this place would prosper so much, though. The current laird of the city must be quite the wise leader.",
  ui_story_5031_50310101_78_dialog_content = "<size=33>Found you...</size>",
  ui_story_5031_50310101_79_dialog_content = "You think he's anything like Lord Schwartz?",
  ui_story_5031_50310101_80_dialog_content = "Seeing the happy look on everyone's face here... It really makes me wonder what kind of person is in charge around here.",
  ui_story_5031_50310101_81_dialog_content = "I... don't believe the two are quite so similar.",
  ui_story_5031_50310101_82_dialog_content = "Out of courtesy, we should pay a visit to the city laird now that we're here.",
  ui_story_5031_50310101_83_dialog_content = "I saw a poster on the street just now, it said something about a circus and a carnival aboard one of the big cruise ships?",
  ui_story_5031_50310101_84_dialog_content = "We could ask the city laird more about that, too.",
  ui_story_5031_50310101_85_dialog_content = "If we're here to relax, then this is a great way to kick things off! A real \"summer vacation\" experience!",
  ui_story_5031_50310101_86_dialog_content = "Yeah! I wouldn't mind asking about what else to do here in Harbor City, either! Or what kind of tasty treats they offer!",
  ui_story_5031_50310101_87_dialog_content = "Vice can barely contain her excitement... Guess it really has been too long since we've taken a break.",
  ui_story_5031_50310101_88_dialog_content = "<size=33>Target locked—PlayerName!</size>",
  ui_story_5031_50310101_89_dialog_content = "Well, what are we waiting for? Let's gooo—<size=50>OUCH!</size>",
  ui_story_5031_50310101_90_dialog_content = "Ow, ow! My back!",
  ui_story_5031_50310101_91_dialog_content = "(Hang on, this seems awfully familiar...)",
  ui_story_5031_50310101_92_dialog_content = "Stay back, or I'll call for help! I mean it!",
  ui_story_5031_50310101_93_dialog_content = "Go—",
  ui_story_5031_50310101_94_option_content = "Force... Ow!!",
  ui_story_5031_50310101_95_dialog_content = "My back!!",
  ui_story_5031_50310101_96_dialog_content = "Lo lo lo!",
  ui_story_5031_50310101_97_dialog_content = "Good work, Kyllo. Okay, retreat through the forest as planned!",
  ui_story_5031_50310101_98_dialog_content = "But I just... Look, I just want a friend.",
  ui_story_5031_50310101_99_dialog_content = "Lo...",
  ui_story_5031_50310101_100_dialog_content = "Everyone says I can only make friends with wondrous beasts. I just wanted to prove that it wasn't true, and that I can make friends with Aurorians and Caelestites, too...",
  ui_story_5031_50310101_101_dialog_content = "Heehee... Hey, PlayerName, this makes you my first ever friend!",
  ui_story_5031_50310101_102_dialog_content = "I'm so happy you're my friend, PlayerName!",
  ui_story_5031_50310101_103_dialog_content = "See, Master! I made a friend!",
  ui_story_5031_50310101_104_dialog_content = "S-So it really is you, Fia!!",
  ui_story_5031_50310101_105_dialog_content = "Why did you attack me from that trash can?!",
  ui_story_5031_50310101_106_dialog_content = "Heehee! Gotcha, PlayerName!",
  ui_story_5031_50310101_107_dialog_content = "Fia?",
  ui_story_5031_50310101_108_dialog_content = "Yeah, this is Fia. Don't mind her, this is just how she is.",
  ui_story_5031_50310101_109_dialog_content = "So this is the little extrozoologist you ran into before?",
  ui_story_5031_50310101_110_dialog_content = "I've heard about them and their field of study, but I never expected to meet one so young.",
  ui_story_5031_50310101_111_dialog_content = "It's been a while, Fia.",
  ui_story_5031_50310101_112_dialog_content = "Hi, Vice! Long time no see!",
  ui_story_5031_50310101_113_dialog_content = "Allow me to introduce myself, Miss Carleen. My name is Fia, and I'm the number one extrozoologist in the whole world!",
  ui_story_5031_50310101_114_dialog_content = "Or at least I will be someday. My apprenticeship just ended, so I still have plenty of room to improve. If I make any trouble for you in the future, please try to be patient with me!",
  ui_story_5031_50310101_115_dialog_content = "A pleasure to meet you. I am Carleen of Lumopolis. You know, you remind me very much of Raphael.",
  ui_story_5031_50310101_116_dialog_content = "I should introduce you when the chance arises. I imagine you two will get along quite nicely.",
  ui_story_5031_50310101_117_dialog_content = "Hang on a second...",
  ui_story_5031_50310101_118_dialog_content = "Why are you acting so cute and innocent, all of a sudden?",
  ui_story_5031_50310101_119_dialog_content = "W-What are you talking about, PlayerName? I'm always this sweet, aren't I? It's not nice to say something like that, you know!",
  ui_story_5031_50310101_120_dialog_content = "Yeah, sure... Let's see how long you can keep it up this time, Fia.",
  ui_story_5031_50310101_121_dialog_content = "Anyway, what are you doing here in the first place? And where's Kyllo?",
  ui_story_5031_50310101_122_dialog_content = "Shhh! Not so loud! If you must know, Kyllo and I are on a <color=#FFB400>secret mission</color>. Master's orders!",
  ui_story_5031_50310101_123_dialog_content = "Kyllo is investigating the waters nearby as we speak!",
  ui_story_5031_50310101_124_dialog_content = "\"Secret mission\"? He didn't send you on some wild goose chase again, did he?",
  ui_story_5031_50310101_125_dialog_content = "Also... Kyllo was massive the last time I saw you guys! Don't you think it'll draw too much attention?",
  ui_story_5031_50310101_126_dialog_content = "Hah! That was its giant form! Kyllo has since mastered the art of switching between forms, you know?",
  ui_story_5031_50310101_127_dialog_content = "Master said that with enough training... it might even attain a human form!",
  ui_story_5031_50310101_128_dialog_content = "That... sounds a little terrifying, to be honest.",
  ui_story_5031_50310101_129_dialog_content = "Don't be scared! There's nothing to be afraid of, as long as you don't make Kyllo mad!",
  ui_story_5031_50310101_130_dialog_content = "But enough about Kyllo! The mission at hand is of vital importance, and it has to do with an <color=#FFB400>exotic</color> wondrous beast!",
  ui_story_5031_50310101_131_dialog_content = "Erm... I didn't intend to eavesdrop, by any means...",
  ui_story_5031_50310101_132_dialog_content = "But don't you think you should keep your voice down, Fia?",
  ui_story_5031_50310101_133_dialog_content = "Also, is it safe to assume that your reason for seeking out PlayerName is to recruit him for your \"secret mission\"?",
  ui_story_5031_50310101_134_dialog_content = "Whoops! Guess I was being a little loud, huh?",
  ui_story_5031_50310101_135_dialog_content = "Well, since you two are PlayerName's close friends, I think I can trust you with the details anyway.",
  ui_story_5031_50310101_136_dialog_content = "Now, let me explain the situation as clearly as I can.",
  ui_story_5031_50310101_137_dialog_content = "It all started a few days ago...",
  ui_story_5031_50310101_138_dialog_content = "Whaaaaat! Harbor City? Really?!",
  ui_story_5031_50310101_139_dialog_content = "Wahoo! I hear the scenery is amazing there, and that there's plenty of tasty food, too!",
  ui_story_5031_50310101_140_dialog_content = "I never knew you cared so much, Master! Sending me on vacation after all the hard work I've put in...",
  ui_story_5031_50310101_141_dialog_content = "The beaches there are pretty famous, now that I recall. I need to go pick out a swimsuit!",
  ui_story_5031_50310101_142_dialog_content = "You're getting awfully ahead of yourself, you know...",
  ui_story_5031_50310101_143_dialog_content = "If it were that nice of a trip, my bags would already be packed.",
  ui_story_5031_50310101_144_dialog_content = "I'm sending you out on an assignment, Fia, not on vacation.",
  ui_story_5031_50310101_145_dialog_content = "Here's some money for travel expenses. Get going.",
  ui_story_5031_50310101_146_dialog_content = "Hey! What am I supposed to do with chump change like this?!",
  ui_story_5031_50310101_147_dialog_content = "W-Wait, Master! Where are you going?!",
  ui_story_5031_50310101_148_dialog_content = "Grrr... I should've known! That good-for-nothing master of mine would never be that kind!",
  ui_story_5031_50310101_149_dialog_content = "Uh... Think you can get to the point of the story, Fia? I think we've heard enough about your master...",
  ui_story_5031_50310101_150_dialog_content = "I'm getting to that!",
  ui_story_5031_50310101_151_dialog_content = "Ahem... The objective of our mission is a wondrous beast known as <color=#FFB400>Cloudwhale</color>.",
  ui_story_5031_50310101_152_dialog_content = "My master has been tracking its special Lumina for some time now. There are signs it's come to the waters of Harbor City.",
  ui_story_5031_50310101_153_dialog_content = "But after we arrived, the Lumina suddenly vanished...",
  ui_story_5031_50310101_154_dialog_content = "My theory is that because it vanished so suddenly and so completely, the Cloudwhale must not have left Harbor City... Rather, something must have happened to it!",
  ui_story_5031_50310101_155_dialog_content = "I see... That sounds ominous, indeed.",
  ui_story_5031_50310101_156_dialog_content = "No kidding, and what's more... My master says that this Cloudwhale's power is even greater than that of a Drakolion.",
  ui_story_5031_50310101_157_dialog_content = "The legends say that its power causes Eclipsites to cower in fear, and that its Lumina can dispel even the thickest Darkflow.",
  ui_story_5031_50310101_158_dialog_content = "The Cloudwhale is also said to have an extremely long life span, so it's highly unlikely that it died of natural causes.",
  ui_story_5031_50310101_159_dialog_content = "Considering all these, my master is worried that it fell into the wrong hands.",
  ui_story_5031_50310101_160_dialog_content = "The Cloudwhale is docile by nature, but should its power be misused by the wrong people, the results could be catastrophic...",
  ui_story_5031_50310101_161_dialog_content = "If everything is as you say... then we can't afford to stand idly by.",
  ui_story_5031_50310101_162_dialog_content = "Do you have any clues to its whereabouts?",
  ui_story_5031_50310101_163_dialog_content = "Hmm... None at all! After my master dumped this assignment on me, he left without saying another word...",
  ui_story_5031_50310101_164_dialog_content = "So you had been wandering aimlessly around Harbor City this whole time until you found my trail? Then you just ambushed me here?",
  ui_story_5031_50310101_165_dialog_content = "You hit the nail right on the head, PlayerName! Not only that, but the money that Master gave me for travel expenses is all but spent...",
  ui_story_5031_50310101_166_dialog_content = "I don't know what to do if you didn't show up, PlayerName!",
  ui_story_5031_50310101_167_dialog_content = "I knew it.",
  ui_story_5031_50310101_168_dialog_content = "Why don't we start by gathering information? We were just on our way to visit the city laird.",
  ui_story_5031_50310101_169_dialog_content = "He might know a thing or two about the situation.",
  ui_story_5031_50310101_170_dialog_content = "Okay! I'd listen to Carleen. Let's go!",
  ui_story_5031_50310101_171_dialog_content = "Hey! Why bustle ahead, Fia? Do you even know where you're going?",
  ui_story_5031_50310101_172_dialog_content = "She's really pumped up, isn't she?",
  ui_story_5031_50310201_1_dialog_content = "Laird <color=#FFB400>Elvis</color>, the soldiers loyal to you are ready now.",
  ui_story_5031_50310201_2_dialog_content = "Things are proceeding just as you planned, sir. We will use the transportation of supplies and fireworks to Emerald as a cover.",
  ui_story_5031_50310201_3_dialog_content = "Yeah, I see.",
  ui_story_5031_50310201_4_dialog_content = "Well done, Captain Patou. Perhaps you really are the only one I can trust this time...",
  ui_story_5031_50310201_5_dialog_content = "As you say, sir. Please leave the rest to me. It's been a great honor serving my laird.",
  ui_story_5031_50310201_6_dialog_content = "Alas... If there were more time to wait, I wouldn't put you at such risk.",
  ui_story_5031_50310201_7_dialog_content = "Laird Elvis! Captain Patou! F-Forgive the intrusion!",
  ui_story_5031_50310201_8_dialog_content = "How rude... I thought I made it perfectly clear that none are allowed to enter?",
  ui_story_5031_50310201_9_dialog_content = "Y-Yes, Captain. Please forgive me, but a noble has come to visit...",
  ui_story_5031_50310201_10_dialog_content = "What noble? Compose yourself, soldier! You are in the service of the House Modali, now act like it!",
  ui_story_5031_50310201_11_dialog_content = "Understood! I-It's Lady Carleen, the Princess of Lumopolis, sir!",
  ui_story_5031_50310201_12_dialog_content = "What? Princess Carleen of Lumopolis, you say?",
  ui_story_5031_50310201_13_dialog_content = "According to Carleen, Harbor City came under Lumopolis' official jurisdiction and protection just before the Darkover Crisis.",
  ui_story_5031_50310201_14_dialog_content = "Does that mean they relied on their own strength to defend their home before then?",
  ui_story_5031_50310201_15_dialog_content = "Historical documents state that Harbor City was once teeming with Eclipsites. Those unfortunate residents fought day and night to keep it from falling to the Eclipsite scourge.",
  ui_story_5031_50310201_16_dialog_content = "Throughout the prolonged battle, the rulers from House <color=#FFB400>Modali</color>, who possessed immense Lumina, allied with other powerhouses.",
  ui_story_5031_50310201_17_dialog_content = "After countless, bloody battles, they were finally able to completely expel those invaders.",
  ui_story_5031_50310201_18_dialog_content = "Then...",
  ui_story_5031_50310201_19_dialog_content = "Blessed by the <color=#FFB400>God of Light</color>, this city has rarely been disturbed by Eclipsites ever since.",
  ui_story_5031_50310201_20_dialog_content = "The people now live their lives in peace, and the economy has flourished significantly.",
  ui_story_5031_50310201_21_dialog_content = "I am honored that you are so well-acquainted with Harbor City's history, Your Highness.",
  ui_story_5031_50310201_22_dialog_content = "I am also grateful to you and Lumopolis for your generous protection. After all, we would never have survived the Darkover Crisis depending on the <color=#FFB400>God of Light's blessing</color> alone.",
  ui_story_5031_50310201_23_dialog_content = "I am Elvis Modali, a descendant of the House Modali and laird of Harbor City.",
  ui_story_5031_50310201_24_dialog_content = "(Strange... Why is the Lumina around this man so faint?)",
  ui_story_5031_50310201_25_dialog_content = "Greetings, Laird Elvis. I pray that our visit hasn't caused you too much inconvenience.",
  ui_story_5031_50310201_26_dialog_content = "Of course not, Your Highness. I only wish you had sent word sooner, so that I could have properly received you and your companions.",
  ui_story_5031_50310201_27_dialog_content = "That won't be necessary, as we hoped to see you without the usual fanfare or formalities. Please don't be particular with us.",
  ui_story_5031_50310201_28_dialog_content = "After all, we have come to Harbor City not as delegates of any kind, but as ordinary travelers on holiday.",
  ui_story_5031_50310201_29_dialog_content = "Rest assured, Your Highness, I fully understand your plight. Might I assume that these two companions of yours are none other than Miss Vice and the legendary Caelestite?",
  ui_story_5031_50310201_30_dialog_content = "Greetings, I'm PlayerName.",
  ui_story_5031_50310201_31_dialog_content = "And I'm Vice, Laird Elvis. Though I never expected you to recognize PlayerName, much less myself.",
  ui_story_5031_50310201_32_dialog_content = "U-Um...!",
  ui_story_5031_50310201_33_dialog_content = "Oh? And who might this be?",
  ui_story_5031_50310201_34_dialog_content = "H-Hello! My name's Fia! I'm a professional extrozoologist, as well as a friend to PlayerName, Vice, and Carleen!",
  ui_story_5031_50310201_35_dialog_content = "An extrozoologist? Hehe, I see... A pleasure to meet you, Miss Fia.",
  ui_story_5031_50310201_36_dialog_content = "I've prepared a banquet. As laird of Harbor City, I'll be honored if you join me for a meal.",
  ui_story_5031_50310201_37_dialog_content = "I see... And are you quite interested in the event held aboard the <color=#FFB400>Emerald</color>, Miss Vice?",
  ui_story_5031_50310201_38_dialog_content = "Actually, I was the one who invited <color=#FFB400>the Illusionist & Old Bill's Circus</color> and the Emerald to Harbor City.",
  ui_story_5031_50310201_39_dialog_content = "My hope is that they can deliver an unforgettable experience to the people of my city this summer.",
  ui_story_5031_50310201_40_dialog_content = "Does the entire ship belong to the circus? It sure has a romantic feeling to it...",
  ui_story_5031_50310201_41_dialog_content = "Indeed. If you and your companions are interested, you could always consider taking part in the festivities.",
  ui_story_5031_50310201_42_dialog_content = "The ringmaster is a childhood friend of mine. Though we haven't seen each other for quite some time, he is as capable as he is trustworthy.",
  ui_story_5031_50310201_43_dialog_content = "I have no doubt that he will provide the very best entertainment for all of the city.",
  ui_story_5031_50310201_44_dialog_content = "Ah... The cruise ship!",
  ui_story_5031_50310201_45_dialog_content = "Um, excuse me! Could one of your friends show us the inside of the ship, Laird Elvis?",
  ui_story_5031_50310201_46_dialog_content = "Hmm?",
  ui_story_5031_50310201_47_dialog_content = "<size=33>Fia! What kind of odd request is that?</size>",
  ui_story_5031_50310201_48_dialog_content = "I just remembered Kyllo told me that a strange, enormous ship had docked in Harbor City not long ago.",
  ui_story_5031_50310201_49_dialog_content = "If the Cloudwhale did suddenly disappear, it could have been kept inside that kind of ship!",
  ui_story_5031_50310201_50_dialog_content = "My apologies, but I'm afraid I cannot grant you this request.",
  ui_story_5031_50310201_51_dialog_content = "Er... Why?",
  ui_story_5031_50310201_52_dialog_content = "I am unsure of the details myself, but this concerns one of the rules of the circus.",
  ui_story_5031_50310201_53_dialog_content = "Yesterday, I went aboard the ship to speak to <color=#FFB400>Jeno</color>, the ringmaster, about providing supplies to his troupe.",
  ui_story_5031_50310201_54_dialog_content = "I thought Jeno would give me a tour of the cabins, but he was only willing to show me as far as the corridor when discussing our business.",
  ui_story_5031_50310201_55_dialog_content = "Out of curiosity, I mentioned that I wished to see the inside of this grand and marvelous ship...",
  ui_story_5031_50310201_56_dialog_content = "But he refused me, stating that it was their policy that only members of the circus could go further into the cabin.",
  ui_story_5031_50310201_57_dialog_content = "As a friend and a business partner, this was as far as I was able to go. I fear entry for you will be even further out of the question.",
  ui_story_5031_50310201_58_dialog_content = "Is there any particular reason you would like to enter the ship? I may be able to negotiate with the ringmaster on your behalf.",
  ui_story_5031_50310201_59_dialog_content = "Actually, Fia was...",
  ui_story_5031_50310201_60_dialog_content = "Ahaha! That was out of curiosity as well! I come from a very small place, and I've never seen the inside of a ship before.",
  ui_story_5031_50310201_61_dialog_content = "<size=33>Don't forget, we're on a secret mission! We can't spill any information on our exotic objective!</size>",
  ui_story_5031_50310201_62_dialog_content = "I understand how you must feel, Miss Fia. After all, ships as large as the Emerald are not exactly commonplace, even in Harbor City.",
  ui_story_5031_50310201_63_dialog_content = "I'm certain you are not alone, either. Plenty of carnival-goers must be dying to know more about the ship and what lies within.",
  ui_story_5031_50310201_64_dialog_content = "Well... Allow me to try speaking with Jeno one more time.",
  ui_story_5031_50310201_65_dialog_content = "Really? Thank you so much, sir!",
  ui_story_5031_50310201_66_dialog_content = "My pleasure, though please try not to get your hopes up too high. Jeno was quick to turn down even his sponsor.",
  ui_story_5031_50310201_67_dialog_content = "However, there will be plenty of other festivities to take part in on the deck, such as the cooking contest, carnival, and circus show.",
  ui_story_5031_50310201_68_dialog_content = "I believe they will go far in satisfying your curiosity as well, Miss Fia.",
  ui_story_5031_50310201_69_dialog_content = "*Coughs*",
  ui_story_5031_50310201_70_dialog_content = "Sir!",
  ui_story_5031_50310201_71_dialog_content = "I'm fine, Patou.",
  ui_story_5031_50310201_72_dialog_content = "It appears that in the excitement of Her Highness and everyone's visit, I completely forgot to take my medicine.",
  ui_story_5031_50310201_73_dialog_content = "Laird Elvis...",
  ui_story_5031_50310201_74_dialog_content = "Thank you for your gracious hospitality.",
  ui_story_5031_50310201_75_dialog_content = "The honor is mine, Your Highness. I do hope that my momentary lapse in health didn't spoil your enjoyment.",
  ui_story_5031_50310201_76_dialog_content = "Not at all. Please do take good care of yourself, Laird.",
  ui_story_5031_50310201_77_dialog_content = "We're going to the Emerald shortly to see the carnival. Please don't get up for our sakes. We'll be on our way.",
  ui_story_5031_50310201_78_dialog_content = "... I understand. However, I've got to prepare a gift for Your Highness before I depart for the Emerald later.",
  ui_story_5031_50310201_79_dialog_content = "It is customary for subjects to offer gifts to their sovereigns. Please kindly accept it, Your Highness.",
  ui_story_5031_50310201_80_dialog_content = "If you insist.",
  ui_story_5031_50310201_81_dialog_content = "Come, everyone. It's time to go.",
  ui_story_5031_50310201_82_dialog_content = "...",
  ui_story_5031_50310201_83_dialog_content = "Sir.",
  ui_story_5031_50310201_84_dialog_content = "Order our men to prepare themselves, Patou.",
  ui_story_5031_50310201_85_dialog_content = "Could... Could Lumopolis have discovered our actions so quickly?",
  ui_story_5031_50310201_86_dialog_content = "I believe it's still too early to say for certain... But for now, we must keep a watchful eye on them.",
  ui_story_5031_50310201_87_dialog_content = "No matter what happens, the plan must proceed today.",
  ui_story_5031_50310201_88_dialog_content = "Forgive my ignorance, sir, but can you not simply ask Ringmaster Jeno for his assistance?",
  ui_story_5031_50310201_89_dialog_content = "As you said, he is your childhood friend.",
  ui_story_5031_50310201_90_dialog_content = "Things are not quite so simple, Patou. Our shared history does not necessarily mean I can trust him.",
  ui_story_5031_50310201_91_dialog_content = "After all, he denied my request to see the inside of his ship without hesitation.",
  ui_story_5031_50310201_92_dialog_content = "According to my findings, he currently owes his allegiance to the <color=#FFB400>True Order</color>.",
  ui_story_5031_50310201_93_dialog_content = "If our objective is revealed due to our recklessness... the entire plan may very well fall apart in an instant.",
  ui_story_5031_50310201_94_dialog_content = "At this point, I'm unsure whether or not I can trust that man, whom I once called a \"friend\"...",
  ui_story_5031_50310201_95_dialog_content = "I understand, sir. Leave it to me.",
  ui_story_5031_50310201_96_dialog_content = "Very well. I will continue looking into Jeno to see if he's still the same person I once knew...",
  ui_story_5031_50310201_97_dialog_content = "Laird Elvis seems like a really nice person, huh? He welcomed us so warmly and was also kind to Vice and me.",
  ui_story_5031_50310201_98_dialog_content = "Yeah, he seems much kinder than some of the nobles we've met before. He doesn't carry himself with the same kind of pretentiousness as they do.",
  ui_story_5031_50310201_99_dialog_content = "Indeed. The House Modali is quite different than many other noble families. They're incredibly protective of their own people, and are also beloved by many.",
  ui_story_5031_50310201_100_dialog_content = "When it comes to governance, their family is one of the best, but unfortunately...",
  ui_story_5031_50310201_101_dialog_content = "Ah... Does it have something to do with how weak his Lumina is?",
  ui_story_5031_50310201_102_dialog_content = "It seems you noticed it, as well. When Elvis started coughing uncontrollably earlier... well, let's just say it wasn't due to a common cold.",
  ui_story_5031_50310201_103_dialog_content = "Even the scar on his face... His disease is known to others as the <color=#FFB400>Modali Syndrome</color>.",
  ui_story_5031_50310201_104_dialog_content = "So the scar on his face is due to his illness? I never would have guessed...",
  ui_story_5031_50310201_105_dialog_content = "Then... Is it serious?",
  ui_story_5031_50310201_106_dialog_content = "I don't understand much about the disease beyond its name, to be honest. I only came to know of it in passing, while I was engaged in my history studies.",
  ui_story_5031_50310201_107_dialog_content = "When I gave in to my curiosity, I quickly found that information regarding the Modali Syndrome and the family itself was astonishingly scarce.",
  ui_story_5031_50310201_108_dialog_content = "All I learned is that this disease quickly saps the Lumina of victims and prevents it from recovering to normal levels for a prolonged period of time.",
  ui_story_5031_50310201_109_dialog_content = "It's not as debilitating for those with above-average levels of Lumina, but for others... contracting the disease quickly and severely impairs their ability to lead normal lives.",
  ui_story_5031_50310201_110_dialog_content = "In extreme cases, the disease can even be fatal.",
  ui_story_5031_50310201_111_dialog_content = "Is it really that bad?!",
  ui_story_5031_50310201_112_dialog_content = "Yes... But this disease is extremely unique and has only ever appeared in Harbor City. As such, scholars believe that it is somehow bound to this region.",
  ui_story_5031_50310201_113_dialog_content = "The people of Harbor City, on the other hand, are entirely convinced that the disease is a symbol of their <color=#FFB400>heroic bloodline</color>.",
  ui_story_5031_50310201_114_dialog_content = "They say that their ancestors, the ones who fended off the Eclipsites in the past, bravely and willingly bore this curse for the sake of their people.",
  ui_story_5031_50310201_115_dialog_content = "As such, their descendants also have a chance to contract it.",
  ui_story_5031_50310201_116_dialog_content = "Fortunately, it seems confirmed cases of this disease have been gradually diminishing over recent years.",
  ui_story_5031_50310201_117_dialog_content = "Oh... I see, I see.",
  ui_story_5031_50310201_118_dialog_content = "You don't have to pretend you understood all of that, you know?",
  ui_story_5031_50310201_119_dialog_content = "O-Of course I understood it! Just because I'm young doesn't mean I'm dumb!",
  ui_story_5031_50310201_120_dialog_content = "In any case, I think the laird understands his own destiny better than anyone else.",
  ui_story_5031_50310201_121_dialog_content = "Just like me—I'm born to be the world's greatest extrozoologist!",
  ui_story_5031_50310201_122_dialog_content = "Carrying on the glory of countless generations past... It must be a complicated and heavy burden to bear.",
  ui_story_5031_50310201_123_dialog_content = "As outsiders, I don't think we have a right to judge the situation at all.",
  ui_story_5031_50310201_124_dialog_content = "Fia makes a very good point.",
  ui_story_5031_50310201_125_dialog_content = "Yeah, she does, although she could have made the same point by not saying anything at all, too.",
  ui_story_5031_50310201_126_dialog_content = "Hehe! In any case, we should really focus on getting aboard the Emerald and taking a look around. Come on, let's go!",
  ui_story_5031_50310201_127_dialog_content = "Hurry up and save the exotic. Complete this quest and I will have time to play!",
  ui_story_5031_50310201_128_dialog_content = "Hold on a second, Fia! What makes you so certain you'll be able to access the inside of the Emerald, anyway?",
  ui_story_5031_50310201_129_dialog_content = "I'll just have to rely on my amazing charm, won't I?",
  ui_story_5031_50310201_130_dialog_content = "What \"amazing charm\"... You'd have better luck pretending to be a small animal and auditioning for the circus.",
  ui_story_5031_50310201_131_dialog_content = "Ugh!",
  ui_story_5031_50310201_132_dialog_content = "That was another short joke, wasn't it?!",
  ui_story_5031_50310201_133_dialog_content = "Get over here!",
  ui_story_5031_50310201_134_dialog_content = "H-Hey, that hurt! Quit pulling so hard, Fia!",
  ui_story_5031_50310201_135_dialog_content = "You're going right into the ocean, you big jerk! Kyllo can toss you around like a ball, for all I care!",
  ui_story_5031_50310201_136_dialog_content = "What? Are you calling Kyllo a seal or something? I don't think Kyllo would appreciate that!",
  ui_story_5031_50310201_137_dialog_content = "I don't care!",
  ui_story_5031_50310201_138_dialog_content = "Whew... Seeing them argue like that somehow puts me more at ease.",
  ui_story_5031_50310201_139_dialog_content = "Yeah... We haven't gotten to relax like this in a while.",
  ui_story_5031_50310201_140_dialog_content = "Wait!",
  ui_story_5031_50310201_141_dialog_content = "A-Alright, cut it out! What is it, Carleen?",
  ui_story_5031_50310201_142_dialog_content = "Over there... What are Eclipsites doing on this seashore?!",
  ui_story_5031_50310201_143_dialog_content = "Prepare for battle, and stay on your guard, everyone! Something's strange about these Eclipsites...",
  ui_story_5031_50310202_1_dialog_content = "Graah...",
  ui_story_5031_50310202_2_dialog_content = "Why were these Eclipsites so weak...?",
  ui_story_5031_50310202_3_dialog_content = "You lot, are you alright?",
  ui_story_5031_50310202_4_dialog_content = "Wait... Y-You're Princess Carleen! M-My apologies if you've been injured... It was because of my negligence that those Eclipsites made it through!",
  ui_story_5031_50310202_5_dialog_content = "There's no need to panic. We are not unarmed citizens and are perfectly capable of defending ourselves.",
  ui_story_5031_50310202_6_dialog_content = "Nonetheless, you and your men need to remain vigilant at all times. Danger could be lurking around every corner.",
  ui_story_5031_50310202_7_dialog_content = "Understood! Thank you for your guidance, Your Highness! We will increase our patrols, as well as investigate the origin of these Eclipsites!",
  ui_story_5031_50310202_8_dialog_content = "Very good, now get to work, soldier.",
  ui_story_5031_50310202_9_dialog_content = "Yes, Your Highness!",
  ui_story_5031_50310202_10_dialog_content = "That was so cool, Carleen! You looked and sounded just like a queen!",
  ui_story_5031_50310202_11_dialog_content = "Of course she did, Fia! Carleen is the daughter of the Lord of Lumopolis, and naturally she's going to make a wise ruler one day.",
  ui_story_5031_50310202_12_dialog_content = "Th-Thank you... But I still have much to learn.",
  ui_story_5031_50310202_13_dialog_content = "But enough about that. The Emerald is just up ahead, so let's keep moving.",
  ui_story_5031_50310202_14_dialog_content = "Anyone who would like to participate in the cooking contest, come this way!",
  ui_story_5031_50310202_15_dialog_content = "Looks like we're here, huh? This place sure is lively!",
  ui_story_5031_50310202_16_dialog_content = "Let's start by gathering information first, PlayerName.",
  ui_story_5031_50310202_17_dialog_content = "Yeah, that makes sense.",
  ui_story_5031_50310202_18_dialog_content = "Hello, could I ask you about the carnival...?",
  ui_story_5031_50310202_19_dialog_content = "Yo! Welcome to the Illusionist & Old Bill's Circus!",
  ui_story_5031_50310202_20_dialog_content = "Looks like this is your first time seeing our circus, am I right? No need to be shy, you guys! Right this way!",
  ui_story_5031_50310202_21_dialog_content = "Just don't make any trouble aboard the ship, okay? I won't be so nice if you start causing a ruckus...",
  ui_story_5031_50310202_22_dialog_content = "Come on, Merylt! Ringmaster Jeno posted us here to welcome guests, so no slacking off!",
  ui_story_5031_50310202_23_dialog_content = "Here, here. Looks like someone's coming in now, and he's just your type! Why don't you say hello, Merylt?",
  ui_story_5031_50310202_24_dialog_content = "Ahh! Subli, don't push me...",
  ui_story_5031_50310202_25_dialog_content = "Say, he sure looks like him, doesn't he? Merylt, go take a closer look!",
  ui_story_5031_50310202_26_dialog_content = "Huh? Looks like who? What are you two going on about?",
  ui_story_5031_50310202_27_dialog_content = "He looks like the guy on that poster from Umbraton Daily! The one Merylt stashed away for herself!",
  ui_story_5031_50310202_28_dialog_content = "Er... What exactly are you talking about?",
  ui_story_5031_50310202_29_dialog_content = "Wait, they look much alike! You're not that Caelestite by any chance, are you?",
  ui_story_5031_50310202_30_dialog_content = "Y-Yeah, actually I am... But how do you three know about me?",
  ui_story_5031_50310202_31_dialog_content = "!!",
  ui_story_5031_50310202_32_dialog_content = "Why's Merylt running off, Subli?",
  ui_story_5031_50310202_33_dialog_content = "Should we detain this guy now?",
  ui_story_5031_50310202_34_dialog_content = "Wh-What?!",
  ui_story_5031_50310202_35_dialog_content = "Hahaha, what fun! Take it easy, Frimet. Let's leave them to Rainbow. For now, just go find Merylt, okay?",
  ui_story_5031_50310202_36_dialog_content = "Hey! Are you loafing around again?",
  ui_story_5031_50310202_37_dialog_content = "Sorry about that, folks! Those three are just helping out for the time being.",
  ui_story_5031_50310202_38_dialog_content = "You must be here for the carnival, I take it?",
  ui_story_5031_50310202_39_dialog_content = "Allow me to introduce myself. I'm Rainbow, the circus emcee, customer liaison, security director, and marine engineer apprentice!",
  ui_story_5031_50310202_40_dialog_content = "Th-That's quite a mouthful...",
  ui_story_5031_50310202_41_dialog_content = "Heehee! That's why everyone thinks I'm so amazing, you know?",
  ui_story_5031_50310202_42_dialog_content = "Nice to meet you, Rainbow! Can you please tell me how to get inside the ship—Ooh!",
  ui_story_5031_50310202_43_dialog_content = "What are you doing? You really think she's going to let you in just because you asked?",
  ui_story_5031_50310202_44_dialog_content = "B-But what are we supposed to do, then?",
  ui_story_5031_50310202_45_dialog_content = "Hello. We just wanted to know more about the carnival, and how best to enjoy it.",
  ui_story_5031_50310202_46_dialog_content = "Well, the carnival is still getting ready at the moment. It's just fine to hang out on the deck and wait for the signal.",
  ui_story_5031_50310202_47_dialog_content = "For now, I invite all of you to go check out the cooking contest being hosted nearby!",
  ui_story_5031_50310202_48_dialog_content = "A fierce contest is about to take place, and there are plenty of wonderful food stalls to visit!",
  ui_story_5031_50310202_49_dialog_content = "Walk that way, and you won't miss it!",
  ui_story_5031_50310202_50_dialog_content = "Thank you for your time. We'll go take a look around.",
  ui_story_5031_50310202_51_dialog_content = "Those circus members were pretty special, weren't they?",
  ui_story_5031_50310202_52_dialog_content = "Especially those three sisters... They seemed much interested in PlayerName.",
  ui_story_5031_50310202_53_dialog_content = "Really...? I'd prefer not to get caught up with strange people...",
  ui_story_5031_50310202_54_dialog_content = "I can't help but think things have been getting way too crazy around me. I'm looking forward to a bit of rest and relaxation.",
  ui_story_5031_50310202_55_dialog_content = "Hmm. What do I have to do to get inside this ship?",
  ui_story_5031_50310202_56_dialog_content = "I really thought I had convinced that kind lady.",
  ui_story_5031_50310202_57_dialog_content = "So you don't think a little too much honesty would get you thrown overboard instead?",
  ui_story_5031_50310202_58_dialog_content = "Don't forget what Elvis said—the interior of the ship is reserved for the circus folk.",
  ui_story_5031_50310202_59_dialog_content = "The best place for us to start looking is above decks. Who knows... we might find something.",
  ui_story_5031_50310202_60_dialog_content = "Hold on a second... that stall just a little further on... I can make out some familiar faces there.",
  ui_story_5031_50310202_61_dialog_content = "It's my joy to present one of the world's finest ways of dissipating this ferocious summer heat.",
  ui_story_5031_50310202_62_dialog_content = "Including our latest flavor—<color=#FFB400>Limited Edition Harbor City Breeze</color>.",
  ui_story_5031_50310202_63_dialog_content = "We will further reward any purchase of ten cups of shaved ice with a special thermal bag lovingly engraved with a picture of a Caelestite!",
  ui_story_5031_50310202_64_dialog_content = "Very well. Your ten cups of shaved ice and the thermal bag, beautiful lady.",
  ui_story_5031_50310202_65_dialog_content = "I'm the one who invented this particular style of shaved ice! And I can't believe Kleken used your picture for the bag!",
  ui_story_5031_50310202_66_dialog_content = "Vice... Surely you recall that \"<color=#FFB400>Transfer of Trade Secret</color>\" you signed with Kleken last year?",
  ui_story_5031_50310202_67_dialog_content = "I very much fear this is the result.",
  ui_story_5031_50310202_68_dialog_content = "Uh-oh... it's too sweet.",
  ui_story_5031_50310202_69_dialog_content = "It doesn't have the complexity of Vice's shaved ice.",
  ui_story_5031_50310202_70_dialog_content = "I-I would like a cup too!",
  ui_story_5031_50310202_71_dialog_content = "Say, you just can't help yourself, can you?",
  ui_story_5031_50310202_72_dialog_content = "Vice is still very much in the doldrums with her sad tale of intellectual property transfer.",
  ui_story_5031_50310202_73_dialog_content = "I-I'm totally fine with it... I'm just happy, however it happened, that everyone now gets the chance to enjoy some delicious shaved ice and I just... I just want...",
  ui_story_5031_50310202_74_dialog_content = "I'll get Kleken to transfer that intellectual property back to me!",
  ui_story_5031_50310202_75_dialog_content = "<color=#e8d9bb>A short while later</color>",
  ui_story_5031_50310202_76_dialog_content = "Wow! Real icy.",
  ui_story_5031_50310202_77_dialog_content = "Don't have it all at once or you'll get a brain freeze!",
  ui_story_5031_50310202_78_dialog_content = "Is Vice still talking to Kleken? Are they okay?",
  ui_story_5031_50310202_79_dialog_content = "PlayerName!",
  ui_story_5031_50310202_80_dialog_content = "Eh? What's that familiar voice?",
  ui_story_5031_50310202_81_dialog_content = "PlayerName, I can't believe it really is you!",
  ui_story_5031_50310202_82_dialog_content = "Fleur, what are you doing here?",
  ui_story_5031_50310202_83_dialog_content = "Oh? You're not here to take part in the Sorcery Pot Championship? It's a gourmet competition festival thingy. Should be starting real soon.",
  ui_story_5031_50310202_84_dialog_content = "And I'd also like to thank you for your help with those baked bread back then.",
  ui_story_5031_50310202_85_dialog_content = "I had a bit of a think. And I've decided to take part in the competition. There's no better way to improve and to get my unique style out there.",
  ui_story_5031_50310202_86_dialog_content = "Uh, you're welcome. I have to say I hadn't heard anything about this gourmet competition until now. What was it called again? \"<color=#FFB400>Sorcery Pot</color>\"?",
  ui_story_5031_50310202_87_dialog_content = "Hold on! Is that a reference to that Iron Chef guy from Rediesel Desert?",
  ui_story_5031_50310202_88_dialog_content = "The Eclipsite connoisseur, Uncle Johnny? The very same! And that Sorcery Pot he uses!",
  ui_story_5031_50310202_89_dialog_content = "Hang on. Who is this \"Uncle Johnny\" character, Carleen?",
  ui_story_5031_50310202_90_dialog_content = "Just a very popular food critic who lives way out in the Rediesel Desert. I don't know much more than that.",
  ui_story_5031_50310202_91_dialog_content = "What's got you so into this?",
  ui_story_5031_50310202_92_dialog_content = "He's not just any old two-bit restaurant critic! He invented the most famous dishes across this whole continent in that pot!",
  ui_story_5031_50310202_93_dialog_content = "D-Do you think Uncle Johnny will take part in the Championship himself?",
  ui_story_5031_50310202_94_dialog_content = "Oh, no, a chef of his stature surely has better things to do than... hold on—is his signature pot up for grabs too?",
  ui_story_5031_50310202_95_dialog_content = "Exactly right! The first prize winner gets nothing less than the masterchef's very own Sorcery Pot!",
  ui_story_5031_50310202_96_dialog_content = "I've got no idea whether the man himself will be there, but I'm sure a prize like that will attract all-stars from around the world!",
  ui_story_5031_50310202_97_dialog_content = "And I want to join in! Can I? Will they let me?",
  ui_story_5031_50310202_98_dialog_content = "Get that magic pot in Vice's hands, and it's going to be wonderful for all of us on the Colossus!",
  ui_story_5031_50310202_99_dialog_content = "Oh! But don't go too crazy on me, PlayerName. Who knows what's going to happen?",
  ui_story_5031_50310202_100_dialog_content = "I'm sorry, Fleur. I just need to have a word with PlayerName quietly.",
  ui_story_5031_50310202_101_dialog_content = "Don't be so pushy, Carleen, Fia.",
  ui_story_5031_50310202_102_dialog_content = "Hey! Fleur, wait for me! I'm coming back!",
  ui_story_5031_50310202_103_dialog_content = "Alright. I'll be waiting.",
  ui_story_5031_50310202_104_dialog_content = "I'll be waiting for you right here, PlayerName!",
  ui_story_5031_50310202_105_dialog_content = "PlayerName, let's not get ahead of ourselves, ok?",
  ui_story_5031_50310202_106_dialog_content = "I'm sorry. I guess I went a bit overboard there.",
  ui_story_5031_50310202_107_dialog_content = "You said it. I think somebody really, really wants to get their hands on that magic pot, PlayerName.",
  ui_story_5031_50310202_108_dialog_content = "What are you doing here? I finally found you!",
  ui_story_5031_50310202_109_dialog_content = "Vice? How did your discussion with Kleken go?",
  ui_story_5031_50310202_110_dialog_content = "A miserable failure! My only consolation is I managed to get my hands on quite a few free cups of shaved ice for y'all!",
  ui_story_5031_50310202_111_dialog_content = "Have at them, friends! Let these icy desserts cleanse away the sense of failure! *Munching*",
  ui_story_5031_50310202_112_dialog_content = "I don't think Vice had a very good time of it... *Munching*",
  ui_story_5031_50310202_113_dialog_content = "Argh. Brain freeze!",
  ui_story_5031_50310202_114_dialog_content = "That's what happens when you eat it all at once, you know. Ow... I got it too.",
  ui_story_5031_50310202_115_dialog_content = "Eh? See that ladder over there pointing down? Don't tell me that was the entrance to the lower decks all along?",
  ui_story_5031_50310202_116_dialog_content = "Eh? Let me have a look.",
  ui_story_5031_50310202_117_dialog_content = "I think it really is... Well? Should we go down?",
  ui_story_5031_50310202_118_dialog_content = "You mean you don't see a problem with breaking and entering?",
  ui_story_5031_50310202_119_dialog_content = "If we're talking about the same evildoers who kidnapped the Cloudwhale, they're not exactly going to roll out the welcome mat.",
  ui_story_5031_50310202_120_dialog_content = "At the end of the day, we gotta try.",
  ui_story_5031_50310202_121_dialog_content = "Knock-knock. Sorry for the intrusion. Please let me in!",
  ui_story_5031_50310202_122_dialog_content = "Did you just literally say \"knock-knock\"?",
  ui_story_5031_50310202_123_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5031_50310202_124_dialog_content = "Ahh!",
  ui_story_5031_50310202_125_dialog_content = "Who is it?!",
  ui_story_5031_50310202_126_dialog_content = "Oh, I'm sorry! Fellow tourists passing through!",
  ui_story_5031_50310202_127_dialog_content = "Another group of lost souls, I take it? Ready to throw everything to the wind for a chance to enter this door?",
  ui_story_5031_50310202_128_dialog_content = "Alternatively, you can just get out of here.",
  ui_story_5031_50310202_129_dialog_content = "Uh?",
  ui_story_5031_50310202_130_dialog_content = "What I mean is that the lower decks are off-limits to passengers!",
  ui_story_5031_50310202_131_dialog_content = "Please make your way back.",
  ui_story_5031_50310202_132_dialog_content = "Oh, sorry! We'll be leaving now.",
  ui_story_5031_50310202_133_dialog_content = "What do you know... It ain't that easy to walk in.",
  ui_story_5031_50310202_134_dialog_content = "This is a conundrum... no doubt about it.",
  ui_story_5031_50310202_135_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5031_50310202_136_dialog_content = "\"Attention all passengers! The preparations for the carnival competition have recently been completed.\"",
  ui_story_5031_50310202_137_dialog_content = "\"Would all interested participants please make their way to the designated area for sign-up and registration.\"",
  ui_story_5031_50310202_138_dialog_content = "\"Participants stand to receive a significant Nightium reward as well as a chance to experience a day in the life of a circus member.\"",
  ui_story_5031_50310202_139_dialog_content = "\"The first prize winner also stands to receive a grand prize personally at the hands of the ringmaster.\"",
  ui_story_5031_50310202_140_dialog_content = "What do you think? A day in the life of a circus member could also mean a day of access to the lower decks.",
  ui_story_5031_50310202_141_dialog_content = "Not a bad idea, if I do say so.",
  ui_story_5031_50310202_142_dialog_content = "Come on, let's take a closer look.",
  ui_story_5031_50310202_143_dialog_content = "My, my, I'd never have guessed. What a crowd!",
  ui_story_5031_50310202_144_dialog_content = "Tsk... They're like a horde of locusts swarming me.",
  ui_story_5031_50310202_145_dialog_content = "What is a respectable judge like myself, Justice Matthieu, doing amongst this riffraff?",
  ui_story_5031_50310202_146_dialog_content = "...",
  ui_story_5031_50310202_147_dialog_content = "Go disturb somebody else!",
  ui_story_5031_50310202_148_dialog_content = "Tsk. This commotion's no good for my delicate humor. I'm even getting short with you, Loewe.",
  ui_story_5031_50310202_149_dialog_content = "Carleen, I think those two are from Lumopolis.",
  ui_story_5031_50310202_150_dialog_content = "They're from the Hall of Justice, maybe... but who cares.",
  ui_story_5031_50310202_151_dialog_content = "Vice! PlayerName and Carleen! And...?",
  ui_story_5031_50310202_152_dialog_content = "Officer Gronru! This is...",
  ui_story_5031_50310202_153_dialog_content = "I'm Fia, an extrozoologist. Pleased to make your acquaintance!",
  ui_story_5031_50310202_154_dialog_content = "Wonderful. I hope you've been a good influence on little kids, Caelestite?",
  ui_story_5031_50310202_155_dialog_content = "What are you looking at me for?!",
  ui_story_5031_50310202_156_dialog_content = "So what do we owe the pleasure, Officer Gronru?",
  ui_story_5031_50310202_157_dialog_content = "I just came on a hunch that the show would be entertaining—alongside your dear schoolmate—",
  ui_story_5031_50310202_158_dialog_content = "C-Ce... U-Um, hi, I'm Ciel... Vice's former classmate.",
  ui_story_5031_50310202_159_dialog_content = "Ce?",
  ui_story_5031_50310202_160_dialog_content = "Long time no see! Actually, it's been far too long. Haven't seen much of you since I started working with PlayerName.",
  ui_story_5031_50310202_161_dialog_content = "Ciel is quite shy. That's her nervous tic—the \"ce.\"",
  ui_story_5031_50310202_162_dialog_content = "But who cares about that, right? We used to call her an absolute genius when it comes to anything to do with engineering, right?",
  ui_story_5031_50310202_163_dialog_content = "Fair enough. A smart person who's steady is hard to find.",
  ui_story_5031_50310202_164_dialog_content = "Officer Gronru, Miss Ciel, are you here for fun?",
  ui_story_5031_50310202_165_dialog_content = "No, no! I wouldn't be wearing this stuffy outfit if I was going to enjoy the carnival.",
  ui_story_5031_50310202_166_dialog_content = "Don't tell me that my esteemed Caelestite hasn't figured it out? Or you, Vice?",
  ui_story_5031_50310202_167_dialog_content = "Have you mentioned the size of this prodigious ship? Consider the complexity of its structure and manufacture!",
  ui_story_5031_50310202_168_dialog_content = "I took the first opportunity I could to drag Ciel along to investigate this work of engineering art.",
  ui_story_5031_50310202_169_dialog_content = "What a shame we haven't managed to find a way onto the lower decks! A simple survey of the exterior cannot provide enough insights.",
  ui_story_5031_50310202_170_dialog_content = "All of which must inexorably lead us now to join the competition ourselves!",
  ui_story_5031_50310202_171_dialog_content = "So, Vice, are you going to help Officer Gronru and her friend?",
  ui_story_5031_50310202_172_dialog_content = "That's quite alright. I don't want to interfere with the machinations of \"Team Colossus.\" And I believe the organizers are quite flexible about team sizes.",
  ui_story_5031_50310202_173_dialog_content = "And I fully believe that Ciel's abilities are no inferior to my esteemed friend, Vice's!",
  ui_story_5031_50310202_174_dialog_content = "I, uh, I'll do my best!",
  ui_story_5031_50310202_175_dialog_content = "Well then, time to ready ourselves for this delightful up-and-coming romp! We'll see you shortly.",
  ui_story_5031_50310202_176_dialog_content = "Oh my. We're lining up tough opponents already, I see...",
  ui_story_5031_50310202_177_dialog_content = "Why are they so slow to announce the details?",
  ui_story_5031_50310202_178_dialog_content = "Oh, I think I just saw two people get up on the stage.",
  ui_story_5031_50310202_179_dialog_content = "Is that Laird Elvis? And there's another figure, all in black?",
  ui_story_5031_50310202_180_dialog_content = "Ahem.",
  ui_story_5031_50310202_181_dialog_content = "Welcome, one and all! My beloved fellow citizens of Harbor City and travelers far and wide!",
  ui_story_5031_50310202_182_dialog_content = "I am the laird of Harbor City, Elvis Modali.",
  ui_story_5031_50310202_183_dialog_content = "Laird Elvis!",
  ui_story_5031_50310202_184_dialog_content = "Elvis Modali! Elvis Modali!",
  ui_story_5031_50310202_185_dialog_content = "Thank you. And it is my honor and privilege to invite a true legend of the seas with us on this summer's day—",
  ui_story_5031_50310202_186_dialog_content = "The legendary Illusionist & Old Bill's Circus will be delivering another spectacular performance in this carnival!",
  ui_story_5031_50310202_187_dialog_content = "I'm the ringmaster of the Illusionist & Old Bill's Circus, Jeno Gallacher. Thank you, all, for the warm welcome.",
  ui_story_5031_50310202_188_dialog_content = "In view of fairness, it'll be my custom in today's proceedings to deliver the rules before each challenge.",
  ui_story_5031_50310202_189_dialog_content = "Competitors to pass all challenges will not only get to experience a day in the life of a circus member...",
  ui_story_5031_50310202_190_dialog_content = "But will also receive a special and precious gift prepared personally by myself.",
  ui_story_5031_50310202_191_dialog_content = "As is often and rightly believed, a circus troupe is also a storehouse of many extraordinary trinkets.",
  ui_story_5031_50310202_192_dialog_content = "And, to tell you the truth, the circus I manage is no exception!",
  ui_story_5031_50310202_193_dialog_content = "Our long voyages in search of wonder have been blessed in very physical, extraordinary ways.",
  ui_story_5031_50310202_194_dialog_content = "As well as the manifold treasures bestowed by the ocean itself—that is to say, the ultimate grand prize of this carnival!",
  ui_story_5031_50310202_195_dialog_content = "Feel free to imagine this exotic treasure. Expect it eagerly. You will not be disappointed!",
  ui_story_5031_50310202_196_dialog_content = "Wow! Sounds super valuable!",
  ui_story_5031_50310202_197_dialog_content = "We're gonna be rich!",
  ui_story_5031_50310202_197X1_dialog_content = "An exotic treasure granted by the sea... I know!",
  ui_story_5031_50310202_197X2_dialog_content = "That must be the Cloud—Whoops!",
  ui_story_5031_50310202_197X3_dialog_content = "Shush! Be quiet. Do you want more opponents to know its true identity and fight us for it?",
  ui_story_5031_50310202_197X4_dialog_content = "Oops, I understand. Then we'll rely on ourselves to win the match and save the Cloudwhale!",
  ui_story_5031_50310202_198_dialog_content = "Also, I hardly think you would be impressed if we had but a single judge for our competition.",
  ui_story_5031_50310202_199_dialog_content = "So, it's my great pleasure to invite the great leader of Harbor City, Laird Elvis, to co-judge with me!",
  ui_story_5031_50310202_200_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310202_201_dialog_content = "Uh...? Jeno? Is this something we should have discussed first?",
  ui_story_5031_50310202_202_dialog_content = "Is there a problem, sir? I would have thought you'd be grateful for a chance to enjoy what any man in your position should be able to!",
  ui_story_5031_50310202_203_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310202_204_dialog_content = "I... see.",
  ui_story_5031_50310202_205_dialog_content = "We trust that you'll enjoy the events to your hearts' content, everyone!",
  ui_story_5031_50310301_0_dialog_content = "Um, so this lace should go in here...",
  ui_story_5031_50310301_0X1_dialog_content = "Huh? How come there's another lace?",
  ui_story_5031_50310301_0X2_dialog_content = "This one... Uh, should it go through the other side?",
  ui_story_5031_50310301_0X3_dialog_content = "Thanks for helping, Vice.",
  ui_story_5031_50310301_0X4_dialog_content = "No problem. Just hang on and give me a second to figure this out.",
  ui_story_5031_50310301_0X5_dialog_content = "Take your time. I'm not in a hurry.",
  ui_story_5031_50310301_0X6_dialog_content = "Um, it should be this way, right?",
  ui_story_5031_50310301_0X7_dialog_content = "Hmm, maybe not...",
  ui_story_5031_50310301_0X8_dialog_content = "... Vice.",
  ui_story_5031_50310301_0X9_dialog_content = "Hm? What is it? Did I hurt you?",
  ui_story_5031_50310301_0X10_dialog_content = "No. It's just... Can I ask you something personal?",
  ui_story_5031_50310301_0X11_dialog_content = "Personal?",
  ui_story_5031_50310301_0X12_dialog_content = "Yeah... I'd like to know how you felt... when you got your new power.",
  ui_story_5031_50310301_0X13_dialog_content = "Oh, I see... That's not personal at all!",
  ui_story_5031_50310301_0X14_dialog_content = "Lift your right elbow a little bit.",
  ui_story_5031_50310301_0X15_dialog_content = "Alright.",
  ui_story_5031_50310301_0X16_dialog_content = "Mm... It's actually kinda hard to answer that.",
  ui_story_5031_50310301_0X17_dialog_content = "It's not that I don't want to... It's just hard to describe.",
  ui_story_5031_50310301_0X18_dialog_content = "I understand.",
  ui_story_5031_50310301_0X19_dialog_content = "To me, it felt like a hidden potential of mine was being unlocked.",
  ui_story_5031_50310301_0X20_dialog_content = "I felt Lumina in a different way than before, yet this new thing was accompanied by risks.",
  ui_story_5031_50310301_0X21_dialog_content = "Risks?",
  ui_story_5031_50310301_0X22_dialog_content = "Yeah, I was in a sort of coma during the process. I thought I'd never wake up.",
  ui_story_5031_50310301_0X23_dialog_content = "I kept holding fast to the image of the old me, afraid I'd lose myself if I relaxed even for a second.",
  ui_story_5031_50310301_0X24_dialog_content = "I saw a lot of marvelous things, too, I experienced them as if I was there.",
  ui_story_5031_50310301_0X25_dialog_content = "Those illusions felt so real, like a test for me.",
  ui_story_5031_50310301_0X26_dialog_content = "Luckily, I clung to a gleam of consciousness and preserved to the end.",
  ui_story_5031_50310301_0X27_dialog_content = "I see. So, a process of unlocking your potential, huh...",
  ui_story_5031_50310301_0X28_dialog_content = "Yeah, that's what I consider it.",
  ui_story_5031_50310301_0X29_dialog_content = "Actually, many Aurorians gain such breakthroughs in a crisis.",
  ui_story_5031_50310301_0X30_dialog_content = "I guess that's what happened to me.",
  ui_story_5031_50310301_0X31_dialog_content = "But even now, I still can't master this new strength completely.",
  ui_story_5031_50310301_0X32_dialog_content = "That's probably because it's still new to you. You will, given time.",
  ui_story_5031_50310301_0X33_dialog_content = "That's true!",
  ui_story_5031_50310301_0X34_dialog_content = "If you want to try it, maybe you can start with releasing your consciousness?",
  ui_story_5031_50310301_0X35_dialog_content = "Releasing my consciousness?",
  ui_story_5031_50310301_0X36_dialog_content = "Yes. That's what I do every time I want to trigger my power, though it doesn't work all the time.",
  ui_story_5031_50310301_0X37_dialog_content = "I see. I understand now.",
  ui_story_5031_50310301_0X38_dialog_content = "I shall attempt it at a later time. Thank you, Vice.",
  ui_story_5031_50310301_0X39_dialog_content = "No problem!",
  ui_story_5031_50310301_0X40_dialog_content = "There we go, the last lace!",
  ui_story_5031_50310301_0X41_dialog_content = "Phew, you nobles sure like clothes that are a hassle.",
  ui_story_5031_50310301_0X42_dialog_content = "Also, this material seems pretty unique. I've never seen something like it in Illumina.",
  ui_story_5031_50310301_0X43_dialog_content = "This is my first time too. It's probably a Harbor City specialty.",
  ui_story_5031_50310301_0X44_dialog_content = "Formalwear is their forte, after all.",
  ui_story_5031_50310301_0X45_dialog_content = "Thanks again for the help, Vice.",
  ui_story_5031_50310301_0X46_dialog_content = "Don't sweat it. But you do look very nice in that, Carleen!",
  ui_story_5031_50310301_0X47_dialog_content = "Let's go show it off to PlayerName and Fia. They'll be amazed!",
  ui_story_5031_50310301_1_dialog_content = "Why isn't Carleen back yet?",
  ui_story_5031_50310301_2_dialog_content = "Girls take time to get changed, not to mention that outfit looked very intricate.",
  ui_story_5031_50310301_2X1_dialog_content = "Even with help from Vice, it should still take a while.",
  ui_story_5031_50310301_3_dialog_content = "You got a point. I suppose most nobles probably need servants to help them get dressed.",
  ui_story_5031_50310301_4_dialog_content = "How about you go give Carleen a hand too, Fia?",
  ui_story_5031_50310301_5_dialog_content = "Hah? What am I, your servant? Ordering me around like that!",
  ui_story_5031_50310301_6_dialog_content = "C'mon, be a good girl. Aren't Carleen and Vice doing their very best to help you locate the Cloudwhale?",
  ui_story_5031_50310301_7_dialog_content = "Alright, alright! I've never helped someone put on a dress before. I can try.",
  ui_story_5031_50310301_8_dialog_content = "PlayerName, go easy on Fia.",
  ui_story_5031_50310301_9_dialog_content = "I'm sorry for keeping everyone waiting...",
  ui_story_5031_50310301_10_dialog_content = "Well! Carleen, you look... absolutely stunning!",
  ui_story_5031_50310301_11_dialog_content = "Yeah! It looks comfortable, practical, and really fits you well, Carleen!",
  ui_story_5031_50310301_12_dialog_content = "Thanks, everyone. It's amazing—the number of professional tailors and incredible fashion designers around Harbor City.",
  ui_story_5031_50310301_13_dialog_content = "I actually feel extremely comfortable in this.",
  ui_story_5031_50310301_14_dialog_content = "What do you think, PlayerName?",
  ui_story_5031_50310301_15_dialog_content = "I'm sorry. I was just spellbound for a second. But what I was going to say was that—",
  ui_story_5031_50310301_16_dialog_content = "Beautiful! Graceful! Powerful!",
  ui_story_5031_50310301_17_dialog_content = "You're a child of the Schwartz family in every way, Carleen, and this stunning outfit just goes to show it.",
  ui_story_5031_50310301_18_dialog_content = "I don't know what to say. I guess I should thank you, Laird Elvis.",
  ui_story_5031_50310301_19_dialog_content = "Please, it's the least I could do. I was going for something that reminded me of the exemplary, noble characteristics of the Schwartz family.",
  ui_story_5031_50310301_20_dialog_content = "You may consider the outfit as a kind of good omen for your successful entrance into the competition!",
  ui_story_5031_50310301_21_dialog_content = "I'm needed elsewhere, but I look forward to seeing you again later!",
  ui_story_5031_50310301_22_dialog_content = "Oh, I'm sorry—I guess I didn't really get a chance to share my thoughts on Carleen's new dress.",
  ui_story_5031_50310301_23_dialog_content = "Urgh. Laird Elvis stole my thunder.",
  ui_story_5031_50310301_24_dialog_content = "Eh, I don't think you have to say anything...",
  ui_story_5031_50310301_25_dialog_content = "You've said quite enough with your eyes.",
  ui_story_5031_50310301_26_dialog_content = "Huh?",
  ui_story_5031_50310301_27_dialog_content = "Greetings, everyone! It's time for me to give you all a brief rundown of the event.",
  ui_story_5031_50310301_28_dialog_content = "Allow me to introduce myself. I'm Rainbow, the circus emcee, customer liaison, security director, and marine engineer apprentice!",
  ui_story_5031_50310301_29_dialog_content = "But today I'll be wearing the hat of the competition's main emcee!",
  ui_story_5031_50310301_30_dialog_content = "In this first stage I kindly ask all of you to take one of my specially prepared water guns from here.",
  ui_story_5031_50310301_31_dialog_content = "These water guns have been modified to channel Lumina into firing a special pellet.",
  ui_story_5031_50310301_32_dialog_content = "The rules are very simple: hit targets as given by Ringmaster Jeno with your water gun.",
  ui_story_5031_50310301_33_dialog_content = "I must inform you that we will not stop competitors or teams from using the water guns on each other!",
  ui_story_5031_50310301_34_dialog_content = "Only the five top-scoring teams will make it into the next round. Those eliminated are cast into the sea as punishment.",
  ui_story_5031_50310301_35_dialog_content = "So we don't want any contestants who can't swim! Or at least make sure you have a flotation device with you!",
  ui_story_5031_50310301_36_dialog_content = "Teams can be of any size, but note your final score will be obtained by dividing your team score by the number of members.",
  ui_story_5031_50310301_37_dialog_content = "These rules are really good for us, right?",
  ui_story_5031_50310301_38_dialog_content = "We're gonna get the prize for sure with Jona and Azure on our team!",
  ui_story_5031_50310301_39_dialog_content = "Water guns? Looks silly, but I can't ignore that grand prize...",
  ui_story_5031_50310301_40_dialog_content = "What else are we gonna do with our time anyway? It's just a bit of harmless fun.",
  ui_story_5031_50310301_41_dialog_content = "Hehe, we're gonna get rich!",
  ui_story_5031_50310301_42_dialog_content = "Don't count your chickens too early! Anyway, you two are Rediesel Wrench newbies.",
  ui_story_5031_50310301_43_dialog_content = "Remember our rules and how we conduct ourselves! Don't bring shame to the Rediesel Wrench!",
  ui_story_5031_50310301_44_dialog_content = "Don't worry 'bout a thing! We know!",
  ui_story_5031_50310301_45_dialog_content = "It's just a few rules, we got it!",
  ui_story_5031_50310301_46_dialog_content = "Is everyone clear on the rules?",
  ui_story_5031_50310301_47_dialog_content = "Loud and clear!",
  ui_story_5031_50310301_48_dialog_content = "Wait! If these water guns run on Lumina, wouldn't this put me at a disadvantage?",
  ui_story_5031_50310301_49_dialog_content = "Oh yeah. I didn't even think about that.",
  ui_story_5031_50310301_50_dialog_content = "Merylt, do you think you could go to the Caelestite's team and help them out?",
  ui_story_5031_50310301_51_dialog_content = "W-What am I supposed to do with that? We're not allowed to take part...",
  ui_story_5031_50310301_52_dialog_content = "Silly. Why even include him? He's not much of a beansprout.",
  ui_story_5031_50310301_53_dialog_content = "Boss, what about the Caelestite?",
  ui_story_5031_50310301_54_dialog_content = "We can take handicaps into account. Count the Caelestite and that little girl as one.",
  ui_story_5031_50310301_55_dialog_content = "Hey! In what universe is a Caelestite plus me half a person each?",
  ui_story_5031_50310301_56_dialog_content = "Have it your way. Two participants then.",
  ui_story_5031_50310301_57_dialog_content = "Uh, actually, I'm a bit young and not very fit... On second thought, maybe it does make sense to combine us!",
  ui_story_5031_50310301_58_dialog_content = "Then, there being no objection, I will deliver your targets shortly—",
  ui_story_5031_50310301_59_dialog_content = "Come on! A round of applause for our crazy competitors!",
  ui_story_5031_50310301_60_dialog_content = "Now, howl! Like you mean it! Beasts of Hades!",
  ui_story_5031_50310301_61_dialog_content = "Wait! I hope Boss isn't really thinking of summoning those...",
  ui_story_5031_50310301_62_dialog_content = "Quick! Cover Rainbow's eyes! She'll go nuts if she sees an Eclipsite!",
  ui_story_5031_50310301_63_dialog_content = "Graah!",
  ui_story_5031_50310301_64_dialog_content = "Eclipsites?!",
  ui_story_5031_50310301_65_dialog_content = "Eclipsites!!",
  ui_story_5031_50310301_66_dialog_content = "Frimet! Do something to help me with Rainbow. She's going to lose it!",
  ui_story_5031_50310301_67_dialog_content = "Stupid Boss! Why choose Eclipsites?!",
  ui_story_5031_50310301_68_dialog_content = "Eh... because it just works so well with this wind.",
  ui_story_5031_50310301_69_dialog_content = "PlayerName, Fia—get behind me and Vice.",
  ui_story_5031_50310301_70_dialog_content = "Do not worry, dear friends! These Eclipsites are little more than illusions I've conjured up with the \"<color=#FFB400>Origin</color>.\"",
  ui_story_5031_50310301_71_dialog_content = "With the power of my own two hands, I've analyzed the \"origin\" of the Eclipsites' power in the course of my battles!",
  ui_story_5031_50310301_72_dialog_content = "And, with the use of the \"<color=#FFB400>Origin Card</color>,\" created the lifelike, nimble illusions you see before you.",
  ui_story_5031_50310301_73_dialog_content = "Grah...",
  ui_story_5031_50310301_74_dialog_content = "Grah...",
  ui_story_5031_50310301_75_dialog_content = "As you can see, the Eclipsites are completely under my control and make excellent targets.",
  ui_story_5031_50310301_76_dialog_content = "So then, let the games begin!",
  ui_story_5031_50310401_1_dialog_content = "Hey! Get busy! I want you to clear out these Eclipsites, because there ain't no way the Rediesel Wrench is gonna settle for the second!",
  ui_story_5031_50310401_2_dialog_content = "Got it, Boss! But what about the Aurorians?",
  ui_story_5031_50310401_3_dialog_content = "What about them? You're a Rediesel Wrench! Now hit it out of the park!",
  ui_story_5031_50310401_4_dialog_content = "Make the Rediesel Wrench look good and shoot anyone in your way over the side of the ship!",
  ui_story_5031_50310401_5_dialog_content = "Got it.",
  ui_story_5031_50310401_6_dialog_content = "Intense, Jona.",
  ui_story_5031_50310401_7_dialog_content = "What's the big deal? No guy, no matter how cute, is above punishment!",
  ui_story_5031_50310401_8_dialog_content = "Cute's cute, but cuter still is that grand prize...",
  ui_story_5031_50310401_9_dialog_content = "Urgh... Jona and Azure are here—they're gun pros.",
  ui_story_5031_50310401_10_dialog_content = "They said you only get points for shooting Eclipsites, but these Rediesel Wrench guys are just shooting other players!",
  ui_story_5031_50310401_11_dialog_content = "If Jeno's illusions didn't make such an excellent cover, we would've been shot overboard ages ago.",
  ui_story_5031_50310401_12_dialog_content = "We still might be unless we can do something instead of just waiting here. Follow my lead! We'll fight our way through!",
  ui_story_5031_50310401_13_dialog_content = "Hold on, Carleen!",
  ui_story_5031_50310401_14_dialog_content = "This is what you get for not following the spirit of the rules, you dirty tricksters—ice blossom, no, ice shoot!",
  ui_story_5031_50310401_15_dialog_content = "Yikes!",
  ui_story_5031_50310401_16_dialog_content = "B-Boss!",
  ui_story_5031_50310401_17_dialog_content = "That's two of them down. Quick, come over here, everyone.",
  ui_story_5031_50310401_18_dialog_content = "Excellent work... Straight into the ocean with Carleen's signature ice shoot. Hey, Carleen, behind the cover, quick!",
  ui_story_5031_50310401_19_dialog_content = "Now's your chance, PlayerName!",
  ui_story_5031_50310401_20_dialog_content = "That's what you get for being a lone ranger, Carleen! This means—",
  ui_story_5031_50310401_21_dialog_content = "I've got you now, my fair princess of Lumopolis!",
  ui_story_5031_50310401_22_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5031_50310401_23_dialog_content = "!!",
  ui_story_5031_50310401_24_dialog_content = "Carleen!",
  ui_story_5031_50310401_25_dialog_content = "I'm—I'm sorry, PlayerName.",
  ui_story_5031_50310401_26_dialog_content = "All's well that ends well. I didn't expect Jona to be so good with a Lumina water gun.",
  ui_story_5031_50310401_27_dialog_content = "Hey! You despicable Rediesel thugs! Stop picking on us!",
  ui_story_5031_50310401_28_dialog_content = "That's not going to work. We got to figure out this impasse.",
  ui_story_5031_50310401_29_dialog_content = "A very exciting competition, everybody.",
  ui_story_5031_50310401_30_dialog_content = "Yes. Indeed. Filled with feats of power I'd not expected.",
  ui_story_5031_50310401_31_dialog_content = "A power I obtained from the True Order...",
  ui_story_5031_50310401_32_dialog_content = "Of which I'm sure you've heard more negative legends as a Lumopolis noble, sir.",
  ui_story_5031_50310401_33_dialog_content = "In fact, what the \"origin\" represents more than anything is merely another way of creating suspense for performative effect.",
  ui_story_5031_50310401_34_dialog_content = "In truth, what I possess is merely the power to transform energy... an effective habit with practice, as you can see.",
  ui_story_5031_50310401_35_dialog_content = "I'm not one to take particular offense at strange powers. Don't worry.",
  ui_story_5031_50310401_36_dialog_content = "But why Eclipsites?",
  ui_story_5031_50310401_37_dialog_content = "We're all here to attend the carnival, aren't we? What is a carnival but a series of exciting, breathtaking encounters?",
  ui_story_5031_50310401_38_dialog_content = "I should think Eclipsites fit the bill very well.",
  ui_story_5031_50310401_39_dialog_content = "I can't fault your business logic. Food for thought.",
  ui_story_5031_50310401_40_dialog_content = "Naturally, I must always think of the business case as the ringmaster of the entire circus troupe.",
  ui_story_5031_50310401_41_dialog_content = "My apologies for the intrusion, Laird Elvis.",
  ui_story_5031_50310401_42_dialog_content = "Patou...? Later, Jeno.",
  ui_story_5031_50310401_43_dialog_content = "What news have you?",
  ui_story_5031_50310401_44_dialog_content = "A report, verified. We've located a room matching your earlier description.",
  ui_story_5031_50310401_45_dialog_content = "What? Wonderful...",
  ui_story_5031_50310401_46_dialog_content = "Unfortunately, the room is protected by a very secure lock we've never seen. Forced entry would certainly raise the alarm.",
  ui_story_5031_50310401_47_dialog_content = "I understand. Then we'll have to find a key capable of opening it.",
  ui_story_5031_50310401_48_dialog_content = "I would assume such a key could be found in Jeno's chambers or his person. We can try both avenues simultaneously.",
  ui_story_5031_50310401_49_dialog_content = "Elvis!",
  ui_story_5031_50310401_50_dialog_content = "I hope I'm not bothering you, but another team has just scored a big point, and people are clamoring for you to honor the point.",
  ui_story_5031_50310401_51_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310401_52_dialog_content = "Apologies, Jeno. After a few more words with Patou.",
  ui_story_5031_50310401_53_dialog_content = "So what shall we do, sir?",
  ui_story_5031_50310401_54_dialog_content = "You and your men have the authority to do whatever is necessary to search the room.",
  ui_story_5031_50310401_55_dialog_content = "But I fear any significant absence from the day's events will arouse Jeno's suspicions.",
  ui_story_5031_50310401_56_dialog_content = "It's intriguing just how many contestants there are with ulterior motives... they could be going after the same thing as us.",
  ui_story_5031_50310401_57_dialog_content = "So I'm going to need eyes on them. Anyone who wants to make a move will need to do it when it's quiet—when the deck is less busy.",
  ui_story_5031_50310401_58_dialog_content = "I take it, sir, we should continue searching quietly and await further orders from your lordship.",
  ui_story_5031_50310401_59_dialog_content = "Laird Elvis! Laird Elvis!",
  ui_story_5031_50310401_60_dialog_content = "I'm finally back, everybody! And I hereby announce the Rediesel Wrench team has won another point!",
  ui_story_5031_50310401_61_dialog_content = "Back indeed. We were beginning to wonder.",
  ui_story_5031_50310401_62_dialog_content = "Apologies, Jeno, for the long wait.",
  ui_story_5031_50310402_1_dialog_content = "And what about that key? How am I supposed to know where you put it?",
  ui_story_5031_50310402_2_dialog_content = "You seem a bit out of sorts, Elvis?",
  ui_story_5031_50310402_3_dialog_content = "I mean, it seemed something your bodyguard said had displeased you.",
  ui_story_5031_50310402_4_dialog_content = "I trust all is well? No maladies of any kind?",
  ui_story_5031_50310402_5_dialog_content = "No, no. I'm very well, thank you.",
  ui_story_5031_50310402_6_dialog_content = "I was just busying myself with a few affairs of state. Sorry for giving you that impression.",
  ui_story_5031_50310402_7_dialog_content = "I hope dragging you out here hasn't taken you away from important work?",
  ui_story_5031_50310402_8_dialog_content = "I was just thinking that maybe you would really appreciate this opportunity to enjoy the wonderful festival with your people.",
  ui_story_5031_50310402_9_dialog_content = "Oh? Is that the first time I've ever seen Boss apologize?",
  ui_story_5031_50310402_10_dialog_content = "I think so. I guess that he can talk like a normal person if he wants to.",
  ui_story_5031_50310402_11_dialog_content = "If you have so much time on your hands, go and help Rainbow, ok?",
  ui_story_5031_50310402_12_dialog_content = "Pffffft.",
  ui_story_5031_50310402_13_dialog_content = "Sheesh. It's like herding cats, morning 'til night.",
  ui_story_5031_50310402_14_dialog_content = "Oh, don't worry about me. I was just...",
  ui_story_5031_50310402_15_dialog_content = "I've been troubled by a few weighty matters in need of a decision.",
  ui_story_5031_50310402_16_dialog_content = "This opportunity to relax has meant a chance for fresh insights into a few things and people. It's very helpful.",
  ui_story_5031_50310402_17_dialog_content = "Wonderful! You must tell me if you find the day bothersome for any reason.",
  ui_story_5031_50310402_18_dialog_content = "Right. No problem.",
  ui_story_5031_50310402_19_dialog_content = "\"Attention, participants! We are now entering into a more exciting stage of our game involving twice as many Eclipsite projections!\"",
  ui_story_5031_50310402_20_dialog_content = "Finally! Bonus time!",
  ui_story_5031_50310402_21_dialog_content = "Cover me, Ciel! Bonus time is where the champions make or break it!",
  ui_story_5031_50310402_22_dialog_content = "G-Got it, Officer Gronru.",
  ui_story_5031_50310402_23_dialog_content = "Ah, you're running too quickly for me—",
  ui_story_5031_50310402_24_dialog_content = "Hey! Who's that?",
  ui_story_5031_50310402_25_dialog_content = "What do we have here? A poor Illumina girl all by her lonesome.",
  ui_story_5031_50310402_26_dialog_content = "H-Hey! Stay away from me!",
  ui_story_5031_50310402_27_dialog_content = "We need that prize. Good things don't come cheap.",
  ui_story_5031_50310402_28_dialog_content = "Sorry, missy, but I'm going to confiscate your water gun. Now do us a favor and jump into the ocean, would you?",
  ui_story_5031_50310402_29_dialog_content = "Wait—nice gear! We could fetch a pretty price for it in Umbraton, don't you think?",
  ui_story_5031_50310402_30_dialog_content = "Yeah! And we always get what we want, missy. Don't make this difficult.",
  ui_story_5031_50310402_31_dialog_content = "Give us your valuables!",
  ui_story_5031_50310402_32_dialog_content = "H-Hands off!",
  ui_story_5031_50310402_33_dialog_content = "Freeze, you two!",
  ui_story_5031_50310402_34_dialog_content = "Don't tell me it's the emcee!",
  ui_story_5031_50310402_35_dialog_content = "The very same! Theft is strictly against tournament rules. I'm afraid I'm not going to be able to let you off!",
  ui_story_5031_50310402_36_dialog_content = "Who do you think you are? You think we're afraid of you because you're the emcee?",
  ui_story_5031_50310402_37_dialog_content = "I will not stand for this kind of loutish behavior, you hear me?",
  ui_story_5031_50310402_38_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5031_50310402_39_dialog_content = "D-Dude!",
  ui_story_5031_50310402_40_dialog_content = "You too!",
  ui_story_5031_50310402_41_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5031_50310402_42_dialog_content = "Ow!",
  ui_story_5031_50310402_43_dialog_content = "V-Very impressive... Overboard just like that.",
  ui_story_5031_50310402_44_dialog_content = "You're not hurt, are you? That was crazy—thinking they could use this event as a shakedown!",
  ui_story_5031_50310402_45_dialog_content = "Uh, I-I've got to help Officer Gronru. Thank you!",
  ui_story_5031_50310402_46_dialog_content = "My water gun... Where is it?",
  ui_story_5031_50310402_47_dialog_content = "Oh. Sorry about that. Here, have this.",
  ui_story_5031_50310402_48_dialog_content = "I've added something to the rules about \"people who lose their water guns can pick up a new one from the emcee.\" So don't worry about it.",
  ui_story_5031_50310402_49_dialog_content = "Oh, ok! Thank you.",
  ui_story_5031_50310402_50_dialog_content = "Hey...",
  ui_story_5031_50310402_51_dialog_content = "Huh?",
  ui_story_5031_50310402_52_dialog_content = "I'm Ciel. Thank you, Miss Rainbow.",
  ui_story_5031_50310402_53_dialog_content = "Ciel? I'll remember your name.",
  ui_story_5031_50310402_54_dialog_content = "My goodness. What's a classy lady like Carleen doing in an event like this?",
  ui_story_5031_50310402_55_dialog_content = "She should know better with her noble upbringing. She's making us all... look bad!",
  ui_story_5031_50310402_56_dialog_content = "...",
  ui_story_5031_50310402_57_dialog_content = "Hey! Am I just speaking to myself here?",
  ui_story_5031_50310402_58_dialog_content = "We've got to keep an eye on and protect Carleen.",
  ui_story_5031_50310402_59_dialog_content = "Tut, I may as well be.",
  ui_story_5031_50310402_60_dialog_content = "Hey, come over here! There are heaps of Eclipsites here you can take down!",
  ui_story_5031_50310402_61_dialog_content = "Ah!",
  ui_story_5031_50310402_62_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5031_50310402_63_dialog_content = "I-I'm sorry, sir... I accidentally got your water gun.",
  ui_story_5031_50310402_64_dialog_content = "Let me help you pick it up.",
  ui_story_5031_50310402_65_dialog_content = "It's okay. Don't worry about it. Your friend is waiting over there. Have a good time.",
  ui_story_5031_50310402_66_dialog_content = "Thank you. What a gentle noble you are!",
  ui_story_5031_50310402_67_dialog_content = "...",
  ui_story_5031_50310402_68_dialog_content = "... Disgusting.",
  ui_story_5031_50310402_69_dialog_content = "Water! Get me some water! I need to wash my hands!",
  ui_story_5031_50310402_70_dialog_content = "... Dramatic.",
  ui_story_5031_50310402_71_dialog_content = "Graah!",
  ui_story_5031_50310402_72_dialog_content = "PlayerName, Jeno sure added a lot of Eclipsites.",
  ui_story_5031_50310402_73_dialog_content = "And those Rediesel guys are not giving us a break.",
  ui_story_5031_50310402_74_dialog_content = "They'd rather risk elimination from a lack of points to focus on us!",
  ui_story_5031_50310402_75_dialog_content = "I think that just says they see us as the competition.",
  ui_story_5031_50310402_76_dialog_content = "And that's why they want to eliminate us early on.",
  ui_story_5031_50310402_77_dialog_content = "I've got a bit of a gambit... but it just might work: I can be the bait as someone who doesn't have access to Lumina.",
  ui_story_5031_50310402_78_dialog_content = "I'll do my best to attract a lot of Eclipsites over while you use the diversion to get out from under Jona and Azure's thumb.",
  ui_story_5031_50310402_79_dialog_content = "That's too risky, PlayerName! We can just try to break through again. I'd be more careful with that!",
  ui_story_5031_50310402_80_dialog_content = "Jona and Azure are too good. They'll be able to pinpoint you from a far distance, Carleen.",
  ui_story_5031_50310402_81_dialog_content = "I don't go down that easy. Trust my power.",
  ui_story_5031_50310402_82_dialog_content = "I do trust, and now's the time to put your faith in my power as well.",
  ui_story_5031_50310402_83_dialog_content = "Carleen, I think PlayerName's suggestion is worth trying.",
  ui_story_5031_50310402_84_dialog_content = "I think it might be the best tactical option we've got.",
  ui_story_5031_50310402_85_dialog_content = "Alright then. But be careful, ok?",
  ui_story_5031_50310402_86_dialog_content = "Rest assured. Fia, you go with Carleen and Vice.",
  ui_story_5031_50310402_87_dialog_content = "H-Huh? Okay.",
  ui_story_5031_50310402_88_dialog_content = "Eclipsites! Meal incoming!",
  ui_story_5031_50310402_89_dialog_content = "500 Lumamber is all it takes to get this biggest banquet you ever saw! Now or never! Ahhhhh!",
  ui_story_5031_50310402_90_dialog_content = "Graah!",
  ui_story_5031_50310402_91_dialog_content = "Graaaah...!",
  ui_story_5031_50310402_92_dialog_content = "Huh? Is that PlayerName? What the heck is he doing?",
  ui_story_5031_50310402_93_dialog_content = "Smart Caelestite. He's baiting the Eclipsites into blocking our line of sight, I guess.",
  ui_story_5031_50310402_94_dialog_content = "Then he's a fool who's gonna get a fool's comeuppance right in his tush for underestimating me...",
  ui_story_5031_50310402_95_dialog_content = "Hiya ladies.",
  ui_story_5031_50310402_96_dialog_content = "What?",
  ui_story_5031_50310402_97_dialog_content = "I'm afraid I consider Carleen's merry band somewhat under my protection...",
  ui_story_5031_50310402_98_dialog_content = "I have enough rage at my tainted hands to go around... You guys dare to attack the noble? Take your lumps!!",
  ui_story_5031_50310402_99_dialog_content = "Get behind me, Vice, Fia!",
  ui_story_5031_50310402_100_dialog_content = "I'm going to take out all you Eclipsites single-handed!",
  ui_story_5031_50310402_101_dialog_content = "<color=#e8d9bb>Bang, bang!</color>",
  ui_story_5031_50310402_102_dialog_content = "Grah...",
  ui_story_5031_50310402_103_dialog_content = "Graah!!",
  ui_story_5031_50310402_104_dialog_content = "Graah!",
  ui_story_5031_50310402_105_dialog_content = "Graah!",
  ui_story_5031_50310402_106_dialog_content = "They're weak, but there are too many. They have us surrounded.",
  ui_story_5031_50310402_107_dialog_content = "This isn't the time to indulge, Carleen. We've got to get back with PlayerName.",
  ui_story_5031_50310402_108_dialog_content = "If only the rules would allow the Moon Cocoon... Humph. Take that, you Eclipsites!",
  ui_story_5031_50310402_108X1_dialog_content = "If only I got new power as Vice got...!",
  ui_story_5031_50310402_108X2_dialog_content = "Calm down, Carleen.",
  ui_story_5031_50310402_108X3_dialog_content = "Just let go of your consciousness like Vice said...",
  ui_story_5031_50310402_108X4_dialog_content = "Let go... Breath.",
  ui_story_5031_50310402_108X5_dialog_content = "Carleen.",
  ui_story_5031_50310402_108X6_dialog_content = "Father...",
  ui_story_5031_50310402_108X7_dialog_content = "You and I both know the Eclipsites cannot be wiped out.",
  ui_story_5031_50310402_108X8_dialog_content = "Reckless actions only lead to the demise of soldiers who believed in you.",
  ui_story_5031_50310402_108X9_dialog_content = "Without great power, you cannot defend any loved one.",
  ui_story_5031_50310402_108X10_dialog_content = "You're not strong enough... Must find a way... to be stronger.",
  ui_story_5031_50310402_108X11_dialog_content = "I'm very disappointed...",
  ui_story_5031_50310402_108X12_dialog_content = "No... That's not true, Father!",
  ui_story_5031_50310402_108X13_dialog_content = "Carleen!",
  ui_story_5031_50310402_108X14_dialog_content = "Graah!",
  ui_story_5031_50310402_108X15_dialog_content = "Beat it!!",
  ui_story_5031_50310402_109_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5031_50310402_110_dialog_content = "Y-You can't use fists! We won't get points.",
  ui_story_5031_50310402_111_dialog_content = "Calm down, Carleen! We've got to find PlayerName first!",
  ui_story_5031_50310402_112_dialog_content = "... I'm sorry. You're right.",
  ui_story_5031_50310402_113_dialog_content = "<color=#e8d9bb>Ring-ring!</color>",
  ui_story_5031_50310402_114_dialog_content = "\"The match has now ended! All remaining participants, please make your way to the judge's podium for scoring.\"",
  ui_story_5031_50310402_115_dialog_content = "Great job, Carleen. We're through to the next round!",
  ui_story_5031_50310402_116_dialog_content = "Well, a lot of it was thanks to PlayerName for getting us out of the Rediesel Wrench's circle.",
  ui_story_5031_50310402_117_dialog_content = "At no small risk to yourself. I wouldn't allow it in a real battle.",
  ui_story_5031_50310402_118_dialog_content = "Aha, the Caelestite actually thinks he saved everyone!",
  ui_story_5031_50310402_119_dialog_content = "Huh? Azure? What do you mean?",
  ui_story_5031_50310402_120_dialog_content = "A Lumo guy picked a fight out of nowhere. He distracted us bad.",
  ui_story_5031_50310402_121_dialog_content = "You can thank your lucky stars he did so... Without him, you'd have been toast.",
  ui_story_5031_50310402_122_dialog_content = "But it was a lot more fun taking him down than playing this silly kid's game with water guns.",
  ui_story_5031_50310402_123_dialog_content = "Called himself a nobleman, he's not like any noble I've seen, and he kept us well-occupied.",
  ui_story_5031_50310402_124_dialog_content = "A pity that quiet guy dragged him off. We could have battled long and hard.",
  ui_story_5031_50310402_125_dialog_content = "B-Boss...",
  ui_story_5031_50310402_126_dialog_content = "You dare show your face again?",
  ui_story_5031_50310402_127_dialog_content = "We don't go against women and children. You forget?!",
  ui_story_5031_50310402_128_dialog_content = "I-I'm so sorry. I don't know what got into me.",
  ui_story_5031_50310402_129_dialog_content = "Start with push-ups away from the main deck. I'll deal with you after my drink.",
  ui_story_5031_50310402_130_dialog_content = "Y-Yes, Boss!",
  ui_story_5031_50310402_131_dialog_content = "Always raining on my parade...",
  ui_story_5031_50310402_132_dialog_content = "I didn't realize the Rediesel Wrench had that side.",
  ui_story_5031_50310402_133_dialog_content = "I'll take that as a compliment. All right, Princess, I'm going drinking with Azure. See you.",
  ui_story_5031_50310402_134_dialog_content = "Bye-bye! We're getting the free booze over there. Hey Caelestite, you're welcome to come.",
  ui_story_5031_50310402_135_dialog_content = "Phew... Somehow we've ended up with one less opponent to worry about.",
  ui_story_5031_50310402_136_dialog_content = "I think Gronru and her friend made it through too. They actually scored quite high.",
  ui_story_5031_50310402_137_dialog_content = "I didn't expect everyone would take it so seriously. Look at Jona and Azure—eliminated in the first round!",
  ui_story_5031_50310402_138_dialog_content = "I'm sure the next round is only going to be... more intense, heart-wrenching, and antagonistic...",
  ui_story_5031_50310402_139_dialog_content = "Purr.",
  ui_story_5031_50310402_140_dialog_content = "That was quite audible!",
  ui_story_5031_50310402_141_dialog_content = "Just building on your anxious atmosphere!",
  ui_story_5031_50310402_142_dialog_content = "Greetings, Laird.",
  ui_story_5031_50310402_143_dialog_content = "Greetings. You were...",
  ui_story_5031_50310402_144_dialog_content = "That's right. I'm Subli.",
  ui_story_5031_50310402_145_dialog_content = "Jeno had me bring you this as a gift.",
  ui_story_5031_50310402_146_dialog_content = "And this is...?",
  ui_story_5031_50310402_147_dialog_content = "A blanket. He was worried you might catch a cold in this sea breeze.",
  ui_story_5031_50310402_148_dialog_content = "... I see. Convey my thanks.",
  ui_story_5031_50310402_149_dialog_content = "And thank you too, Subli.",
  ui_story_5031_50310402_150_dialog_content = "Hee, don't mention it.",
  ui_story_5031_50310402_151_dialog_content = "...",
  ui_story_5031_50310501_1_dialog_content = "I salute you, brave warriors, who've made it through the first round!",
  ui_story_5031_50310501_2_dialog_content = "There's no question all of you have proved your mettle on this journey to the ultimate treasure.",
  ui_story_5031_50310501_3_dialog_content = "Our rules for the next round are also extremely simple.",
  ui_story_5031_50310501_4_dialog_content = "I'm sure you've all had the benefit of playing a very similar game as children.",
  ui_story_5031_50310501_5_dialog_content = "Come out, oh craven beast that squirms in the dusk hours! Oh guardian of strange artifacts and sorceries!",
  ui_story_5031_50310501_6_dialog_content = "<color=#e8d9bb>Thud...!</color>",
  ui_story_5031_50310501_7_dialog_content = "Look, this is our Keeper of the Secret in this round.",
  ui_story_5031_50310501_8_dialog_content = "Ahem. Now, I will go over some of the rules.",
  ui_story_5031_50310501_9_dialog_content = "When this unique Eclipsite turns green...",
  ui_story_5031_50310501_10_dialog_content = "You need to get to it as fast as you can, past all other Eclipsites blocking you.",
  ui_story_5031_50310501_11_dialog_content = "Just cross this line at its feet to qualify for the next round.",
  ui_story_5031_50310501_12_dialog_content = "Please be careful when it turns red!",
  ui_story_5031_50310501_13_dialog_content = "No Aurorians or Eclipsites are allowed to move then. If you do, you'll be thrown overboard by the nearest Eclipsite, and then you'll be out.",
  ui_story_5031_50310501_14_dialog_content = "Anyone who doesn't make it to the finish line by the end is also out.",
  ui_story_5031_50310501_15_dialog_content = "And you can feel free to use appropriate Luminatics. No restrictions now.",
  ui_story_5031_50310501_16_dialog_content = "Exactly. So come on then! Show us what you've got! Challenge my creature for the prize!",
  ui_story_5031_50310501_17_dialog_content = "PlayerName.",
  ui_story_5031_50310501_18_dialog_content = "Yeah. Now I can finally use my strengths.",
  ui_story_5031_50310501_19_dialog_content = "Don't worry. I'll help everyone make it to the finish line in time!",
  ui_story_5031_50310502_1_dialog_content = "Heh! Even I could take out an Eclipsite like that!",
  ui_story_5031_50310502_2_dialog_content = "Watch and learn, you filthy Eclipsites!",
  ui_story_5031_50310502_3_dialog_content = "Hey! The big one is about to change color. Better stop!",
  ui_story_5031_50310502_4_dialog_content = "Give me a sec! I can take the lead!",
  ui_story_5031_50310502_5_dialog_content = "Idiots. You're about to be eliminated, don't you know?",
  ui_story_5031_50310502_6_dialog_content = "By the way, I have you to thank for earning points last round while I was otherwise engaged with those two bandits.",
  ui_story_5031_50310502_7_dialog_content = "I never knew they were so tough... That was a good warm-up.",
  ui_story_5031_50310502_8_dialog_content = "If you hadn't pulled me away... I could have made an example of them!",
  ui_story_5031_50310502_9_dialog_content = "...",
  ui_story_5031_50310502_10_dialog_content = "Tut. I'm trying to compliment you, my man! Your Luminatics sealed your mouth shut?",
  ui_story_5031_50310502_11_dialog_content = "<color=#e8d9bb>Ring-ring!</color>",
  ui_story_5031_50310502_12_dialog_content = "It changed color!",
  ui_story_5031_50310502_13_dialog_content = "Graah!",
  ui_story_5031_50310502_14_dialog_content = "D-Don't come over!",
  ui_story_5031_50310502_15_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5031_50310502_16_dialog_content = "<color=#e8d9bb>Plop!!</color>",
  ui_story_5031_50310502_17_dialog_content = "Over they go! Commoners by name, commoners by nature...",
  ui_story_5031_50310502_18_dialog_content = "We must not venture too far from the princess. Protect her at closer quarters.",
  ui_story_5031_50310502_19_dialog_content = "We can't let her take a dip in the sea like those poor, foolish souls.",
  ui_story_5031_50310502_20_dialog_content = "Thank you for the blanket, Jeno.",
  ui_story_5031_50310502_21_dialog_content = "You're welcome. Keep warm, keep well. Looks like a stiff breeze would blow you over.",
  ui_story_5031_50310502_22_dialog_content = "Hehe. A strange game for an adult of your years, surely?",
  ui_story_5031_50310502_23_dialog_content = "In what way? Is it too childish?",
  ui_story_5031_50310502_24_dialog_content = "Not at all. I'm just a bit surprised.",
  ui_story_5031_50310502_25_dialog_content = "You still enjoy this game even after all these years, even bring it back for this round...",
  ui_story_5031_50310502_26_dialog_content = "Cuz I'm quite a nostalgic person.",
  ui_story_5031_50310502_27_dialog_content = "I'm also cursed with a long memory. For example, something as insignificant as a missed appointment many years ago—for which I waited an entire day.",
  ui_story_5031_50310502_28_dialog_content = "... I do apologize for not having said goodbye all those years ago.",
  ui_story_5031_50310502_29_dialog_content = "That's alright.",
  ui_story_5031_50310502_30_dialog_content = "...?",
  ui_story_5031_50310502_31_dialog_content = "I just wanted to hear you say that.",
  ui_story_5031_50310502_32_dialog_content = "I can only imagine...",
  ui_story_5031_50310502_33_dialog_content = "Imagine all the travails involved in working one's way up from the son of a restaurant owner to the laird of Harbor City.",
  ui_story_5031_50310502_34_dialog_content = "But I still get a strong impression you haven't changed at all in so many other important ways. I hope that's not mistaken.",
  ui_story_5031_50310502_35_dialog_content = "In what important ways?",
  ui_story_5031_50310502_36_dialog_content = "Like the aerobic exercises you rolled out across Harbor City. Very silly but... very you.",
  ui_story_5031_50310502_37_dialog_content = "Hahaha! Silly, but effective to help everyone keep fit.",
  ui_story_5031_50310502_38_dialog_content = "What about you? I looked for you for a long time after returning to Lumopolis. No one knew your whereabouts.",
  ui_story_5031_50310502_39_dialog_content = "Me?",
  ui_story_5031_50310502_40_dialog_content = "I looked for you for a long time after returning to Harbor City. No one knew where you'd gone.",
  ui_story_5031_50310502_41_dialog_content = "Some even told me that you and your family were no longer with us...",
  ui_story_5031_50310502_42_dialog_content = "A fair summation.",
  ui_story_5031_50310502_43_dialog_content = "Providence handed us an escape into the Emerald and, like refugees fleeing the Darkover Crisis, we took hold of our life raft for all it's worth.",
  ui_story_5031_50310502_44_dialog_content = "As fate would have it, I was eventually saved by Lady Victoria of the True Order.",
  ui_story_5031_50310502_45_dialog_content = "She also endowed me with an ability to manipulate the Origin.",
  ui_story_5031_50310502_46_dialog_content = "It was only upon my return to the Emerald that I learned my parents had passed.",
  ui_story_5031_50310502_47_dialog_content = "And, of course, I blamed the previous ringmaster for their demise. I challenged him to a duel in my wrath.",
  ui_story_5031_50310502_48_dialog_content = "The truth was a long time coming, long enough for the old ringmaster to forgive this indiscretion.",
  ui_story_5031_50310502_49_dialog_content = "And then it was just myself, the Emerald, and fellow circus members on our journey across the high seas.",
  ui_story_5031_50310502_50_dialog_content = "I'm sorry... They were good people.",
  ui_story_5031_50310502_51_dialog_content = "You don't need to apologize. It wasn't your fault.",
  ui_story_5031_50310502_52_dialog_content = "I may be leveraging the True Order to advance my career as a magician...",
  ui_story_5031_50310502_53_dialog_content = "But, truth be told, I care little for the Order and its doctrines.",
  ui_story_5031_50310502_54_dialog_content = "Anyway, the Order has so many sects... I'm afraid I'm probably in the most \"sidetracked\" type.",
  ui_story_5031_50310502_55_dialog_content = "Yet I must honor the promise I made to Lady Victoria for her kindness.",
  ui_story_5031_50310502_56_dialog_content = "I never want to betray a promise...",
  ui_story_5031_50310502_57_dialog_content = "A promise... *Coughs*",
  ui_story_5031_50310502_58_dialog_content = "Is that—are you coughing up blood?",
  ui_story_5031_50310502_59_dialog_content = "I-I'm fine. A little overworked with politics... and also this darned cold...",
  ui_story_5031_50310502_60_dialog_content = "Do you take me for a fool?",
  ui_story_5031_50310502_61_dialog_content = "Haha! Far from it. I'm very healthy, thank you.",
  ui_story_5031_50310502_62_dialog_content = "Or do you want to use your divination powers to see into my future? I'm sure I have another 200 years left at least.",
  ui_story_5031_50310502_63_dialog_content = "Divination? Please. You can tell me the truth!",
  ui_story_5031_50310502_64_dialog_content = "*Gasping* Well, as a former resident of Harbor City yourself, you must be familiar with the so-called \"Legendary Heroes\"?",
  ui_story_5031_50310502_65_dialog_content = "Of course. A bedtime story for little children.",
  ui_story_5031_50310502_66_dialog_content = "... But that bedtime story is real.",
  ui_story_5031_50310502_67_dialog_content = "...",
  ui_story_5031_50310502_68_dialog_content = "To put it simply, they sealed the Eclipsites away with some sort of blood pact.",
  ui_story_5031_50310502_69_dialog_content = "The Eclipsites affected fell into deep hibernation, while Harbor City has been effectively protected from approaching.",
  ui_story_5031_50310502_70_dialog_content = "But this came at a cost—not only to them, but also to their descendants.",
  ui_story_5031_50310502_71_dialog_content = "And this is the true source of the condition known as Modali Syndrome.",
  ui_story_5031_50310502_72_dialog_content = "What? Is that why you have that scar on your face? Modali Syndrome?",
  ui_story_5031_50310502_73_dialog_content = "*Coughs* Indeed. But worry not. I'm... ugh... coping rather well.",
  ui_story_5031_50310502_74_dialog_content = "If it was sealed with a pact, then is there some way of undoing it?",
  ui_story_5031_50310502_75_dialog_content = "Perhaps. That's what I've been searching for in these long years... a solution.",
  ui_story_5031_50310502_76_dialog_content = "And what have you found?",
  ui_story_5031_50310502_77_dialog_content = "I'm sorry, I have nothing adequate to share yet. And there are secrets and interests involved that cannot be told simply or lightly.",
  ui_story_5031_50310502_78_dialog_content = "...",
  ui_story_5031_50310502_79_dialog_content = "Look! That girl's a powerhouse! She's racing ahead!",
  ui_story_5031_50310502_80_dialog_content = "Her partner's not even using Luminatics! How come she still takes a lead?",
  ui_story_5031_50310502_81_dialog_content = "Who can't use Luminatics? Is he a Caelestite?",
  ui_story_5031_50310502_82_dialog_content = "What? Let's see the Caelestite!",
  ui_story_5031_50310502_83_dialog_content = "Ringmaster, can I bother you for a sec? A new batch of supplies. Just need you to sign off.",
  ui_story_5031_50310502_84_dialog_content = "Sure. I'll be right over.",
  ui_story_5031_50310502_85_dialog_content = "I'm afraid you might have to judge solo until I return.",
  ui_story_5031_50310502_86_dialog_content = "Go ahead, Jeno.",
  ui_story_5031_50310602_1_dialog_content = "\"Round 2 race—start!\"",
  ui_story_5031_50310602_2_dialog_content = "<color=#e8d9bb>Ring-ring!</color>",
  ui_story_5031_50310602_3_dialog_content = "PlayerName! Stay close to us!",
  ui_story_5031_50310602_4_dialog_content = "Stay close on PlayerName, Vice and Fia! Don't let Eclipsites get to him.",
  ui_story_5031_50310602_5_dialog_content = "Got it!",
  ui_story_5031_50310602_6_dialog_content = "I didn't realize we had so little time to move. Sorry, I can't be of more help.",
  ui_story_5031_50310602_7_dialog_content = "I think some Aurorians have already sprinted over with their Luminatics.",
  ui_story_5031_50310602_8_dialog_content = "Never mind. We just need to focus.",
  ui_story_5031_50310602_9_dialog_content = "PlayerName, I need you to give me a path forward.",
  ui_story_5031_50310602_10_dialog_content = "Got it!",
  ui_story_5031_50310602_11_dialog_content = "Ah...",
  ui_story_5031_50310602_12_dialog_content = "It irks me on so many levels. I know the rules say to keep a distance from Her Highness, but I can't allow it.",
  ui_story_5031_50310602_13_dialog_content = "Hey, aren't you... that Judge? I remember.",
  ui_story_5031_50310602_14_dialog_content = "I am indeed Judge Matthieu, Your Highness, and this silent can of beans next to me is my associate, Loewe.",
  ui_story_5031_50310602_15_dialog_content = "I realize poor Pittman has been under your grace, but what I wish to say is—",
  ui_story_5031_50310602_16_dialog_content = "Your Highness... you deserve better.",
  ui_story_5031_50310602_17_dialog_content = "A mighty warrior should not be joined at the hip with someone incapable of rudimentary Luminatics.",
  ui_story_5031_50310602_18_dialog_content = "You would have already qualified by now without the hindrance of this Caelestite—even if he is supposedly helping.",
  ui_story_5031_50310602_19_dialog_content = "I see in the Caelestite the same hapless dependency of all commoners.",
  ui_story_5031_50310602_20_dialog_content = "Wh-What?!",
  ui_story_5031_50310602_21_dialog_content = "Don't pay him any mind.",
  ui_story_5031_50310602_22_dialog_content = "What?",
  ui_story_5031_50310602_23_dialog_content = "He's a little twisted inside.",
  ui_story_5031_50310602_24_dialog_content = "Hey! What are you saying?!",
  ui_story_5031_50310602_25_dialog_content = "Tell me more! I want to hear more.",
  ui_story_5031_50310602_26_dialog_content = "He usually pretends to be easygoing.",
  ui_story_5031_50310602_27_dialog_content = "But he, in fact, hates commoners.",
  ui_story_5031_50310602_28_dialog_content = "But he's built up a massive neurosis against commoners...",
  ui_story_5031_50310602_29_dialog_content = "Which is funny considering his own background...",
  ui_story_5031_50310602_30_dialog_content = "Hey! Not another word! I forbid it! Return to your silence!",
  ui_story_5031_50310602_31_dialog_content = "You will hear and obey! Stop!",
  ui_story_5031_50310602_32_dialog_content = "... Shut up!",
  ui_story_5031_50310602_33_dialog_content = "Tut.",
  ui_story_5031_50310602_34_dialog_content = "I thought the nobles of Lumopolis all looked down on commoners to different extents.",
  ui_story_5031_50310602_35_dialog_content = "It's not the same.",
  ui_story_5031_50310602_X35_dialog_content = "He washes his hand at least ten times if someone touches his hand by accident.",
  ui_story_5031_50310602_X36_dialog_content = "He screams when dust falls onto him.",
  ui_story_5031_50310602_36_dialog_content = "Ooh... May as well live within a case and do away with the outside world.",
  ui_story_5031_50310602_37_dialog_content = "Yes, he's obsessed with cleanliness to a crazy level.",
  ui_story_5031_50310602_38_dialog_content = "I'm so sorry to hear that...",
  ui_story_5031_50310602_39_dialog_content = "I don't need pity from a backwater lass like yourself!",
  ui_story_5031_50310602_40_dialog_content = "He slacks off at work.",
  ui_story_5031_50310602_41_dialog_content = "Lazy at work, you say? You're not painting an impressive picture.",
  ui_story_5031_50310602_42_dialog_content = "And takes advantage of the sentiments of his old classmates.",
  ui_story_5031_50310602_X42_dialog_content = "Pushes things to Pittma...",
  ui_story_5031_50310602_43_dialog_content = "<color=#e8d9bb>Ring-ring!</color>",
  ui_story_5031_50310602_44_dialog_content = "It's changing color! Hold your horses, everyone!",
  ui_story_5031_50310602_45_dialog_content = "Oh no!",
  ui_story_5031_50310602_46_dialog_content = "I can't stop sprinting! Help me!",
  ui_story_5031_50310602_47_dialog_content = "G-Get away from me, dirty commoner!",
  ui_story_5031_50310602_48_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5031_50310602_49_dialog_content = "I-I'm so sorry, sir.",
  ui_story_5031_50310602_50_dialog_content = "Get... away! Away!",
  ui_story_5031_50310602_51_dialog_content = "My clothes! I need to get to a changing room!",
  ui_story_5031_50310602_52_dialog_content = "I'm going back for a bath, Loewe!",
  ui_story_5031_50310602_53_dialog_content = "He's a fussy eater.",
  ui_story_5031_50310602_54_dialog_content = "He says his tongue is sensitive to heat.",
  ui_story_5031_50310602_55_dialog_content = "Screaming things like: \"Ah! It's so hot!\"",
  ui_story_5031_50310602_56_dialog_content = "And makes me take a look at it!",
  ui_story_5031_50310602_57_dialog_content = "I don't want to look at it at all.",
  ui_story_5031_50310602_58_dialog_content = "Three have been eliminated!",
  ui_story_5031_50310602_59_dialog_content = "Talk to you later!",
  ui_story_5031_50310602_60_dialog_content = "I got such a different feeling from the impression of the appearance. This short and concise way of talking is impressive.",
  ui_story_5031_50310602_X60_dialog_content = "Yes, this seems like an interesting person.",
  ui_story_5031_50310602_61_dialog_content = "I'm sorry, Carleen.",
  ui_story_5031_50310602_62_dialog_content = "For what? Don't listen to anything Matthieu said.",
  ui_story_5031_50310602_63_dialog_content = "You're trying so hard, but I'm not much good in a fight. Sometimes I do think I'm letting you down.",
  ui_story_5031_50310602_64_dialog_content = "You think I'm trying too hard? Is that why you're saying that?",
  ui_story_5031_50310602_65_dialog_content = "Yeah. I think you've been the top competitor in this carnival... carrying our team on your shoulders.",
  ui_story_5031_50310602_66_dialog_content = "You think so...?",
  ui_story_5031_50310602_67_dialog_content = "I've never considered you a burden. In fact, you're our secret weapon with all the things you can do!",
  ui_story_5031_50310602_68_dialog_content = "Of course, PlayerName. You've always been a very important teammate.",
  ui_story_5031_50310602_69_dialog_content = "Goodness gracious. PlayerName, you can't let yourself be influenced by what some random weirdo says.",
  ui_story_5031_50310602_70_dialog_content = "Everyone...",
  ui_story_5031_50310602_71_dialog_content = "<color=#e8d9bb>Ring-ring!</color>",
  ui_story_5031_50310602_72_dialog_content = "It's green now. Get ready!",
  ui_story_5031_50310602_73_dialog_content = "Okay. Everyone, go straight ahead!",
  ui_story_5031_50310701_1_dialog_content = "We're almost there, PlayerName.",
  ui_story_5031_50310701_2_dialog_content = "Just a few more steps to the next round...",
  ui_story_5031_50310701_3_dialog_content = "<color=#e8d9bb>Ring-ring!</color>",
  ui_story_5031_50310701_4_dialog_content = "Everyone, move!",
  ui_story_5031_50310701_5_dialog_content = "Wait, stop!",
  ui_story_5031_50310701_6_dialog_content = "It's back to the original color now!",
  ui_story_5031_50310701_7_dialog_content = "<color=#e8d9bb>Ring-ring!</color>",
  ui_story_5031_50310701_8_dialog_content = "What happened? Is it getting faster?",
  ui_story_5031_50310701_9_dialog_content = "Ouch!",
  ui_story_5031_50310701_10_dialog_content = "Yikes. It's turning really fast now!",
  ui_story_5031_50310701_11_dialog_content = "They're testing reaction times—otherwise, why make it so unpredictable?",
  ui_story_5031_50310701_12_dialog_content = "We gotta tread carefully now.",
  ui_story_5031_50310701_13_dialog_content = "Another four contestants are eliminated!",
  ui_story_5031_50310701_14_dialog_content = "You see that girl over there, Carleen? I think something's wrong with her.",
  ui_story_5031_50310701_15_dialog_content = "She doesn't look too happy. I can sense her Lumina power getting weaker by the second.",
  ui_story_5031_50310701_16_dialog_content = "Boo-hoo...",
  ui_story_5031_50310701_17_dialog_content = "Oh no. She's collapsed!",
  ui_story_5031_50310701_18_dialog_content = "Doesn't that mean she's going to be thrown into the water?",
  ui_story_5031_50310701_19_dialog_content = "Looks like she's in pain with her eyes close.",
  ui_story_5031_50310701_20_dialog_content = "They can't throw her in the sea if she's got a medical condition!",
  ui_story_5031_50310701_21_dialog_content = "PlayerName, PlayerName, we gotta think of something.",
  ui_story_5031_50310701_22_dialog_content = "Grah...",
  ui_story_5031_50310701_23_dialog_content = "We can't wait any longer!",
  ui_story_5031_50310701_24_dialog_content = "Carleen!",
  ui_story_5031_50310702_1_dialog_content = "Time-out!!",
  ui_story_5031_50310702_2_dialog_content = "Whatever is the matter, Your Highness?",
  ui_story_5031_50310702_3_dialog_content = "This lady is unwell.",
  ui_story_5031_50310702_4_dialog_content = "I'll have a look. I know some first aid.",
  ui_story_5031_50310702_5_dialog_content = "Are you alright, young lady? Can you hear me?",
  ui_story_5031_50310702_6_dialog_content = "Boo-hoo...",
  ui_story_5031_50310702_7_dialog_content = "I know the condition... Modali Syndrome.",
  ui_story_5031_50310702_8_dialog_content = "Quick, take this pill.",
  ui_story_5031_50310702_9_dialog_content = "Can I trouble you to bring that blanket, Jeno?",
  ui_story_5031_50310702_10_dialog_content = "Sure.",
  ui_story_5031_50310702_11_dialog_content = "Huff, puff...",
  ui_story_5031_50310702_12_dialog_content = "Laird Elvis... Thank you. I'm feeling much better.",
  ui_story_5031_50310702_13_dialog_content = "Don't overexert yourself. Your body temperature's low. You'll be more comfortable in a blanket.",
  ui_story_5031_50310702_14_dialog_content = "Yes... Thank you, sir—you taught us the aerobic exercises, and I've always drank warm water.",
  ui_story_5031_50310702_15_dialog_content = "Yes, very good, Ranka. I'm proud of you.",
  ui_story_5031_50310702_16_dialog_content = "The blanket, Elvis.",
  ui_story_5031_50310702_17_dialog_content = "Ah. Thank you.",
  ui_story_5031_50310702_18_dialog_content = "Patou!",
  ui_story_5031_50310702_19_dialog_content = "Here I am, sir.",
  ui_story_5031_50310702_20_dialog_content = "Have the guards take her back to her family and impress upon them the urgency of a hospital visit.",
  ui_story_5031_50310702_21_dialog_content = "Leave it to me, sir!",
  ui_story_5031_50310702_22_dialog_content = "Do you see how young she is, Jeno?",
  ui_story_5031_50310702_23_dialog_content = "...",
  ui_story_5031_50310702_24_dialog_content = "Laird Elvis, you are a faithful and kind-hearted laird to Harbor City.",
  ui_story_5031_50310702_25_dialog_content = "I've seen more nobility from you today than from a lifetime of many so-called nobles.",
  ui_story_5031_50310702_26_dialog_content = "Harbor City is truly fortunate to have a laird such as yourself.",
  ui_story_5031_50310702_27_dialog_content = "Sheesh. She's just another commoner. I think you've lost perspective, Your Highness.",
  ui_story_5031_50310702_28_dialog_content = "So unpleasant to be... semi-assaulted by that eliminated commoner.",
  ui_story_5031_50310702_29_dialog_content = "I was nearly cast into the sea. But I managed to get back up.",
  ui_story_5031_50310702_30_dialog_content = "When on earth can we return for a bath and change of clothes?",
  ui_story_5031_50310702_31_dialog_content = "Quiet.",
  ui_story_5031_50310702_32_dialog_content = "Thank you for your kind words, Your Highness.",
  ui_story_5031_50310702_33_dialog_content = "But I can't help much more than that.",
  ui_story_5031_50310702_34_dialog_content = "I'm sorry, but urgent duty calls. Until later.",
  ui_story_5031_50310702_35_dialog_content = "Certainly.",
  ui_story_5031_50310702_36_dialog_content = "...",
  ui_story_5031_50310702_37_dialog_content = "You sent for me, sir?",
  ui_story_5031_50310702_38_dialog_content = "We are running out of time, Patou.",
  ui_story_5031_50310702_39_dialog_content = "The <color=#FFB400>Windstone</color> grows weaker. I can feel it.",
  ui_story_5031_50310702_40_dialog_content = "That's why I, and then the girl, fell under this malady.",
  ui_story_5031_50310702_41_dialog_content = "I'm afraid the seal may not last much longer.",
  ui_story_5031_50310702_42_dialog_content = "Why not seek help from Lumopolis, sir? Princess Carleen seemed different from the other nobles.",
  ui_story_5031_50310702_43_dialog_content = "She might put us in touch with Lord Schwartz and aid us.",
  ui_story_5031_50310702_44_dialog_content = "While I personally believe that Lord Schwartz has the insight to help us in this matter...",
  ui_story_5031_50310702_45_dialog_content = "I don't have any faith in the Elder Council.",
  ui_story_5031_50310702_46_dialog_content = "What is more likely? That they will send troops to defend Harbor City? Or that they'll ask us to vacate the land we've inhabited for generations?",
  ui_story_5031_50310702_47_dialog_content = "Think of the cost paid by our ancestors to protect the secret of the Windstone... It's well-kept even today.",
  ui_story_5031_50310702_48_dialog_content = "If news of its existence spreads, we'd have to contend with those who want to take it.",
  ui_story_5031_50310702_49_dialog_content = "Harbor City is lost without the Windstone.",
  ui_story_5031_50310702_50_dialog_content = "This home of ours that our forefathers gave their lives to protect and in which we've established ourselves for generations would be lost.",
  ui_story_5031_50310702_51_dialog_content = "Everything I'm doing is for the safety and security of Harbor City. The reality is that we are on our own.",
  ui_story_5031_50310702_52_dialog_content = "Yes... sir. I understand.",
  ui_story_5031_50310702_53_dialog_content = "We gladly offer our lives in defense of Harbor City and House Modali.",
  ui_story_5031_50310702_54_dialog_content = "We've reached the point of no return.",
  ui_story_5031_50310702_55_dialog_content = "Defeat will mean the end of Harbor City, and its residents. No one is coming to save us.",
  ui_story_5031_50310702_56_dialog_content = "We must learn how to save ourselves, Patou.",
  ui_story_5031_50310702_57_dialog_content = "Princess Carleen, are you sure to keep your identity hidden?",
  ui_story_5031_50310702_58_dialog_content = "Yes. I don't want anything to come between me and our relaxing holiday. Thank you for understanding, Laird Elvis.",
  ui_story_5031_50310702_59_dialog_content = "Very well.",
  ui_story_5031_50310702_60_dialog_content = "Listen to me, everyone.",
  ui_story_5031_50310702_61_dialog_content = "The lady who just collapsed from sickness would have been thrown overboard by Eclipsites according to our rules.",
  ui_story_5031_50310702_62_dialog_content = "Yet this brave lady and her companions risked disqualification to save her from a dangerous situation!",
  ui_story_5031_50310702_63_dialog_content = "She could have fallen unconscious into the water.",
  ui_story_5031_50310702_64_dialog_content = "They may have broken the rules, but we reward the kind of heart here in Harbor City!",
  ui_story_5031_50310702_65_dialog_content = "... And since this is our custom, I hope you will join me in welcoming their team back into the competition!",
  ui_story_5031_50310702_66_dialog_content = "Hooray! Hooray!",
  ui_story_5031_50310702_67_dialog_content = "You're awesome, Laird Elvis!",
  ui_story_5031_50310702_68_dialog_content = "Thank you, all! I'm honored to be your governor.",
  ui_story_5031_50310702_69_dialog_content = "Thank you, Laird Elvis!",
  ui_story_5031_50310702_70_dialog_content = "Don't mention it. I'm sure you all would have done the same.",
  ui_story_5031_50310702_71_dialog_content = "You and your companions may return to the match.",
  ui_story_5031_50310702_X71_dialog_content = "Then let's continue!",
  ui_story_5031_50310702_X72_dialog_content = "Huff, huff...! You guys are running too fast. We've even reached the finish line somehow.",
  ui_story_5031_50310702_X73_dialog_content = "Hurry up, PlayerName! It's changing colors again!",
  ui_story_5031_50310702_X74_dialog_content = "Seriously? No, I can't do it anymore.",
  ui_story_5031_50310702_72_dialog_content = "Sprint here, PlayerName. We'll catch you!",
  ui_story_5031_50310702_73_dialog_content = "Got it!",
  ui_story_5031_50310702_74_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5031_50310702_75_dialog_content = "That was close.",
  ui_story_5031_50310702_76_dialog_content = "You're very heavy, PlayerName.",
  ui_story_5031_50310702_77_dialog_content = "We did it!",
  ui_story_5031_50310702_78_dialog_content = "We're in the next round!",
  ui_story_5031_50310702_79_dialog_content = "But a lot of other strong competitors made it too.",
  ui_story_5031_50310702_80_dialog_content = "That person making a scene... is that Officer Gronru?",
  ui_story_5031_50310702_81_dialog_content = "Hey! Hurry up, Ciel!",
  ui_story_5031_50310702_82_dialog_content = "Come on, use your ultimate!",
  ui_story_5031_50310702_83_dialog_content = "Or we're going to be eliminated!",
  ui_story_5031_50310702_84_dialog_content = "C-Ce, but <color=#FFB400>Styx</color> is still...",
  ui_story_5031_50310702_85_dialog_content = "Uh... Okay. \"Leg mech status update—Mark II.\"",
  ui_story_5031_50310702_86_dialog_content = "\"Increase power release by 50%.\"",
  ui_story_5031_50310702_87_dialog_content = "Let's go!",
  ui_story_5031_50310702_88_dialog_content = "Woah! Ciel just went straight over!",
  ui_story_5031_50310702_89_dialog_content = "Ahhh! Out of the way, everyone! I lost control of Styx!",
  ui_story_5031_50310702_90_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5031_50310702_91_dialog_content = "V-Very impressive. It even left a hole in the building.",
  ui_story_5031_50310702_92_dialog_content = "And a rather lengthy mark on the deck.",
  ui_story_5031_50310702_93_dialog_content = "Wow, that's just incredible. Where did she go?",
  ui_story_5031_50310702_94_dialog_content = "Are you alright, Ciel?",
  ui_story_5031_50310702_95_dialog_content = "Ouch, ouch! I-I don't think I'm injured.",
  ui_story_5031_50310702_96_dialog_content = "You may not be injured, but I can't say the same for our beloved Emerald.",
  ui_story_5031_50310702_97_dialog_content = "Oh. I-I'm so sorry!",
  ui_story_5031_50310702_98_dialog_content = "I didn't mean to! I haven't finished debugging Styx—no, it's my fault for being weak...",
  ui_story_5031_50310702_99_dialog_content = "It's alright. I'm not interested in blame. Let's just think of what to do next.",
  ui_story_5031_50310702_100_dialog_content = "Ideally, we'd just hire someone to repair it.",
  ui_story_5031_50310702_101_dialog_content = "But I don't think Ciel is a child of money.",
  ui_story_5031_50310702_102_dialog_content = "You're right. I'm sorry about that...",
  ui_story_5031_50310702_103_dialog_content = "Stop apologizing. Come on. It's alright!",
  ui_story_5031_50310702_104_dialog_content = "That reminds me! You can challenge our next round—a surfing contest!",
  ui_story_5031_50310702_105_dialog_content = "Laird Elvis is sponsoring the next round with an extra prize for the winner.",
  ui_story_5031_50310702_106_dialog_content = "R-Really!?",
  ui_story_5031_50310702_107_dialog_content = "Indeed! And I'm pretty sure... it's five million Nightium!",
  ui_story_5031_50310702_108_dialog_content = "That's enough to cover the repair costs.",
  ui_story_5031_50310702_109_dialog_content = "Wonderful! I'm in!",
  ui_story_5031_50310702_110_dialog_content = "Hey, let's not get ahead of ourselves.",
  ui_story_5031_50310702_111_dialog_content = "Myself and Merylt sisters are also joining.",
  ui_story_5031_50310702_112_dialog_content = "And I intend to win, Ciel!",
  ui_story_5031_50310702_113_dialog_content = "If you lose... oh, what's its name again? Styx, right?",
  ui_story_5031_50310702_114_dialog_content = "It will be mine.",
  ui_story_5031_50310702_115_dialog_content = "... I can't.",
  ui_story_5031_50310702_116_dialog_content = "Hey. I just want to borrow it to study it. I'm not going to steal it from you or anything like that.",
  ui_story_5031_50310702_117_dialog_content = "I'll return it after.",
  ui_story_5031_50310702_118_dialog_content = "I'm sorry.",
  ui_story_5031_50310702_119_dialog_content = "The thing is... I simply can't do that...",
  ui_story_5031_50310801_1_dialog_content = "Hey everyone! I hope the cool summer breeze and free fruit have got you all excited?",
  ui_story_5031_50310801_2_dialog_content = "You look well-rested and ready to get into the next round of competition!",
  ui_story_5031_50310801_3_dialog_content = "Yes!",
  ui_story_5031_50310801_4_dialog_content = "Oh, you look very excited! And looks like you can't wait any longer.",
  ui_story_5031_50310801_5_dialog_content = "So this time we get to wipe away some of the sweat we've accumulated.",
  ui_story_5031_50310801_6_dialog_content = "It's time for a cool dip in the big bath of the sea under this hot sun!",
  ui_story_5031_50310801_7_dialog_content = "It's the moment you've all been waiting for—a <size=45>surfing contest</size>!",
  ui_story_5031_50310801_8_dialog_content = "Wow!!",
  ui_story_5031_50310801_9_dialog_content = "And because it's a tradition to have surfing contests in Harbor City, the winning team...",
  ui_story_5031_50310801_10_dialog_content = "... They will also receive a special reward from Laird Elvis of <color=#FFB400>five million Nightium</color>!",
  ui_story_5031_50310801_11_dialog_content = "F-Five million?",
  ui_story_5031_50310801_12_dialog_content = "Five million!?",
  ui_story_5031_50310801_13_dialog_content = "PlayerName, Vice! Control yourselves.",
  ui_story_5031_50310801_14_dialog_content = "Don't forget why we're here.",
  ui_story_5031_50310801_15_dialog_content = "Yeah... But maybe we can win some money while helping Fia get that wondrous beast.",
  ui_story_5031_50310801_16_dialog_content = "Harbor City is pretty wealthy, eh?",
  ui_story_5031_50310801_17_dialog_content = "Indeed it is. They've seen a boom in recent years.",
  ui_story_5031_50310801_18_dialog_content = "It's not every day you see a laird throw out a huge prize to his people.",
  ui_story_5031_50310801_19_dialog_content = "No wonder Harbor City is going well if that's what Laird Elvis is up to.",
  ui_story_5031_50310801_20_dialog_content = "You seem to be working really hard lately.",
  ui_story_5031_50310801_21_dialog_content = "Even though we're on vacation, you're still fretting over the continent's economic problems.",
  ui_story_5031_50310801_22_dialog_content = "Ah, sorry, I must be boring you guys...",
  ui_story_5031_50310801_23_dialog_content = "No, not at all. That's not what I meant.",
  ui_story_5031_50310801_24_dialog_content = "I was just worried about you overworking yourself.",
  ui_story_5031_50310801_25_dialog_content = "Yes, Carleen! It's not worth the stress. Let's loosen up!",
  ui_story_5031_50310801_26_dialog_content = "Look how much fun Fia's having with that pineapple.",
  ui_story_5031_50310801_27_dialog_content = "I'm sure she's well and truly distracted from her grand scheme.",
  ui_story_5031_50310801_28_dialog_content = "Yum! It's really sweet!",
  ui_story_5031_50310801_29_dialog_content = "It's great, you know, they have free fruits!",
  ui_story_5031_50310801_30_dialog_content = "Yeah. It is indeed.",
  ui_story_5031_50310801_31_dialog_content = "I have a lot to learn from Fia.",
  ui_story_5031_50310801_32_dialog_content = "<size=33>And not just her, but also Vice and PlayerName, too...</size>",
  ui_story_5031_50310801_33_dialog_content = "You and I both know the Eclipsites cannot be wiped out.",
  ui_story_5031_50310801_34_dialog_content = "A ruler should exercise more restraint—not rush into the thick of things to accomplish everything on your own.",
  ui_story_5031_50310801_35_dialog_content = "You wouldn't only be harming yourself, but also those who follow you.",
  ui_story_5031_50310801_36_dialog_content = "...",
  ui_story_5031_50310801_37_dialog_content = "I want you to really consider why I'm sending you to travel around the world with PlayerName.",
  ui_story_5031_50310801_38_dialog_content = "I...",
  ui_story_5031_50310801_39_dialog_content = "Your perspective on being a ruler needs maturing.",
  ui_story_5031_50310801_40_dialog_content = "... Yes, Father.",
  ui_story_5031_50310801_41_dialog_content = "Carleen? Carleen!",
  ui_story_5031_50310801_42_dialog_content = "Huh? I'm sorry, what did you say?",
  ui_story_5031_50310801_43_dialog_content = "I was just saying maybe we should go change? We'll be spending a lot of time in the water for sure.",
  ui_story_5031_50310801_44_dialog_content = "Can't stain your new clothes!",
  ui_story_5031_50310801_45_dialog_content = "Ah. Very well.",
  ui_story_5031_50310801_46_dialog_content = "Wait—what should I change into?",
  ui_story_5031_50310801_47_dialog_content = "Heh! That would naturally be—",
  ui_story_5031_50310801_48_dialog_content = "Swimsuit!",
  ui_story_5031_50310801_49_dialog_content = "Wow! You look great, Carleen and Vice!",
  ui_story_5031_50310801_50_dialog_content = "Thanks, Fia.",
  ui_story_5031_50310801_51_dialog_content = "H-How come you brought my swimsuit along too?",
  ui_story_5031_50310801_52_dialog_content = "Who doesn't bring a swimsuit to the beach?",
  ui_story_5031_50310801_53_dialog_content = "These are our first watersports, so I didn't think to take it out 'til now.",
  ui_story_5031_50310801_54_dialog_content = "I wish I had a swimsuit, too!",
  ui_story_5031_50310801_55_dialog_content = "We'll head straight for a Harbor City fashion outlet after to order one for you!",
  ui_story_5031_50310801_56_dialog_content = "Really? Thanks, Vice!",
  ui_story_5031_50310801_57_dialog_content = "Wow. First time I've ever had swimwear custom ordered for me. Awesome!",
  ui_story_5031_50310801_58_dialog_content = "I also noticed some really nice utensils before. Maybe we can buy those too!",
  ui_story_5031_50310801_59_dialog_content = "Great!",
  ui_story_5031_50310801_60_dialog_content = "Also...",
  ui_story_5031_50310801_61_dialog_content = "Ahem, I-I...",
  ui_story_5031_50310801_62_dialog_content = "Huh? What is it, PlayerName?",
  ui_story_5031_50310801_63_dialog_content = "I'm sorry for interrupting you in the middle of a great chat...",
  ui_story_5031_50310801_64_dialog_content = "But... I can't surf.",
  ui_story_5031_50310801_65_dialog_content = "<size=45>What?!</size>",
  ui_story_5031_50310801_66_dialog_content = "So that means I won't be getting my swimsuit?",
  ui_story_5031_50310801_67_dialog_content = "That's what you're worried about? Have you forgotten our real purpose here—your wondrous beast?",
  ui_story_5031_50310801_68_dialog_content = "My swimsuit as well as the Cloudwhale... Boo-hoo...",
  ui_story_5031_50310801_69_dialog_content = "... They are all out of reach! Waaaah!",
  ui_story_5031_50310801_70_dialog_content = "I'm so sorry, Fia. Don't cry!",
  ui_story_5031_50310801_71_dialog_content = "I'll think of a way—even if we don't get the first place...",
  ui_story_5031_50310801_72_dialog_content = "I'm sure we can find enough money for some swimwear!",
  ui_story_5031_50310801_73_dialog_content = "... Really?",
  ui_story_5031_50310801_74_dialog_content = "Yes! Carleen and Vice can vouch for me, can't you?",
  ui_story_5031_50310801_75_dialog_content = "T-That would be great!",
  ui_story_5031_50310801_76_dialog_content = "Sorry, I shouldn't have started fantasizing about winning the prize before asking about the situation clearly.",
  ui_story_5031_50310801_77_dialog_content = "It's not your fault, Vice. I'm just so uncoordinated. I can't even surf!",
  ui_story_5031_50310801_78_dialog_content = "Oh, no, you misunderstand, PlayerName.",
  ui_story_5031_50310801_79_dialog_content = "Not everyone is cut out for surfing.",
  ui_story_5031_50310801_80_dialog_content = "I just happened to have studied it before.",
  ui_story_5031_50310801_X80_dialog_content = "So did I. When I visited Harbor City in my childhood, I just watched the surfing competition that year.",
  ui_story_5031_50310801_X81_dialog_content = "That's why I became interested in it and found myself a teacher.",
  ui_story_5031_50310801_81_dialog_content = "Oh? So where did you learn surfing, Fia?",
  ui_story_5031_50310801_82_dialog_content = "Huh? I never learned to surf.",
  ui_story_5031_50310801_83_dialog_content = "What?!",
  ui_story_5031_50310801_84_dialog_content = "Then why were you crying? If you've never done it before and don't know how!",
  ui_story_5031_50310801_85_dialog_content = "How could you shout at me like that, Caelestite! You won't find a girlfriend with an attitude like that.",
  ui_story_5031_50310801_86_dialog_content = "A g-girlfriend?",
  ui_story_5031_50310801_87_dialog_content = "What are you talking about? Hey, come back!",
  ui_story_5031_50310801_88_dialog_content = "Woah! Everyone's heading for the water! We should go—now!",
  ui_story_5031_50310801_89_dialog_content = "... You're fast!",
  ui_story_5031_50310801_90_dialog_content = "...",
  ui_story_5031_50310801_91_dialog_content = "...",
  ui_story_5031_50310801_92_dialog_content = "(How did it get so awkward all of a sudden?)",
  ui_story_5031_50310801_93_dialog_content = "Ahem, so, we're going there now as well, are we?",
  ui_story_5031_50310801_94_dialog_content = "Yeah. I think so.",
  ui_story_5031_50310801_95_dialog_content = "Okay. Let's go.",
  ui_story_5031_50310801_96_dialog_content = "(What's got into them?)",
  ui_story_5031_50310801_97_dialog_content = "Right. Put both hands parallel around your lower chest and bring your feet together.",
  ui_story_5031_50310801_98_dialog_content = "Then use the strength in your arms to support your body.",
  ui_story_5031_50310801_99_dialog_content = "L-Like this?",
  ui_story_5031_50310801_100_dialog_content = "That's right. Stare straight ahead. You're doing well.",
  ui_story_5031_50310801_101_dialog_content = "When the wave comes up, that's your cue to stand. Keep your feet the same width as your shoulders and straighten your back.",
  ui_story_5031_50310801_102_dialog_content = "Here's a wave!",
  ui_story_5031_50310801_103_dialog_content = "Feel your surfboard gaining speed under the wave? It's happening!",
  ui_story_5031_50310801_104_dialog_content = "O-Okay!",
  ui_story_5031_50310801_105_dialog_content = "Standing up... Wow!",
  ui_story_5031_50310801_106_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5031_50310801_107_dialog_content = "PlayerName!",
  ui_story_5031_50310801_108_dialog_content = "*Coughing*",
  ui_story_5031_50310801_109_dialog_content = "I-I'm fine. I'm still alive...",
  ui_story_5031_50310801_110_dialog_content = "Come on, PlayerName. Don't be so weak.",
  ui_story_5031_50310801_111_dialog_content = "Even I know how to stand on a surfboard.",
  ui_story_5031_50310801_112_dialog_content = "You're not standing at all! You're clearly crouching!",
  ui_story_5031_50310801_113_dialog_content = "I'm still better than you!",
  ui_story_5031_50310801_114_dialog_content = "And with Carleen's idea, all I need to learn is to crouch!",
  ui_story_5031_50310801_115_dialog_content = "Don't forget I'm the only one who can ask the fish to come to help push my surfboard!",
  ui_story_5031_50310801_116_dialog_content = "You've got to be...",
  ui_story_5031_50310801_117_dialog_content = "The time has come!",
  ui_story_5031_50310801_118_dialog_content = "Wow! Great to see so many folks out there practicing on the waves. Good job!",
  ui_story_5031_50310801_119_dialog_content = "It looks like the promise of 5 million Nightium is extremely attractive!",
  ui_story_5031_50310801_120_dialog_content = "Haha!",
  ui_story_5031_50310801_121_dialog_content = "Heh! Just kidding!",
  ui_story_5031_50310801_122_dialog_content = "So let's start with the rules!",
  ui_story_5031_50310801_123_dialog_content = "As before, four people to a team. You'll take turns taking on the waves.",
  ui_story_5031_50310801_124_dialog_content = "If you don't have four people on your team, you can enter with fewer.",
  ui_story_5031_50310801_125_dialog_content = "You may enter with just two people, because only the two top performers on your team will be scored!",
  ui_story_5031_50310801_126_dialog_content = "As before, you get points for taking out Eclipsite illusions. But you're not going to be eliminated by falling in the water.",
  ui_story_5031_50310801_127_dialog_content = "Apart from Eclipsites, half of your points are going to come from your surfing technique.",
  ui_story_5031_50310801_128_dialog_content = "So I suggest organizing the order in which you're gonna go. It'll be very important!",
  ui_story_5031_50310801_129_dialog_content = "Oh no! I just revealed an important secret to winning. I guess it'll make the contest much more intense!",
  ui_story_5031_50310801_130_dialog_content = "Hahahahaha!",
  ui_story_5031_50310801_131_dialog_content = "Anyway—have fun, everybody!",
  ui_story_5031_50310801_132_dialog_content = "We're just about to start round one—in a moment.",
  ui_story_5031_50310801_133_dialog_content = "Would all teams please line up? And can we have the first player from each team by the starting location?",
  ui_story_5031_50310801_134_dialog_content = "I want to let you all in on a little secret...",
  ui_story_5031_50310801_135_dialog_content = "Our first surfer today is going to be... me!",
  ui_story_5031_50310801_136_dialog_content = "Yeah!",
  ui_story_5031_50310801_137_dialog_content = "You can sure surf, Rainbow!",
  ui_story_5031_50310801_138_dialog_content = "Rainbow is really winning the crowd.",
  ui_story_5031_50310801_139_dialog_content = "She must be awesome at this. She's got a lot of confidence.",
  ui_story_5031_50310801_140_dialog_content = "Oh well. Anyway, the rules say only the two best scorers will count, so it could be good for us.",
  ui_story_5031_50310801_141_dialog_content = "That's why the order you go in is really important.",
  ui_story_5031_50310801_142_dialog_content = "So if they have Rainbow starting for their team, then we should...",
  ui_story_5031_50310801_143_dialog_content = "Hmph! Isn't it obvious I should go first? I'm the best!",
  ui_story_5031_50310801_144_dialog_content = "... You? The best?",
  ui_story_5031_50310801_145_dialog_content = "What are you implying?",
  ui_story_5031_50310801_146_dialog_content = "Don't forget I'm the only one who managed to follow Carleen's instructions just then!",
  ui_story_5031_50310801_147_dialog_content = "It's a sure thing! I'll win easily.",
  ui_story_5031_50310801_148_dialog_content = "You can stand here and wait for my triumphant return, PlayerName!",
  ui_story_5031_50310801_149_dialog_content = "... Is it really going to be that easy?",
  ui_story_5031_50310801_150_dialog_content = "Something about her swagger is making me even more concerned.",
  ui_story_5031_50310801_151_dialog_content = "Ahem, I'll need to emcee this one since Rainbow has involved herself.",
  ui_story_5031_50310801_152_dialog_content = "Uh... I must say that you all seem rather small from this vantage point, bobbing up and down on the waves...",
  ui_story_5031_50310801_153_dialog_content = "Small though you are, you have mastered the natural laws of motion, allowing you to surf.",
  ui_story_5031_50310801_154_dialog_content = "It is nothing less than an art form of supreme wit and aesthetic sense...",
  ui_story_5031_50310801_155_dialog_content = "Farewell, all! Ride the rhythms of these waves, and conquer...",
  ui_story_5031_50310801_156_dialog_content = "... Enough! Let's start! Start!",
  ui_story_5031_50310801_157_dialog_content = "We're waiting!",
  ui_story_5031_50310801_158_dialog_content = "Tsk. I just can't understand mediocre fools.",
  ui_story_5031_50310801_159_dialog_content = "Since you're all so impatient, then let's start. Go!",
  ui_story_5031_50310801_160_dialog_content = "...",
  ui_story_5031_50310801_161_dialog_content = "Huh? That's it?",
  ui_story_5031_50310801_162_dialog_content = "We want another emcee!",
  ui_story_5031_50310801_163_dialog_content = "Haha! Poor Jeno.",
  ui_story_5031_50310801_164_dialog_content = "In that case, I'd better go!",
  ui_story_5031_50310801_165_dialog_content = "Come on, Ciel! It's started! Quick!",
  ui_story_5031_50310801_166_dialog_content = "It's already started? Wasn't there some sort of signal?",
  ui_story_5031_50310801_167_dialog_content = "O-Oh, dear. \"Leg mech status update—Spray Mode\"!",
  ui_story_5031_50310801_168_dialog_content = "Are they surfing on a mech?",
  ui_story_5031_50310801_169_dialog_content = "The waves just swept those contestants into the sea!",
  ui_story_5031_50310801_170_dialog_content = "What are we supposed to do about that?",
  ui_story_5031_50310801_171_dialog_content = "It's alright. Fia's pretty far away now... and seems to be going steady.",
  ui_story_5031_50310801_172_dialog_content = "Oooh! Off you go, Rainbow!!",
  ui_story_5031_50310801_173_dialog_content = "Wow! She turns like a pro!",
  ui_story_5031_50310801_174_dialog_content = "That girl in the mech isn't half-bad either. She's fast!",
  ui_story_5031_50310801_175_dialog_content = "But doesn't look quite as good on a board as Rainbow.",
  ui_story_5031_50310801_176_dialog_content = "Hmph. The contest is far from as simple as you might think.",
  ui_story_5031_50310801_177_dialog_content = "Roar! Cursed creatures from the deep!",
  ui_story_5031_50310801_178_dialog_content = "Graaaah!",
  ui_story_5031_50310801_179_dialog_content = "They're here!",
  ui_story_5031_50310801_180_dialog_content = "Heh! Rainbow is about to transform again!",
  ui_story_5031_50310801_181_dialog_content = "Ooh. Careful, Rainbow!",
  ui_story_5031_50310801_182_dialog_content = "Huh? There are Eclipsites coming out of the waves!",
  ui_story_5031_50310801_183_dialog_content = "That's going to be a bit difficult...",
  ui_story_5031_50310801_184_dialog_content = "R-Rainbow?",
  ui_story_5031_50310801_185_dialog_content = "Yeaaaaah!",
  ui_story_5031_50310801_186_dialog_content = "I've put up with you long enough, wretched Eclipsites!",
  ui_story_5031_50310801_187_dialog_content = "<size=45>Die!</size>",
  ui_story_5031_50310801_188_dialog_content = "You don't look too happy. Are you thinking about that Ranka girl?",
  ui_story_5031_50310802_X1_dialog_content = "You don't look too happy. Are you thinking about that Ranka girl?",
  ui_story_5031_50310802_1_dialog_content = "Oh, uh, yeah...",
  ui_story_5031_50310802_2_dialog_content = "Let me get you some fruit. You need to stay hydrated.",
  ui_story_5031_50310802_3_dialog_content = "Thank you, Jeno.",
  ui_story_5031_50310802_4_dialog_content = "Is that medicine you just gave her the \"solution\" you were talking about?",
  ui_story_5031_50310802_5_dialog_content = "Not at all. It's something I invented after studying the old texts. It's just for temporary pain relief.",
  ui_story_5031_50310802_6_dialog_content = "And yet you invented it?",
  ui_story_5031_50310802_7_dialog_content = "Once upon a time, you wanted to be a chef. But you became a pharmacist?",
  ui_story_5031_50310802_8_dialog_content = "Heh! Harbor City does not need more chefs, but we need someone who understands Modali Syndrome very well.",
  ui_story_5031_50310802_9_dialog_content = "So, in other words, you sacrificed your dream to do something great with your life?",
  ui_story_5031_50310802_10_dialog_content = "I never wanted to become great. I just don't want to stand by while others are in pain.",
  ui_story_5031_50310802_11_dialog_content = "And I'm not much of a pharmacist. I just copied what I read in the ancient scrolls. It was easy.",
  ui_story_5031_50310802_12_dialog_content = "I'll feel free to pursue my dreams once I figure out Modali Syndrome.",
  ui_story_5031_50310802_13_dialog_content = "And what would you do then?",
  ui_story_5031_50310802_14_dialog_content = "I might try my hand at opening a chain of high-class art halls with restaurants attached.",
  ui_story_5031_50310802_15_dialog_content = "You still remember that promise from all those years ago?",
  ui_story_5031_50310802_16_dialog_content = "It's been so long... I thought you'd forgotten.",
  ui_story_5031_50310802_17_dialog_content = "I have an excellent memory. I even remember little things—like that portrait you were meant to paint for me.",
  ui_story_5031_50310802_18_dialog_content = "I've kept a space empty in the Harbor City art gallery.",
  ui_story_5031_50310802_19_dialog_content = "...",
  ui_story_5031_50310802_20_dialog_content = "So is there anything I can do to help?",
  ui_story_5031_50310802_21_dialog_content = "What do you mean?",
  ui_story_5031_50310802_22_dialog_content = "Is there something I can do to help you with this \"Modali Syndrome\"?",
  ui_story_5031_50310802_23_dialog_content = "...",
  ui_story_5031_50310802_24_dialog_content = "Actually...",
  ui_story_5031_50310802_25_dialog_content = "Woah! Rainbow is amazing!",
  ui_story_5031_50310802_26_dialog_content = "A perfect blend of power and beauty!",
  ui_story_5031_50310802_27_dialog_content = "... What were you saying?",
  ui_story_5031_50310802_28_dialog_content = "It's alright. Let's enjoy the event first.",
  ui_story_5031_50310802_29_dialog_content = "I should try to be a good judge. Wouldn't want to let the contestants down.",
  ui_story_5031_50310802_30_dialog_content = "Rainbow is really strong—and scary too...",
  ui_story_5031_50310802_31_dialog_content = "Y-You're right.",
  ui_story_5031_50310802_32_dialog_content = "Don't say that about Rainbow, beansprout!",
  ui_story_5031_50310802_33_dialog_content = "Yeah. Even if Merylt cares about you!",
  ui_story_5031_50310802_34_dialog_content = "Oh, I'm so sorry. I meant it in a good way!",
  ui_story_5031_50310802_35_dialog_content = "I'm just so awestruck by her fearless display of spirit...",
  ui_story_5031_50310802_36_dialog_content = "Don't go causing trouble, Subli.",
  ui_story_5031_50310802_37_dialog_content = "Rainbow really, really hates Eclipsites. That's why she's doing that.",
  ui_story_5031_50310802_38_dialog_content = "She hates Eclipsites?",
  ui_story_5031_50310802_39_dialog_content = "Yeah...",
  ui_story_5031_50310802_40_dialog_content = "Rainbow's village was destroyed by the Eclipsites.",
  ui_story_5031_50310802_41_dialog_content = "That's how she lost her friends and family.",
  ui_story_5031_50310802_42_dialog_content = "Which is why Rainbow gets mad whenever she sees Eclipsites—even illusions.",
  ui_story_5031_50310802_43_dialog_content = "She's a really sweet and gentle person. It's just with Eclipsites.",
  ui_story_5031_50310802_44_dialog_content = "Yeah. I love Rainbow!",
  ui_story_5031_50310802_45_dialog_content = "Me too. I like her a lot more than our ringmaster—he always looks fierce.",
  ui_story_5031_50310802_46_dialog_content = "I think... our ringmaster is nice...",
  ui_story_5031_50310802_47_dialog_content = "Only you would say something like that!",
  ui_story_5031_50310802_48_dialog_content = "So that's why...",
  ui_story_5031_50310802_49_dialog_content = "Looking at Rainbow's sunny attitude, it's hard to believe she has such a tragic past.",
  ui_story_5031_50310802_50_dialog_content = "Sometimes the happiest, sweetest girls are the ones with the most painful, tragic pasts.",
  ui_story_5031_50310802_51_dialog_content = "I respect her.",
  ui_story_5031_50310802_52_dialog_content = "Right. I can't help but feel I'm lucky not to be the first to go out there...",
  ui_story_5031_50310802_53_dialog_content = "Hey... What's going on with Fia?",
  ui_story_5031_50310802_54_dialog_content = "Stop coming to my surfboard from everywhere at once!",
  ui_story_5031_50310802_55_dialog_content = "Pick a direction!",
  ui_story_5031_50310802_56_dialog_content = "Yikes. Wrong way! Not there! Woah!",
  ui_story_5031_50310802_57_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5031_50310802_58_dialog_content = "Haha! How did that girl manage a 360-degree turn?",
  ui_story_5031_50310802_59_dialog_content = "Now she's taking a dip. She's not going to win many points for style.",
  ui_story_5031_50310802_60_dialog_content = "*Coughing*",
  ui_story_5031_50310802_61_dialog_content = "Stupid fish!",
  ui_story_5031_50310802_62_dialog_content = "PlayerName is going to laugh at me for sure, boo-hoo...",
  ui_story_5031_50310802_63_dialog_content = "Fia must be worrying about me laughing at her now.",
  ui_story_5031_50310802_64_dialog_content = "But... haha!",
  ui_story_5031_50310802_65_dialog_content = "I must say that's very funny, hahaha!",
  ui_story_5031_50310802_66_dialog_content = "Don't laugh so loudly, PlayerName.",
  ui_story_5031_50310802_67_dialog_content = "It's my fault. I didn't expect Fia to have coordination problems with the fish.",
  ui_story_5031_50310802_68_dialog_content = "It was a bit unrealistic to hope she could win with fish communication.",
  ui_story_5031_50310802_69_dialog_content = "No, no. Fia said it'd be a piece of cake!",
  ui_story_5031_50310802_70_dialog_content = "You can't keep blaming yourself for everything, Carleen. It's just a game anyway. Who cares?",
  ui_story_5031_50310802_71_dialog_content = "... Yeah.",
  ui_story_5031_50310802_72_dialog_content = "Let me give you some commentary—I bet you can tell what's going on if you still had your precious eyes.",
  ui_story_5031_50310802_73_dialog_content = "The most outstanding surfer in the contest right now is our very own Rainbow of the Circus—as well as Ciel of Illumina.",
  ui_story_5031_50310802_74_dialog_content = "The two are about even for Eclipsites destroyed and far ahead when it comes to style.",
  ui_story_5031_50310802_75_dialog_content = "But given the response of our audience, Rainbow seems to have a slightly superior technique.",
  ui_story_5031_50310802_76_dialog_content = "So I wish the rest of you, eighteen contestants, thoroughly unremarkable as you are, the best of luck.",
  ui_story_5031_50310802_77_dialog_content = "... And a valiant struggle against the waves and vicissitudes of life.",
  ui_story_5031_50310802_78_dialog_content = "...",
  ui_story_5031_50310802_79_dialog_content = "Just you wait, Jeno!",
  ui_story_5031_50310802_80_dialog_content = "Down into the sea with you!",
  ui_story_5031_50310802_81_dialog_content = "Graaaah!",
  ui_story_5031_50310802_82_dialog_content = "Phew, even if you're an illusion, I can't help it!",
  ui_story_5031_50310802_83_dialog_content = "I feel much better after destroying you all!",
  ui_story_5031_50310802_84_dialog_content = "You're so... powerful...",
  ui_story_5031_50310802_85_dialog_content = "Huh? Right back at ya, girl!",
  ui_story_5031_50310802_86_dialog_content = "You're quite a good match for me who grew up by the sea!",
  ui_story_5031_50310802_87_dialog_content = "Actually, I just earned the marks by killing Eclipsites.",
  ui_story_5031_50310802_88_dialog_content = "I didn't score much in terms of my surfing skills.",
  ui_story_5031_50310802_89_dialog_content = "I just took advantage of a loophole in the rules...",
  ui_story_5031_50310802_90_dialog_content = "You're weird, Ciel.",
  ui_story_5031_50310802_91_dialog_content = "W-Weird?",
  ui_story_5031_50310802_92_dialog_content = "Yeah. I'm giving you praises, but you not only won't accept them, you also look upset.",
  ui_story_5031_50310802_93_dialog_content = "What's wrong with scoring by killing Eclipsites? How is that abusing the rules?",
  ui_story_5031_50310802_94_dialog_content = "...",
  ui_story_5031_50310802_95_dialog_content = "Ciel, you're good. You should have more confidence in yourself.",
  ui_story_5031_50310802_96_dialog_content = "Keeping on doubting yourself is one sure way to mess things up.",
  ui_story_5031_50310802_97_dialog_content = "I...",
  ui_story_5031_50310802_98_dialog_content = "Graagh!",
  ui_story_5031_50310802_99_dialog_content = "More Eclipsites!? You're not getting away!",
  ui_story_5031_50310802_100_dialog_content = "I'm... good?",
  ui_story_5031_50310802_101_dialog_content = "Heh... Heheh.",
  ui_story_5031_50310802_102_dialog_content = "Well, there's no way I'm gonna disappoint Rainbow, then!",
  ui_story_5031_50310802_103_dialog_content = "\"Arm mech status update—Type II\"!",
  ui_story_5031_50310802_104_dialog_content = "\"Increase power release by 60%\"!",
  ui_story_5031_50310802_105_dialog_content = "<color=#e8d9bb>Rumbles—</color>",
  ui_story_5031_50310802_106_dialog_content = "C-Ciel!?",
  ui_story_5031_50310802_107_dialog_content = "Did she increase energy output again?",
  ui_story_5031_50310802_108_dialog_content = "But Styx is...",
  ui_story_5031_50310802_109_dialog_content = "Hey! That mecha girl unleashed such powerful energy at sea!",
  ui_story_5031_50310802_110_dialog_content = "The ship is rocking back and forth! We are gonna sink...",
  ui_story_5031_50310802_111_dialog_content = "She flew up into the sky! She's trying to earn more points with a jumping flip?",
  ui_story_5031_50310802_112_dialog_content = "No, wait... That's...",
  ui_story_5031_50310802_113_dialog_content = "Eclipsites! She knocked the Eclipsites out from the sea!",
  ui_story_5031_50310802_114_dialog_content = "Ahh, that's...",
  ui_story_5031_50310802_115_dialog_content = "Such an incredible power!",
  ui_story_5031_50310802_116_dialog_content = "Since I'm not so highly skilled, I'll have to rely on the remaining 50% points.",
  ui_story_5031_50310802_117_dialog_content = "Styx, sweep attack!",
  ui_story_5031_50310802_118_dialog_content = "But the mecha has great output and can launch effective area attacks.",
  ui_story_5031_50310802_119_dialog_content = "Right, her mecha is heavier, so it cannot perform nimble acts.",
  ui_story_5031_50310802_120_dialog_content = "Ciel took advantage of this to instantly kill a large number of Eclipsites, turning the tables by earning a load of points!",
  ui_story_5031_50310802_121_dialog_content = "Trying to break out of a desperate situation despite her disadvantages. It's inspiring.",
  ui_story_5031_50310802_122_dialog_content = "Then, would the laird give her a score?",
  ui_story_5031_50310802_123_dialog_content = "Sure thing, ringmaster.",
  ui_story_5031_50310802_124_dialog_content = "I-Is that...",
  ui_story_5031_50310802_125_dialog_content = "<color=#e8d9bb>Click... Clack...</color>",
  ui_story_5031_50310802_126_dialog_content = "Huh?",
  ui_story_5031_50310802_127_dialog_content = "Oh, no! Styx cannot maintain such a high energy output...",
  ui_story_5031_50310802_128_dialog_content = "Ahhhhh! I-I'm falling!",
  ui_story_5031_50310802_129_dialog_content = "Ciel!",
  ui_story_5031_50310802_130_dialog_content = "Hah!",
  ui_story_5031_50310802_131_dialog_content = "Huh? Rainbow?",
  ui_story_5031_50310802_132_dialog_content = "Uhm...",
  ui_story_5031_50310802_133_dialog_content = "You can open your eyes now. I've got you.",
  ui_story_5031_50310802_134_dialog_content = "What?",
  ui_story_5031_50310802_135_dialog_content = "R-Rainbow?",
  ui_story_5031_50310802_136_dialog_content = "That was reckless. Switching to such a high energy output when your mecha wasn't calibrated for it.",
  ui_story_5031_50310802_137_dialog_content = "I-I'm sorry.",
  ui_story_5031_50310802_138_dialog_content = "Styx experienced an explosion, and the damage wasn't fully repaired.",
  ui_story_5031_50310802_139_dialog_content = "Sorry to burden you...",
  ui_story_5031_50310802_140_dialog_content = "Is that so? What a pity!",
  ui_story_5031_50310802_141_dialog_content = "I'm so looking forward to its capabilities once it's fully repaired!",
  ui_story_5031_50310802_142_dialog_content = "...",
  ui_story_5031_50310802_143_dialog_content = "Uhm... Rainbow?",
  ui_story_5031_50310802_144_dialog_content = "Hmm? What is it?",
  ui_story_5031_50310802_145_dialog_content = "Why did you save me? If I fall into the sea, I'll lose a lot of points.",
  ui_story_5031_50310802_146_dialog_content = "Huh? Well...",
  ui_story_5031_50310802_147_dialog_content = "It's probably because of that, compared to 5 million Nightium...",
  ui_story_5031_50310802_148_dialog_content = "I'm more interested in you.",
  ui_story_5031_50310901_1_dialog_content = "The first round is over! Now, would the contestants for the second round go to their assigned starting points?",
  ui_story_5031_50310901_2_dialog_content = "In the meantime, the final scores for the first round will be calculated.",
  ui_story_5031_50310901_3_dialog_content = "It's okay, Fia. We still have our chance.",
  ui_story_5031_50310901_4_dialog_content = "Yeah. Don't feel bad. We never expected you to get a high score.",
  ui_story_5031_50310901_5_dialog_content = "Aaaah!",
  ui_story_5031_50310901_6_dialog_content = "Stupid PlayerName!",
  ui_story_5031_50310901_7_dialog_content = "Huh? What did I do?",
  ui_story_5031_50310901_8_dialog_content = "I-I was trying to comfort you.",
  ui_story_5031_50310901_9_dialog_content = "Just stop it first, PlayerName.",
  ui_story_5031_50310901_10_dialog_content = "... I believe there is a misunderstanding.",
  ui_story_5031_50310901_11_dialog_content = "Prepare for the second round, everyone.",
  ui_story_5031_50310901_12_dialog_content = "I heard Rainbow said they'll send Merylt next.",
  ui_story_5031_50310901_13_dialog_content = "Hm? You okay, Fia?",
  ui_story_5031_50310901_14_dialog_content = "*Sob* Carleen! PlayerName, he...",
  ui_story_5031_50310901_15_dialog_content = "Wait a minute! I didn't do anything!",
  ui_story_5031_50310901_16_dialog_content = "Fia, forget about him. Let's just focus on the next round.",
  ui_story_5031_50310901_17_dialog_content = "You want the prize mon⁠—I mean the swimsuit... And we have a Cloudwhale to save, right?",
  ui_story_5031_50310901_18_dialog_content = "Boo-hoo, yes...",
  ui_story_5031_50310901_19_dialog_content = "Then dry your tears. Let's discuss our arrangement for the next round.",
  ui_story_5031_50310901_20_dialog_content = "Then... I propose that PlayerName goes next!",
  ui_story_5031_50310901_21_dialog_content = "Huh?!",
  ui_story_5031_50310901_22_dialog_content = "Hmph! You were laughing when I fell into the water, weren't you?",
  ui_story_5031_50310901_23_dialog_content = "Now it's my turn to laugh at you!",
  ui_story_5031_50310901_24_dialog_content = "How did you know I was laughing⁠—No, wait. That makes no sense!",
  ui_story_5031_50310901_25_dialog_content = "I thought winning the game was more important!",
  ui_story_5031_50310901_26_dialog_content = "We only need two winning scores, so I don't even need to go on, right?",
  ui_story_5031_50310901_27_dialog_content = "Did you forget, PlayerName? You and Fia are counted as one.",
  ui_story_5031_50310901_28_dialog_content = "You and Fia's score is summed up.",
  ui_story_5031_50310901_29_dialog_content = "Right... That happened...",
  ui_story_5031_50310901_30_dialog_content = "We don't know who Vice and I will face when it's our turn.",
  ui_story_5031_50310901_31_dialog_content = "So, just to be safe, it's best that you participate.",
  ui_story_5031_50310901_32_dialog_content = "Then it actually makes sense to send PlayerName up next.",
  ui_story_5031_50310901_33_dialog_content = "True. Merylt should be the mildest of the triplets.",
  ui_story_5031_50310901_34_dialog_content = "And I don't feel Officer Gronru is any good at surfing",
  ui_story_5031_50310901_35_dialog_content = "So, if that's the case...",
  ui_story_5031_50310901_36_dialog_content = "If that's the case...",
  ui_story_5031_50310901_37_dialog_content = "I know, I know... I'll go. Just stop glaring at me.",
  ui_story_5031_50310901_38_dialog_content = "Heheh! Good luck, PlayerName.",
  ui_story_5031_50310901_39_dialog_content = "No pressure, alright? Just remember what we've taught you.",
  ui_story_5031_50310901_40_dialog_content = "It's fine even if you couldn't do it.",
  ui_story_5031_50310901_41_dialog_content = "I got it, I got it.",
  ui_story_5031_50310901_42_dialog_content = "Hmph! You better not be the weakest link, PlayerName!",
  ui_story_5031_50310901_43_dialog_content = "You didn't earn a good score yourself!",
  ui_story_5031_50310901_44_dialog_content = "While we announce the score, will all contestants get to your positions?",
  ui_story_5031_50310901_45_dialog_content = "The winner of the last round is... Rainbow!",
  ui_story_5031_50310901_46_dialog_content = "That's no surprise. She's our ace.",
  ui_story_5031_50310901_47_dialog_content = "Rainbow—!",
  ui_story_5031_50310901_48_dialog_content = "However, there's something that will knock your socks off!",
  ui_story_5031_50310901_49_dialog_content = "We have another contestant with the same score sharing the same rank, and that is... Ciel!",
  ui_story_5031_50310901_50_dialog_content = "That's the mecha girl!",
  ui_story_5031_50310901_51_dialog_content = "Incredible! She caught up to Rainbow's score!?",
  ui_story_5031_50310901_52_dialog_content = "That's amazing, Ciel!",
  ui_story_5031_50310901_53_dialog_content = "Thank you, Officer Gronru!",
  ui_story_5031_50310901_54_dialog_content = "Officer Gronru? Why are you here!?",
  ui_story_5031_50310901_55_dialog_content = "You should be in your position!",
  ui_story_5031_50310901_56_dialog_content = "Well, that's because...",
  ui_story_5031_50310901_57_dialog_content = "I know you want to pit Merylt, PlayerName, and I against each other...",
  ui_story_5031_50310901_58_dialog_content = "Hoping to take advantage of the situation, don't you?",
  ui_story_5031_50310901_59_dialog_content = "...",
  ui_story_5031_50310901_60_dialog_content = "Uhm, well...",
  ui_story_5031_50310901_61_dialog_content = "Well, guess what? I'm not gonna make things so easy for you!",
  ui_story_5031_50310901_62_dialog_content = "Hmm... Don't be nervous.",
  ui_story_5031_50310901_63_dialog_content = "There are fewer people this round. All I need to do is to hold my own.",
  ui_story_5031_50310901_64_dialog_content = "PlayerName, Uh...",
  ui_story_5031_50310901_65_dialog_content = "What happened, Merylt?",
  ui_story_5031_50310901_66_dialog_content = "Uhm, your board... It's not tethered to you.",
  ui_story_5031_50310901_67_dialog_content = "It's very dangerous...",
  ui_story_5031_50310901_68_dialog_content = "Oh! I totally forgot about it!",
  ui_story_5031_50310901_69_dialog_content = "Thanks so much, Merylt!",
  ui_story_5031_50310901_70_dialog_content = "Uhm...!",
  ui_story_5031_50310901_71_dialog_content = "Oh, she just dove into the water!",
  ui_story_5031_50310901_72_dialog_content = "Did I say something wrong again?",
  ui_story_5031_50310901_73_dialog_content = "Well, it's time.",
  ui_story_5031_50310901_74_dialog_content = "Let's kick off the second round.",
  ui_story_5031_50310901_75_dialog_content = "Hahahaha... Just like that, again?",
  ui_story_5031_50310901_76_dialog_content = "Is that the circus ringmaster's style?",
  ui_story_5031_50310901_77_dialog_content = "Oh, there is no mecha in this round. How disappointing.",
  ui_story_5031_50310901_78_dialog_content = "Huh? Look! That's the girl of the circus triplets...",
  ui_story_5031_50310901_79_dialog_content = "Her movements are even more graceful than Rainbow's!",
  ui_story_5031_50310901_80_dialog_content = "Of course! Merylt's one of the circus members with the best balance and control!",
  ui_story_5031_50310901_81_dialog_content = "She has mastered high-flying trapeze and gym rings. Surfing should be a piece of cake for her!",
  ui_story_5031_50310901_82_dialog_content = "You really know everything there's to know about the circus members.",
  ui_story_5031_50310901_83_dialog_content = "Well, they are not just my employees.",
  ui_story_5031_50310901_84_dialog_content = "They are my family.",
  ui_story_5031_50310901_85_dialog_content = "...",
  ui_story_5031_50310901_86_dialog_content = "That actually reminds me of the old you.",
  ui_story_5031_50310901_87_dialog_content = "Is that so? The useless brat who always depended on his family and you?",
  ui_story_5031_50310901_88_dialog_content = "No. That innocent little boy who'd cry for a birdie that fell out of its nest.",
  ui_story_5031_50310901_89_dialog_content = "You even broke your arm when trying to put it back and wore a cast for six months.",
  ui_story_5031_50310901_90_dialog_content = "And you're still trying to take care of everyone around you.",
  ui_story_5031_50310901_91_dialog_content = "Oh, enough with all those embarrassing things about me.",
  ui_story_5031_50310901_92_dialog_content = "Just enjoy the game.",
  ui_story_5031_50310901_93_dialog_content = "Ha... All right, all right.",
  ui_story_5031_50310902_1_dialog_content = "As expected, the highest scoring contestant is still a member of our circus...",
  ui_story_5031_50310902_2_dialog_content = "Merylt!",
  ui_story_5031_50310902_3_dialog_content = "Ohhhhhh!",
  ui_story_5031_50310902_4_dialog_content = "This brilliant result is the fruition of her endless hard work and sweat under the stars.",
  ui_story_5031_50310902_5_dialog_content = "I hope her success will inspire and stir up something in all you lazybones!",
  ui_story_5031_50310902_X5_dialog_content = "...",
  ui_story_5031_50310902_X6_dialog_content = "Hmph, so ashamed you're at a loss for words? Fine, not everyone wants to do something with their life.",
  ui_story_5031_50310902_X7_dialog_content = "Contestants for the third round, get ready!",
  ui_story_5031_50310902_X8_dialog_content = "Third-round contestants, please get ready.",
  ui_story_5031_50310902_6_dialog_content = "Contestants for the third round, get ready!",
  ui_story_5031_50310902_7_dialog_content = "Huh? PlayerName, you earn zero points? No way.",
  ui_story_5031_50310902_8_dialog_content = "In a manner of speaking, that is beyond what a normal person can do.",
  ui_story_5031_50310902_9_dialog_content = "Without Carleen and Vice, we really don't know what to do about the Cloudwhale.",
  ui_story_5031_50310902_10_dialog_content = "*Sob* That's enough...",
  ui_story_5031_50310902_11_dialog_content = "As a Caelestite, I'm sorry.",
  ui_story_5031_50310902_12_dialog_content = "Oh, stop blaming PlayerName, Fia.",
  ui_story_5031_50310902_13_dialog_content = "It's unrealistic to think a newbie could learn how to surf in one day.",
  ui_story_5031_50310902_14_dialog_content = "We'll catch up. Don't worry.",
  ui_story_5031_50310902_15_dialog_content = "You're really reliable, Carleen, Vice!",
  ui_story_5031_50310902_16_dialog_content = "Sigh, try harder and do your best, PlayerName.",
  ui_story_5031_50310902_17_dialog_content = "Don't be upset. I'll stop teasing you. When I master how to surf, Carleen and I will do our best to teach you!",
  ui_story_5031_50310902_18_dialog_content = "Hah. I suppose I should be grateful.",
  ui_story_5031_50310902_19_dialog_content = "You better be!",
  ui_story_5031_50310902_20_dialog_content = "U-Um, PlayerName...",
  ui_story_5031_50310902_21_dialog_content = "Huh? Merylt? What can I do for you?",
  ui_story_5031_50310902_22_dialog_content = "Uhm...",
  ui_story_5031_50310902_23_dialog_content = "Oh, just let me say it!",
  ui_story_5031_50310902_24_dialog_content = "PlayerName, Merylt wants to apologize for almost hurting you!",
  ui_story_5031_50310902_25_dialog_content = "Oh, that! Don't worry, Merylt. You didn't hurt me.",
  ui_story_5031_50310902_26_dialog_content = "I just breathed in some water because I got frightened myself.",
  ui_story_5031_50310902_27_dialog_content = "Emm... Hm...",
  ui_story_5031_50310902_28_dialog_content = "You are so gentle, PlayerName! Unlike the boss!",
  ui_story_5031_50310902_29_dialog_content = "Such gentleness, no wonder Merylt fell for ya—Uhmm!?",
  ui_story_5031_50310902_30_dialog_content = "F-Frimet!",
  ui_story_5031_50310902_31_dialog_content = "You should go get ready, n-now!",
  ui_story_5031_50310902_32_dialog_content = "Mm! Mmm!",
  ui_story_5031_50310902_33_dialog_content = "Ah, wait for me!",
  ui_story_5031_50310902_34_dialog_content = "Oh?",
  ui_story_5031_50310902_35_dialog_content = "You are quite popular, PlayerName.",
  ui_story_5031_50310902_36_dialog_content = "...",
  ui_story_5031_50310902_37_dialog_content = "Huh? What are you talking about?",
  ui_story_5031_50310902_38_dialog_content = "Nothing!",
  ui_story_5031_50310902_39_dialog_content = "I better go get ready. It's gonna start any moment now.",
  ui_story_5031_50310902_40_dialog_content = "Yeah, let's go.",
  ui_story_5031_50310902_41_dialog_content = "Acting all mysterious...",
  ui_story_5031_50310902_42_dialog_content = "Let's head up the beach then, Fia—",
  ui_story_5031_50310902_43_dialog_content = "Huh? Fia?",
  ui_story_5031_50310902_44_dialog_content = "Really? What's happening to all of them?",
  ui_story_5031_50310902_45_dialog_content = "Now that we're in the third round, everyone should know the rules already. Let's get started, then.",
  ui_story_5031_50310902_46_dialog_content = "Rapid Torrent!",
  ui_story_5031_50310902_47_dialog_content = "That's a powerful offense.",
  ui_story_5031_50310902_48_dialog_content = "Looks like I'd need to take it seriously now. Time to show off my special training!",
  ui_story_5031_50310902_49_dialog_content = "*Coughs*",
  ui_story_5031_50310902_50_dialog_content = "Elvis! Where's your medicine?",
  ui_story_5031_50310902_51_dialog_content = "Inside... my coat's inner pock.",
  ui_story_5031_50310902_52_dialog_content = "Don't forget to turn off the speaker... cough...",
  ui_story_5031_50310902_53_dialog_content = "Don't worry. I turned it off.",
  ui_story_5031_50310902_54_dialog_content = "You sure it's in your pocket? I can't find it.",
  ui_story_5031_50310902_55_dialog_content = "Cough, cough... Ugh...",
  ui_story_5031_50310902_56_dialog_content = "I'm sorry... Do you have a handkerchief?",
  ui_story_5031_50310902_57_dialog_content = "Sure. One second.",
  ui_story_5031_50310902_58_dialog_content = "<color=#e8d9bb>Clatter—</color>",
  ui_story_5031_50310902_59_dialog_content = "Tsk, too many things.",
  ui_story_5031_50310902_60_dialog_content = "Can you just be good at a time like this?",
  ui_story_5031_50310902_61_dialog_content = "...",
  ui_story_5031_50310902_62_dialog_content = "Here.",
  ui_story_5031_50310902_63_dialog_content = "Thanks... Cough, cough...",
  ui_story_5031_50310902_64_dialog_content = "This is an exciting round! Quite a brawl!",
  ui_story_5031_50310902_65_dialog_content = "Yes! Another Eclipsite down!",
  ui_story_5031_50310902_66_dialog_content = "That girl with a bow is amazing!",
  ui_story_5031_50310902_67_dialog_content = "...",
  ui_story_5031_50310902_68_dialog_content = "Sorry, can you take me somewhere with fewer people so I can rest a bit?",
  ui_story_5031_50310902_69_dialog_content = "Of course.",
  ui_story_5031_50310902_70_dialog_content = "Hey, you, over there!",
  ui_story_5031_50310902_71_dialog_content = "Yes, you.",
  ui_story_5031_50310902_72_dialog_content = "Yes, boss?",
  ui_story_5031_50310902_73_dialog_content = "Keep the score and take over for me for a bit. We have a business to discuss.",
  ui_story_5031_50310902_74_dialog_content = "On it!",
  ui_story_5031_50310902_75_dialog_content = "Don't look at me like that. I'm fine now.",
  ui_story_5031_50310902_76_dialog_content = "Fine? Coughing up blood all over me is not FINE.",
  ui_story_5031_50310902_77_dialog_content = "Sorry about your clothes.",
  ui_story_5031_50310902_78_dialog_content = "You know that's not what I meant.",
  ui_story_5031_50310902_79_dialog_content = "Don't worry. It only means that I have more blood than I need... It's a good sign, isn't it?",
  ui_story_5031_50310902_80_dialog_content = "Stop the nonsense.",
  ui_story_5031_50310902_81_dialog_content = "You really can't tell me what your plan is?",
  ui_story_5031_50310902_82_dialog_content = "I'll make sure I get it done for you if you'll trust me.",
  ui_story_5031_50310902_83_dialog_content = "...",
  ui_story_5031_50310902_84_dialog_content = "What's that look on your face?",
  ui_story_5031_50310902_85_dialog_content = "Oh, it's just that you reminded me of our past again.",
  ui_story_5031_50310902_86_dialog_content = "Another embarrassing thing that I had done?",
  ui_story_5031_50310902_87_dialog_content = "Well, you were always smaller and skinnier than me, but still, you tried your best to help others, help me.",
  ui_story_5031_50310902_88_dialog_content = "And that's exactly the look in your eyes right now.",
  ui_story_5031_50310902_89_dialog_content = "Time may have made its mark on us, but it doesn't change who we are.",
  ui_story_5031_50310902_90_dialog_content = "Yeah... Some things change, but some stay the same.",
  ui_story_5031_50310902_91_dialog_content = "Just like how you're still shorter than me.",
  ui_story_5031_50310902_92_dialog_content = "Tsk. But now, I can take ten of you.",
  ui_story_5031_50310902_93_dialog_content = "Yeah... You're no longer the Jeno that needed my protection.",
  ui_story_5031_50310902_94_dialog_content = "Not that I'm in any shape to protect you now.",
  ui_story_5031_50310902_95_dialog_content = "Then it's my turn.",
  ui_story_5031_50310902_96_dialog_content = "Ha... It's not that easy, and you can't just talk it through.",
  ui_story_5031_50310902_97_dialog_content = "I'm serious, Elvis.",
  ui_story_5031_50310902_98_dialog_content = "Tell me what your plan is, and I'll find a way to make it happen.",
  ui_story_5031_50310902_99_dialog_content = "What if it involves the organization behind you?",
  ui_story_5031_50310902_100_dialog_content = "...?",
  ui_story_5031_50310902_101_dialog_content = "What if, just what if. It requires your ship and something from its depth?",
  ui_story_5031_50310902_102_dialog_content = "Will you still help?",
  ui_story_5031_50310902_103_dialog_content = "How did you know...?",
  ui_story_5031_50310902_104_dialog_content = "That's not important, Jeno.",
  ui_story_5031_50310902_105_dialog_content = "What's important is, that we're not children anymore, and we cannot go back to that simple time anymore.",
  ui_story_5031_50310902_106_dialog_content = "Our every decision, promise, every word carries so much more weight and burden.",
  ui_story_5031_50310902_107_dialog_content = "So, let me ask you again. If that's the case, will you still help me?",
  ui_story_5031_50310902_108_dialog_content = "...",
  ui_story_5031_50310902_109_dialog_content = "I... I once made a promise.",
  ui_story_5031_50310902_110_dialog_content = "I promised to protect the ship and protect that thing.",
  ui_story_5031_50310902_111_dialog_content = "I see... Sorry to have put you in this position.",
  ui_story_5031_50310902_112_dialog_content = "It's best for us to get back to the game. Looks like the job is more than what your temporary substitute can handle.",
  ui_story_5031_50310902_113_dialog_content = "Elvis, I...",
  ui_story_5031_50310902_114_dialog_content = "Jeno.",
  ui_story_5031_50310902_115_dialog_content = "...",
  ui_story_5031_50310902_116_dialog_content = "It's fine. I understand.",
  ui_story_5031_50310902_117_dialog_content = "No matter what, I just want you to know...",
  ui_story_5031_50310902_118_dialog_content = "I've missed you for the last dozen years.",
  ui_story_5031_50310902_119_dialog_content = "...!",
  ui_story_5031_50311001_1_dialog_content = "Your Highness.",
  ui_story_5031_50311001_2_dialog_content = "Matthieu? What is it?",
  ui_story_5031_50311001_3_dialog_content = "Are you going to keep up with this farce?",
  ui_story_5031_50311001_4_dialog_content = "Being in the same water with the commoners... It's disgusting.",
  ui_story_5031_50311001_5_dialog_content = "Yes, I am.",
  ui_story_5031_50311001_6_dialog_content = "If you find it unbearable, you might as well just stay on the beach or ship. Better yet, you should just head back to Lumopolis.",
  ui_story_5031_50311001_7_dialog_content = "Tsk, such an enraging attitude...",
  ui_story_5031_50311001_8_dialog_content = "Matthieu.",
  ui_story_5031_50311001_9_dialog_content = "Hmph... What a chore. Why should I protect such a diva of a princess?",
  ui_story_5031_50311001_10_dialog_content = "...",
  ui_story_5031_50311001_11_dialog_content = "Matthieu, I'm no diva, and this princess doesn't need your protection.",
  ui_story_5031_50311001_12_dialog_content = "And if you're just annoyed by the fact that you can't swim, don't worry, I will be fine.",
  ui_story_5031_50311001_13_dialog_content = "Pfft...",
  ui_story_5031_50311001_14_dialog_content = "What... what are you talking about?!",
  ui_story_5031_50311001_15_dialog_content = "I can't swim!? There's no way that I can't do something a lowly commoner can!",
  ui_story_5031_50311001_16_dialog_content = "A-And, Loewe, I heard you laughing at me! How dare you!",
  ui_story_5031_50311001_17_dialog_content = "Well, you really can't swim.",
  ui_story_5031_50311001_18_dialog_content = "Ahhhh! You...!",
  ui_story_5031_50311001_19_dialog_content = "I had enough! You ill-tempered princess, mark my words, you'll regret mixing with the commoners!",
  ui_story_5031_50311001_20_dialog_content = "I'm going to go change!",
  ui_story_5031_50311001_21_dialog_content = "...",
  ui_story_5031_50311001_22_dialog_content = "Why are they even here...?",
  ui_story_5031_50311001_23_dialog_content = "He probably wanted to stop me from entering the game because he couldn't swim himself.",
  ui_story_5031_50311001_24_dialog_content = "I really don't get why Irridon even sent him.",
  ui_story_5031_50311001_25_dialog_content = "Vice! You're back!",
  ui_story_5031_50311001_26_dialog_content = "Welcome back, Vice.",
  ui_story_5031_50311001_27_dialog_content = "You were so amazing, Vice! You'll definitely get a high score!",
  ui_story_5031_50311001_28_dialog_content = "The Cloudwhale is as good as ours! And I don't have to listen to my master talk my ears off!",
  ui_story_5031_50311001_29_dialog_content = "You give me too much credit, Fia.",
  ui_story_5031_50311001_30_dialog_content = "The other contestants were worthy opponents.",
  ui_story_5031_50311001_31_dialog_content = "I didn't think Officer Gronru would be so good at surfing... I underestimated her.",
  ui_story_5031_50311001_32_dialog_content = "It's okay. We still have one more round, but their score is fixed now.",
  ui_story_5031_50311001_33_dialog_content = "Now, it's Carleen's turn!",
  ui_story_5031_50311001_34_dialog_content = "Matthieu and Loewe were here? Are they also here to participate in the game?",
  ui_story_5031_50311001_35_dialog_content = "Don't mind them.",
  ui_story_5031_50311001_36_dialog_content = "Come to think of it, we haven't heard the voice of our host for a long time.",
  ui_story_5031_50311001_37_dialog_content = "You're right. I wonder what he and Elvis are doing.",
  ui_story_5031_50311001_38_dialog_content = "Anyway, you better get ready, Carleen.",
  ui_story_5031_50311001_39_dialog_content = "Good luck, Carleen!",
  ui_story_5031_50311001_40_dialog_content = "Go, Carleen!",
  ui_story_5031_50311001_41_dialog_content = "Leave it to me.",
  ui_story_5031_50311001_42_dialog_content = "...",
  ui_story_5031_50311001_43_dialog_content = "Jeno, sir?",
  ui_story_5031_50311001_44_dialog_content = "What?",
  ui_story_5031_50311001_45_dialog_content = "<size=33>Ahh! What's with the boss' sudden change in attitude...?</size>",
  ui_story_5031_50311001_46_dialog_content = "Uhm... The scores for the last round are here. Aren't you gonna announce it?",
  ui_story_5031_50311001_47_dialog_content = "...",
  ui_story_5031_50311001_48_dialog_content = "Uhm... Or, at least say the word to begin the next round...",
  ui_story_5031_50311001_49_dialog_content = "The contestants are all ready and waiting...",
  ui_story_5031_50311001_50_dialog_content = "Begin.",
  ui_story_5031_50311001_51_dialog_content = "...",
  ui_story_5031_50311001_52_dialog_content = "Fine... I'm getting used to him.",
  ui_story_5031_50311001_53_dialog_content = "Ice Blossom!",
  ui_story_5031_50311001_54_dialog_content = "Oh! Quick reaction!",
  ui_story_5031_50311001_55_dialog_content = "She used Lumina to freeze the waves!",
  ui_story_5031_50311001_56_dialog_content = "And speeded away while executing the move to perfection!",
  ui_story_5031_50311001_57_dialog_content = "This is incredible! I'm so excited!",
  ui_story_5031_50311001_58_dialog_content = "Go!",
  ui_story_5031_50311001_59_dialog_content = "Graagh!!",
  ui_story_5031_50311001_60_dialog_content = "Huh? Freezing so many Eclipsites at the same time!?",
  ui_story_5031_50311001_61_dialog_content = "Wow!",
  ui_story_5031_50311001_62_dialog_content = "That girl also saved Ranka, didn't she?",
  ui_story_5031_50311001_63_dialog_content = "She's amazing. She's not only elegant, she's also deadly against all those Eclipsites!",
  ui_story_5031_50311001_64_dialog_content = "Not just that, she even froze the surface of the sea, making it her path! Such precision!",
  ui_story_5031_50311001_65_dialog_content = "Wait, is her name Carleen?",
  ui_story_5031_50311001_66_dialog_content = "Now I remember! She's the princess, isn't she?",
  ui_story_5031_50311001_67_dialog_content = "Incredible, just incredible!",
  ui_story_5031_50311001_68_dialog_content = "She's really got my heart pumping hard! I gotta keep up!",
  ui_story_5031_50311001_69_dialog_content = "Phew...",
  ui_story_5031_50311001_70_dialog_content = "That's 62.",
  ui_story_5031_50311001_71_dialog_content = "Gronru hit 70 and Ciel nailed... 93.",
  ui_story_5031_50311001_72_dialog_content = "Tsk. Having a mecha sure is advantageous at this.",
  ui_story_5031_50311001_73_dialog_content = "If Vice got 69... Hmm...",
  ui_story_5031_50311001_74_dialog_content = "I need to take down at least 32 more, and score more from moves as well.",
  ui_story_5031_50311001_75_dialog_content = "As for the circus...",
  ui_story_5031_50311001_76_dialog_content = "Hi, Princess Carleen. Are you taking a break here?",
  ui_story_5031_50311001_77_dialog_content = "Subli?",
  ui_story_5031_50311001_78_dialog_content = "You remember my name! I'm so happy!",
  ui_story_5031_50311001_79_dialog_content = "Just call me Carleen.",
  ui_story_5031_50311001_80_dialog_content = "Alright, Carleen.",
  ui_story_5031_50311001_81_dialog_content = "I like you a lot, but I have unfortunate news for you.",
  ui_story_5031_50311001_82_dialog_content = "What is it?",
  ui_story_5031_50311001_83_dialog_content = "Our strategy is to send Rainbow and Merylt first to score as many points as they can.",
  ui_story_5031_50311001_84_dialog_content = "As for Frimet and me...",
  ui_story_5031_50311001_85_dialog_content = "We're here to interfere with the other contestants!",
  ui_story_5031_50311001_86_dialog_content = "Ugh!",
  ui_story_5031_50311001_87_dialog_content = "No wonder Frimet kept on messing with Vice!",
  ui_story_5031_50311001_88_dialog_content = "Yeah... So don't hate me, please. It's nothing personal.",
  ui_story_5031_50311001_89_dialog_content = "Tsk! How dare a mere commoner attack Princess Carleen!",
  ui_story_5031_50311001_90_dialog_content = "Loewe, I want her taken down, right now!",
  ui_story_5031_50311001_91_dialog_content = "...",
  ui_story_5031_50311001_92_dialog_content = "How nimble... She sure did grow up in the circus.",
  ui_story_5031_50311001_93_dialog_content = "I'm at a disadvantage here on such a narrow board...",
  ui_story_5031_50311001_94_dialog_content = "Oh! Carleen, you're amazing!",
  ui_story_5031_50311001_95_dialog_content = "You can keep balance while defending my attacks!",
  ui_story_5031_50311001_96_dialog_content = "You're so graceful, I really admire you!",
  ui_story_5031_50311001_97_dialog_content = "Uhm... I can't actually hurt her.",
  ui_story_5031_50311001_98_dialog_content = "I just have to try to put some distance between us.",
  ui_story_5031_50311001_99_dialog_content = "Huh? Where are you going, Carleen?",
  ui_story_5031_50311001_100_dialog_content = "Won't you play with me some more? I haven't had enough fun yet!",
  ui_story_5031_50311001_101_dialog_content = "Now's the time!",
  ui_story_5031_50311001_102_dialog_content = "Ice Blossom!",
  ui_story_5031_50311001_103_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5031_50311001_104_dialog_content = "Ah!",
  ui_story_5031_50311001_105_dialog_content = "I'm sorry. You're better off staying here.",
  ui_story_5031_50311001_106_dialog_content = "Ouch... Huh?",
  ui_story_5031_50311001_107_dialog_content = "I-I thought I was a goner!",
  ui_story_5031_50311001_108_dialog_content = "So she just froze me in place here!",
  ui_story_5031_50311001_109_dialog_content = "I can't move, but I'm not hurt in any way, and my head is not in the ice...",
  ui_story_5031_50311001_110_dialog_content = "Oh, such control and precision! Now I like Carleen even more!",
  ui_story_5031_50311001_111_dialog_content = "That kid... She's so weird.",
  ui_story_5031_50311001_112_dialog_content = "At least she's no longer a threat. All I need to do now is focus on earning points.",
  ui_story_5031_50311001_113_dialog_content = "I wasted too much time back then. I have to make it up for everyone's sake.",
  ui_story_5031_50311002_1_dialog_content = "Assemble, everyone!",
  ui_story_5031_50311002_2_dialog_content = "How did you like the surfing contest?",
  ui_story_5031_50311002_3_dialog_content = "We love it!",
  ui_story_5031_50311002_4_dialog_content = "Heheh, I had a great time as well!",
  ui_story_5031_50311002_5_dialog_content = "You have all had a memorable time here. It's forever for you to keep!",
  ui_story_5031_50311002_6_dialog_content = "Now, it's time to announce the score!",
  ui_story_5031_50311002_7_dialog_content = "Gulp—",
  ui_story_5031_50311002_8_dialog_content = "Fia, your swallowing sound was loud.",
  ui_story_5031_50311002_9_dialog_content = "I-I'm not anxious at all!",
  ui_story_5031_50311002_10_dialog_content = "Don't worry. Carleen did a great job. We'll be fine.",
  ui_story_5031_50311002_11_dialog_content = "I only caught up to Gronru's score in killing the Eclipsites...",
  ui_story_5031_50311002_12_dialog_content = "As for the score on my moves... We'll have to see.",
  ui_story_5031_50311002_13_dialog_content = "Rainbow and her team... may still be ahead of us.",
  ui_story_5031_50311002_14_dialog_content = "Alright! I'm not gonna keep you waiting!",
  ui_story_5031_50311002_15_dialog_content = "The winner of the surfing contest is...",
  ui_story_5031_50311002_16_dialog_content = "Yours truly! The Emerald!",
  ui_story_5031_50311002_17_dialog_content = "The detailed calculations and scoring will be posted on the bulletin board. Please check it if you're in doubt!",
  ui_story_5031_50311002_18_dialog_content = "I promise it's the legit score from all the audience here! No favors!",
  ui_story_5031_50311002_19_dialog_content = "Wow!",
  ui_story_5031_50311002_20_dialog_content = "Rainbow, you deserve it!",
  ui_story_5031_50311002_21_dialog_content = "Thank you for your support of Emerald!",
  ui_story_5031_50311002_22_dialog_content = "And we thank the laird for the 5 million Nightium!",
  ui_story_5031_50311002_23_dialog_content = "Hahahahah!",
  ui_story_5031_50311002_24_dialog_content = "So sad!",
  ui_story_5031_50311002_25_dialog_content = "Nightium... 5 million Nightium...",
  ui_story_5031_50311002_26_dialog_content = "Boo-hoo, my swimsuit...!",
  ui_story_5031_50311002_27_dialog_content = "It's okay. The Emerald is not a carnival team, so we still have a chance at the Cloudwhale.",
  ui_story_5031_50311002_28_dialog_content = "As for the swimsuit... We can still afford it without the prize money.",
  ui_story_5031_50311002_29_dialog_content = "Really? You really gonna buy me a swimsuit, PlayerName?",
  ui_story_5031_50311002_30_dialog_content = "Sure, if you stop angering people and gossiping and just be a good girl.",
  ui_story_5031_50311002_31_dialog_content = "What!? I'm a lady! Where did that impression of yours come from?",
  ui_story_5031_50311002_32_dialog_content = "So you mean you can't do it? Oh, never mind then.",
  ui_story_5031_50311002_33_dialog_content = "Ahhh! But you promised! You can't turn back on a promise!",
  ui_story_5031_50311002_34_dialog_content = "...",
  ui_story_5031_50311002_35_dialog_content = "Next, our runner-up team!",
  ui_story_5031_50311002_36_dialog_content = "Hush! They are announcing the runner-up now!",
  ui_story_5031_50311002_37_dialog_content = "The runner-up is...",
  ui_story_5031_50311002_38_dialog_content = "Gronru and Ciel, from Illumina!",
  ui_story_5031_50311002_39_dialog_content = "Wow!",
  ui_story_5031_50311002_40_dialog_content = "What?!",
  ui_story_5031_50311002_41_dialog_content = "<size=45>What?!</size>",
  ui_story_5031_50311002_42_dialog_content = "<size=55>Huh?</size>",
  ui_story_5031_50311002_43_dialog_content = "It's... Gronru and Ciel?",
  ui_story_5031_50311002_44_dialog_content = "Th-Then... Doesn't that mean...",
  ui_story_5031_50311002_45_dialog_content = "We wouldn't be the ones taking the prize home...?",
  ui_story_5031_50311002_46_dialog_content = "T-The Cloudwhale's gonna be someone else's!?",
  ui_story_5031_50311002_47_dialog_content = "Ahhhh! Master's gonna scold me to death!",
  ui_story_5031_50311002_48_dialog_content = "...",
  ui_story_5031_50311002_49_dialog_content = "Carleen? Where are you going?",
  ui_story_5031_50311002_50_dialog_content = "Carleen!",
  ui_story_5031_50311002_51_dialog_content = "Wait up, Carleen. Where are you going?",
  ui_story_5031_50311002_52_dialog_content = "Car⁠—",
  ui_story_5031_50311002_53_dialog_content = "Sorry, PlayerName and Vice, but I'd like to be alone for a while.",
  ui_story_5031_50311002_54_dialog_content = "W-We can go.",
  ui_story_5031_50311002_55_dialog_content = "But we're worried about you. Could you at least...",
  ui_story_5031_50311002_56_dialog_content = "At least tell us... What happened?",
  ui_story_5031_50311002_56X1_dialog_content = "Yeah. Did we do anything wrong?",
  ui_story_5031_50311002_56X2_dialog_content = "No, no... It has nothing to do with you.",
  ui_story_5031_50311002_57_dialog_content = "I just... feel like I'm a loser.",
  ui_story_5031_50311002_58_dialog_content = "I did everything, but I still didn't manage to win it for my friends... and I couldn't get her what she wanted.",
  ui_story_5031_50311002_59_dialog_content = "But it's not your fault.",
  ui_story_5031_50311002_60_dialog_content = "Truth to be told, I should be the one responsible...",
  ui_story_5031_50311002_61_dialog_content = "Everyone did their best, but I messed it all up because I didn't learn to surf.",
  ui_story_5031_50311002_62_dialog_content = "That's different...",
  ui_story_5031_50311002_63_dialog_content = "How is it different? It feels the same.",
  ui_story_5031_50311002_64_dialog_content = "Thank you for saying that, but it's my fault, not yours, and that's a fact.",
  ui_story_5031_50311002_65_dialog_content = "This is a team sport. No one should take all the blame.",
  ui_story_5031_50311002_66_dialog_content = "I'm the one who needs to apologize and thank you.",
  ui_story_5031_50311002_67_dialog_content = "Without you, we wouldn't be able to make it this far.",
  ui_story_5031_50311002_68_dialog_content = "...",
  ui_story_5031_50311002_69_dialog_content = "Likewise, do you think we can make it this far without Vice?",
  ui_story_5031_50311002_70_dialog_content = "No...",
  ui_story_5031_50311002_71_dialog_content = "See, so you do get it. It's how we feel about you.",
  ui_story_5031_50311002_72_dialog_content = "As for the prize, the whale, or whatever, we just have to figure another way.",
  ui_story_5031_50311002_73_dialog_content = "It's not like it's the end of the world if we don't win.",
  ui_story_5031_50311002_74_dialog_content = "Yeah, Carleen. At the very least, we can see Jeno, Officer Gronru, or Rainbow.",
  ui_story_5031_50311002_75_dialog_content = "We can tell them about Cloudwhale. I'm sure they'll be willing to help.",
  ui_story_5031_50311002_75X1_dialog_content = "Vice is right. None of this is a problem that couldn't be solved.",
  ui_story_5031_50311002_76_dialog_content = "So, stop being so upset, Carleen.",
  ui_story_5031_50311002_77_dialog_content = "Let's figure out something together.",
  ui_story_5031_50311002_78_dialog_content = "...",
  ui_story_5031_50311002_79_dialog_content = "Okay.",
  ui_story_5031_50311002_80_dialog_content = "You're right. Thank you.",
  ui_story_5031_50311002_81_dialog_content = "I should learn from you. Maybe this is what my father wanted...",
  ui_story_5031_50311002_82_dialog_content = "Lord Schwartz? What do you mean?",
  ui_story_5031_50311002_83_dialog_content = "Actually, before this trip, we had a... conversation.",
  ui_story_5031_50311002_83X1_dialog_content = "Conversation?",
  ui_story_5031_50311002_83X2_dialog_content = "Yes. Father would like me to contemplate the purpose of traveling with you.",
  ui_story_5031_50311002_83X3_dialog_content = "I think I got what he meant. There are many things I can learn from you.",
  ui_story_5031_50311002_83X4_dialog_content = "No wonder you've been lost in your own world the whole day, Carleen.",
  ui_story_5031_50311002_83X5_dialog_content = "But even after wracking my brain, a lot of things are still beyond me.",
  ui_story_5031_50311002_83X6_dialog_content = "Such as the breakthrough you talked about, Vice. I actually gave it a try today.",
  ui_story_5031_50311002_83X7_dialog_content = "Eh? You tried?",
  ui_story_5031_50311002_83X8_dialog_content = "Yes, and I followed what you suggested, the consciousness release.",
  ui_story_5031_50311002_83X9_dialog_content = "But I kept remembering the conversation with my father... and thus couldn't concentrate.",
  ui_story_5031_50311002_83X10_dialog_content = "So I failed.",
  ui_story_5031_50311002_83X11_dialog_content = "I see. That's actually pretty common, though.",
  ui_story_5031_50311002_83X12_dialog_content = "It's very hard to free yourself from any emotions so you can be totally focused.",
  ui_story_5031_50311002_83X13_dialog_content = "For me, I got rid of all other thoughts because I held on to that gleam.",
  ui_story_5031_50311002_83X14_dialog_content = "Gleam? I remember you mentioned it. What was it?",
  ui_story_5031_50311002_83X15_dialog_content = "Um... I thought about the fun stuff I did with you and PlayerName.",
  ui_story_5031_50311002_83X16_dialog_content = "And before I knew it, there was silence inside me.",
  ui_story_5031_50311002_83X17_dialog_content = "But that's rather profound and hard for me to describe.",
  ui_story_5031_50311002_83X18_dialog_content = "I see. Then I shall...",
  ui_story_5031_50311002_84_dialog_content = "PlayerName! Carleen! Vice!",
  ui_story_5031_50311002_85_dialog_content = "Why did you leave me behind? We've been looking for you!",
  ui_story_5031_50311002_85X1_dialog_content = "Oops, I can't believe we forgot about you! We were in such a hurry.",
  ui_story_5031_50311002_86_dialog_content = "What's the matter, Fia? Why are you so flustered?",
  ui_story_5031_50311002_87_dialog_content = "Looking for you, of course!",
  ui_story_5031_50311002_88_dialog_content = "Listen, listen! Jeno just came to tell us that...",
  ui_story_5031_50311002_89_dialog_content = "The surfing contest's ranking only serves to decide the sequence for the next contest! We still have another contest!",
  ui_story_5031_50311002_90_dialog_content = "We're performing with the circus as members!",
  ui_story_5031_50311002_91_dialog_content = "That means, we still have a chance!",
  ui_story_5031_50311101_1_dialog_content = "Wait, so what exactly is⁠—",
  ui_story_5031_50311101_2_dialog_content = "Boo-hoo—<size=45>Waaaagh!!</size>",
  ui_story_5031_50311101_3_dialog_content = "<size=45>Our... great goal...</size>",
  ui_story_5031_50311101_4_dialog_content = "The Cloudwhale... At this rate, we'll lose the Cloudwhale! <size=45>Waaaagh!</size>",
  ui_story_5031_50311101_5_dialog_content = "(Geez... The most important final battle is coming up...)",
  ui_story_5031_50311101_6_dialog_content = "(But the wondrous beasts are throwing a tantrum and just won't listen to Fia.)",
  ui_story_5031_50311101_7_dialog_content = "(We're gonna be eliminated like this. I better talk Fia into trying harder!)",
  ui_story_5031_50311101_8_option_content = "Fia, don't be upset!",
  ui_story_5031_50311101_9_dialog_content = "D-Does that mean you have an idea, PlayerName?",
  ui_story_5031_50311101_10_dialog_content = "To be honest, no. But we only have less than an hour to rehearse.",
  ui_story_5031_50311101_11_dialog_content = "The audience will be coming in to see the performance after that.",
  ui_story_5031_50311101_12_dialog_content = "We're so dead! Waaaagh!",
  ui_story_5031_50311101_13_dialog_content = "Stop, stop! Stop crying!",
  ui_story_5031_50311101_14_dialog_content = "Remember? We crossed the entire Astra to protect wondrous beasts against all odds.",
  ui_story_5031_50311101_15_dialog_content = "We managed to do THAT! There's no way something like this can get us down, right?",
  ui_story_5031_50311101_16_dialog_content = "If you would just try harder to get through to Bica, we could give them a great performance!",
  ui_story_5031_50311101_17_dialog_content = "Hai?",
  ui_story_5031_50311101_18_dialog_content = "I... I'm beaten.",
  ui_story_5031_50311101_19_dialog_content = "I mean, we entered the contest without even knowing if the final prize really was the Cloudwhale.",
  ui_story_5031_50311101_20_dialog_content = "(And you only realized that now!?)",
  ui_story_5031_50311101_21_dialog_content = "Hey! That look on your face! You're thinking something bad about me, aren't you!?",
  ui_story_5031_50311101_22_dialog_content = "NO! Of course not! I wouldn't dare!",
  ui_story_5031_50311101_23_dialog_content = "How about this? Let's pretend we're going to the washroom and see if the prize is the Cloudwhale?",
  ui_story_5031_50311101_24_dialog_content = "If it is, then you would be motivated to rehearse with Bica, right?",
  ui_story_5031_50311101_25_dialog_content = "C-Can we really do that?",
  ui_story_5031_50311101_26_dialog_content = "That Jeno seems like a fearsome guy. It'd be bad if we piss him off.",
  ui_story_5031_50311101_27_dialog_content = "Oh, it'll just be a quick peek. It'll be fine!",
  ui_story_5031_50311101_28_dialog_content = "I'll also try to use my psychic abilities so no one will find out!",
  ui_story_5031_50311101_29_dialog_content = "Hmm... Right! That'll do!",
  ui_story_5031_50311101_30_dialog_content = "I trust you, PlayerName. My \"super exotic\" wondrous beast, the Caelestite!",
  ui_story_5031_50311101_31_dialog_content = "Come on, stop calling me a wondrous beast already!",
  ui_story_5031_50311101_32_dialog_content = "Oh, never mind. We don't have much time. Let's move!",
  ui_story_5031_50311101_33_dialog_content = "<color=#e8d9bb>Somewhere deep inside the ship</color>",
  ui_story_5031_50311101_34_dialog_content = "This is the place that the fierce owner wouldn't let us into.",
  ui_story_5031_50311101_35_dialog_content = "It's a labyrinth! Every corridor looks the same and so many forked paths...",
  ui_story_5031_50311101_36_dialog_content = "Where are they hiding the Cloudwhale?",
  ui_story_5031_50311101_37_dialog_content = "Stop, Fia.",
  ui_story_5031_50311101_38_dialog_content = "Let's hide here for a bit. I sense that someone's coming this way.",
  ui_story_5031_50311101_39_dialog_content = "*Yawn* It's the third round of patrol already.",
  ui_story_5031_50311101_40_dialog_content = "I don't know what the boss is thinking, sending us to patrol someplace as airtight as this.",
  ui_story_5031_50311101_41_dialog_content = "Why would there be patrols in a circus? Could the circus owner be hiding something?",
  ui_story_5031_50311101_42_dialog_content = "Without you, I'd definitely be caught and thrown out already, PlayerName.",
  ui_story_5031_50311101_43_dialog_content = "It's all thanks to you, PlayerName. When we find the Cloudwhale, I'll be sure to reward you!",
  ui_story_5031_50311101_44_dialog_content = "How about a pack of animal cookies? Kyllo loves it. Do you think you'll like it, PlayerName?",
  ui_story_5031_50311101_45_dialog_content = "Let's think about that after we find the prize.",
  ui_story_5031_50311101_46_dialog_content = "Uhm...",
  ui_story_5031_50311101_47_dialog_content = "Hold up. I sense two people ahead... But they are not moving.",
  ui_story_5031_50311101_48_dialog_content = "Let's try to sneak past them, then.",
  ui_story_5031_50311101_49_dialog_content = "Wait!",
  ui_story_5031_50311101_50_dialog_content = "Now what?",
  ui_story_5031_50311101_51_dialog_content = "These two people feel... familiar, somehow.",
  ui_story_5031_50311101_52_dialog_content = "Elvis and Patou?",
  ui_story_5031_50311101_53_dialog_content = "The laird and the guard? Why are they here?",
  ui_story_5031_50311101_54_dialog_content = "How would I know? Let's forget about them first and focus on our target.",
  ui_story_5031_50311101_55_dialog_content = "Let's be quiet and not alert them to our presence.",
  ui_story_5031_50311101_56_dialog_content = "I'm sorry, sir. We've searched Jeno's residence and everywhere related but didn't find anything that resembles a key.",
  ui_story_5031_50311101_57_dialog_content = "It's okay. I know where it is.",
  ui_story_5031_50311101_58_dialog_content = "He keeps the key on him at all times.",
  ui_story_5031_50311101_59_dialog_content = "Now, that's gonna be difficult...",
  ui_story_5031_50311101_60_dialog_content = "It's fine. The plan is still a go. We have to make it work tonight.",
  ui_story_5031_50311101_61_dialog_content = "The plan? PlayerName, they are talking about some plan⁠—",
  ui_story_5031_50311101_62_option_content = "Hush!",
  ui_story_5031_50311101_63_dialog_content = "Did you hear that?",
  ui_story_5031_50311101_64_dialog_content = "Who's there? Come out, now!",
  ui_story_5031_50311101_65_dialog_content = "(Oh no! Run!)",
  ui_story_5031_50311101_66_dialog_content = "Huff, huff. We made it onto the deck.",
  ui_story_5031_50311101_67_dialog_content = "Huff!!! You were so rude, PlayerName! You almost suffocated me!",
  ui_story_5031_50311101_68_dialog_content = "I'm sorry! I was too focused on getting away.",
  ui_story_5031_50311101_69_dialog_content = "They headed that way!",
  ui_story_5031_50311101_70_dialog_content = "*Cough* Let's... find them.",
  ui_story_5031_50311101_71_dialog_content = "Oh! They are still on our tail. We better find a place to hide!",
  ui_story_5031_50311101_72_dialog_content = "Hey, PlayerName and Little Fia!",
  ui_story_5031_50311101_73_dialog_content = "I'm not little!",
  ui_story_5031_50311101_74_dialog_content = "Have you done rehearsing?",
  ui_story_5031_50311101_75_dialog_content = "Huh? N-No, not yet. But we needed to do something, so please, excuse...",
  ui_story_5031_50311101_76_dialog_content = "Hehe! I've got an ace up my sleeves!",
  ui_story_5031_50311101_77_dialog_content = "With the help of the Throne, I'll surely be the winner this time!",
  ui_story_5031_50311101_78_dialog_content = "Why don't I give you a sneak preview, my defeated rival!?",
  ui_story_5031_50311101_79_dialog_content = "(Oh, no, we got tangled up with Gronru. Is there anywhere to hide nearby?)",
  ui_story_5031_50311101_80_dialog_content = "PlayerName, they're almost on us!",
  ui_story_5031_50311101_81_dialog_content = "Use your psychic abilities to do something!",
  ui_story_5031_50311101_82_dialog_content = "It doesn't work like that!",
  ui_story_5031_50311101_83_dialog_content = "Invincible—",
  ui_story_5031_50311101_84_dialog_content = "Blue sea—",
  ui_story_5031_50311101_85_dialog_content = "<size=45>Throne!!</size>",
  ui_story_5031_50311101_86_dialog_content = "The light, it's so blinding!",
  ui_story_5031_50311101_87_dialog_content = "Ugh... What's with that light!?",
  ui_story_5031_50311101_88_dialog_content = "Incredible, isn't it?",
  ui_story_5031_50311101_89_dialog_content = "It provides lighting to my Throne!",
  ui_story_5031_50311101_90_dialog_content = "This way, I can even surf on the darkest of nights!",
  ui_story_5031_50311101_91_dialog_content = "Uh, Okay. T-That's cool?",
  ui_story_5031_50311101_92_dialog_content = "That's incredible!",
  ui_story_5031_50311101_93_dialog_content = "It attracted the attention of so many people!?",
  ui_story_5031_50311101_94_dialog_content = "That was amazing! Can you do it again?",
  ui_story_5031_50311101_95_dialog_content = "Again? Of course!",
  ui_story_5031_50311101_96_dialog_content = "Tsk. There are too many people here. They must've gotten away by now.",
  ui_story_5031_50311101_97_dialog_content = "It's okay. They may have eavesdropped, but it doesn't impact our plan.",
  ui_story_5031_50311101_98_dialog_content = "Let's get back. Everything goes according to plan.",
  ui_story_5031_50311101_99_dialog_content = "As you command.",
  ui_story_5031_50311101_100_dialog_content = "They're gone. What a relief.",
  ui_story_5031_50311101_101_dialog_content = "Thanks so much, Gronru!",
  ui_story_5031_50311101_102_dialog_content = "Heh? Thank me for what? What are you talking about?",
  ui_story_5031_50311101_103_dialog_content = "We'll thank you once this is all over.",
  ui_story_5031_50311101_104_dialog_content = "But we got things to do. Later!",
  ui_story_5031_50311101_105_dialog_content = "Hey, why are you in a hurry, my defeated rival!?",
  ui_story_5031_50311101_106_dialog_content = "Well, at least they look more relaxed now.",
  ui_story_5031_50311101_107_dialog_content = "They must've enjoyed my extraordinary performance!",
  ui_story_5031_50311101_108_dialog_content = "After going through all the troubles, we not only wasted time, we still didn't find out what's the grand prize.",
  ui_story_5031_50311101_109_dialog_content = "There's nothing we could do. It was huge and filled with guards inside the ship.",
  ui_story_5031_50311101_110_dialog_content = "There's no way we can search the entire ship with just the two of us.",
  ui_story_5031_50311101_111_dialog_content = "Looks like we'll have to do it the hard way and be the winner!",
  ui_story_5031_50311101_112_dialog_content = "But... We're out of time...",
  ui_story_5031_50311101_113_dialog_content = "My Cloudwhale... My poor Cloudwhale must already be...",
  ui_story_5031_50311101_114_dialog_content = "Why are you crying again!?",
  ui_story_5031_50311101_115_dialog_content = "PlayerName, Fia. Are you still rehearsing?",
  ui_story_5031_50311101_116_dialog_content = "Did you say something rude to Fia to make her cry?",
  ui_story_5031_50311101_117_option_content = "No way!",
  ui_story_5031_50311101_118_option_content = "It's not me!",
  ui_story_5031_50311101_119_dialog_content = "Bica just won't collaborate, so Fia is panicking.",
  ui_story_5031_50311101_120_dialog_content = "Hai hai!",
  ui_story_5031_50311101_121_dialog_content = "They... They are not praising you!",
  ui_story_5031_50311101_122_dialog_content = "Hai?",
  ui_story_5031_50311101_123_dialog_content = "Strange. I thought they had a good relationship.",
  ui_story_5031_50311101_124_dialog_content = "How come Bica suddenly won't collaborate?",
  ui_story_5031_50311101_125_dialog_content = "Did you not talk to Bica about it?",
  ui_story_5031_50311101_126_dialog_content = "I-I talked, but Bica just won't listen!",
  ui_story_5031_50311101_127_dialog_content = "What did you say to Bica?",
  ui_story_5031_50311101_128_dialog_content = "I told Bica to work with me to win that important prize.",
  ui_story_5031_50311101_129_dialog_content = "Then, what did Bica say?",
  ui_story_5031_50311101_130_dialog_content = "Bica didn't say anything...",
  ui_story_5031_50311101_131_dialog_content = "So Bica didn't agree after all?!",
  ui_story_5031_50311101_132_dialog_content = "But Bica has already promised to be my temporary partner... How can it not agree?!",
  ui_story_5031_50311101_133_dialog_content = "Waaaah!!!",
  ui_story_5031_50311101_134_dialog_content = "Oh, don't cry, Fia... You're the only one who can help yourself out this time.",
  ui_story_5031_50311101_135_dialog_content = "Help myself out?",
  ui_story_5031_50311101_136_dialog_content = "Bica may have agreed to be your partner, but that doesn't mean you get to order it around.",
  ui_story_5031_50311101_137_dialog_content = "You're in this situation right now just because you didn't really listen to Bica.",
  ui_story_5031_50311101_138_dialog_content = "Then what should I do?",
  ui_story_5031_50311101_139_dialog_content = "First, apologize to Bica.",
  ui_story_5031_50311101_140_dialog_content = "Not just apologies. You have to ask for Bica's help in this, and have Bica's consent!",
  ui_story_5031_50311101_141_dialog_content = "Would Bica lend me a hand this time?",
  ui_story_5031_50311101_142_dialog_content = "It looks much more ferocious than a wild Bica...",
  ui_story_5031_50311101_143_dialog_content = "That depends on your attitude.",
  ui_story_5031_50311101_144_dialog_content = "You can do it, Fia.",
  ui_story_5031_50311101_145_dialog_content = "Yeah. Don't give up. Just do your best.",
  ui_story_5031_50311101_146_dialog_content = "Al-Alright. I'll try.",
  ui_story_5031_50311101_147_dialog_content = "Bica, I...",
  ui_story_5031_50311101_148_dialog_content = "I'm sorry.",
  ui_story_5031_50311101_149_dialog_content = "Hai hai?",
  ui_story_5031_50311101_150_dialog_content = "(Bica puts its paws beside its ears. Is it asking Fia to speak louder?)",
  ui_story_5031_50311101_151_dialog_content = "I...",
  ui_story_5031_50311101_152_dialog_content = "<size=45>I'm sorry!</size>",
  ui_story_5031_50311101_153_dialog_content = "It was my fault. I shouldn't have forced you to help with my performance, ignoring your will...",
  ui_story_5031_50311101_154_dialog_content = "I'm so sorry. It won't happen the next time... Th-There won't be a next time!",
  ui_story_5031_50311101_155_dialog_content = "I'll always ask about your feelings in advance in the future... Boo-hoo...",
  ui_story_5031_50311101_156_dialog_content = "Hai?",
  ui_story_5031_50311101_157_dialog_content = "And afterward? Er, afterward... how about I buy you a good meal?",
  ui_story_5031_50311101_158_dialog_content = "Hai—Hai hai?",
  ui_story_5031_50311101_159_dialog_content = "Huh? You wanna have Mr. Peng's legendary grapes?",
  ui_story_5031_50311101_160_dialog_content = "You said another Bica told you that?",
  ui_story_5031_50311101_161_dialog_content = "But that's so expensive...",
  ui_story_5031_50311101_162_dialog_content = "Hai hai?",
  ui_story_5031_50311101_163_dialog_content = "No, no! I'm not complaining!",
  ui_story_5031_50311101_164_dialog_content = "I'll buy anything for you, as long as you forgive me. Boo-hoo...",
  ui_story_5031_50311101_165_dialog_content = "(Oh, just look at Fia's expression right now.)",
  ui_story_5031_50311101_166_dialog_content = "(She should really take this chance to learn how to work with others.)",
  ui_story_5031_50311101_167_dialog_content = "Hai!",
  ui_story_5031_50311101_168_dialog_content = "(Bica seems happy. Did Bica accept Fia's apologies?)",
  ui_story_5031_50311101_169_dialog_content = "You forgive me? That's wonderful!",
  ui_story_5031_50311101_170_dialog_content = "Then about the performance...",
  ui_story_5031_50311101_171_dialog_content = "Hai hai!",
  ui_story_5031_50311101_172_dialog_content = "Huh?",
  ui_story_5031_50311101_173_dialog_content = "Fia, what did Bica say?",
  ui_story_5031_50311101_174_dialog_content = "It said... \"That depends on you.\"",
  ui_story_5031_50311101_175_dialog_content = "Is it that vague?!",
  ui_story_5031_50311101_176_dialog_content = "Is it going to be okay? Shouldn't you ask Bica one more time, just to be sure?",
  ui_story_5031_50311101_177_dialog_content = "I mean, the outcome of the final battle depends on this...",
  ui_story_5031_50311101_178_dialog_content = "But I...",
  ui_story_5031_50311101_179_dialog_content = "The final battle is upon us! Contestants, it's time!",
  ui_story_5031_50311101_180_dialog_content = "Already?!",
  ui_story_5031_50311101_181_dialog_content = "It's been an hour? There's no other choice...",
  ui_story_5031_50311101_182_dialog_content = "We have to do it!",
  ui_story_5031_50311101_183_dialog_content = "Leave it to me!",
  ui_story_5031_50311101_184_dialog_content = "I'll try to earn as many points as I can.",
  ui_story_5031_50311101_185_dialog_content = "Bica and I will do our best too!",
  ui_story_5031_50311101_186_dialog_content = "Hai hai!",
  ui_story_5031_50311201_1_dialog_content = "As night sets, the third round of the competition is about to begin!",
  ui_story_5031_50311201_2_dialog_content = "Wow!!!",
  ui_story_5031_50311201_3_dialog_content = "Based on the results from the previous rounds, two teams will take on each other on the stage!",
  ui_story_5031_50311201_4_dialog_content = "They are... the leading team from Illumina!",
  ui_story_5031_50311201_5_dialog_content = "And a rising team led by the rookie extrozoologist Fia!",
  ui_story_5031_50311201_6_dialog_content = "Ohhhhhh!",
  ui_story_5031_50311201_7_dialog_content = "That's a warm welcome from the audience. Great!",
  ui_story_5031_50311201_8_dialog_content = "Now, before the game officially begins, let's enjoy the opening performance by Ringmaster—Jeno and the three sisters!",
  ui_story_5031_50311201_9_dialog_content = "First, Ringmaster Jeno!",
  ui_story_5031_50311201_10_dialog_content = "The Foresight Ritual, an ability sought after by countless Aurorians throughout the ages.",
  ui_story_5031_50311201_11_dialog_content = "To communicate with greater existences, to decipher fragments of the past or future...",
  ui_story_5031_50311201_12_dialog_content = "And to be able to perceive true history or peek into the future.",
  ui_story_5031_50311201_13_dialog_content = "Tonight, I shall demonstrate this ancient power and answer all your questions.",
  ui_story_5031_50311201_14_dialog_content = "This deck of Origin Card shall be my aid.",
  ui_story_5031_50311201_15_dialog_content = "Oh! This is it! The legendary Foresight Ritual!",
  ui_story_5031_50311201_16_dialog_content = "Being able to summon Eclipsites and foresee the future. What secrets does the power of Origin hold?",
  ui_story_5031_50311201_17_dialog_content = "Next, I must ask the assistance from a lucky audience.",
  ui_story_5031_50311201_18_dialog_content = "Who is the fated guest that will cross paths with me?",
  ui_story_5031_50311201_19_dialog_content = "Me!!!",
  ui_story_5031_50311201_20_dialog_content = "Me! Pick me!",
  ui_story_5031_50311201_21_dialog_content = "I sense it. I sense it now...",
  ui_story_5031_50311201_22_dialog_content = "The Origin Card points my fate toward... YOU!",
  ui_story_5031_50311201_23_dialog_content = "The lady on the right of the front row.",
  ui_story_5031_50311201_24_dialog_content = "Me-Me?",
  ui_story_5031_50311201_25_dialog_content = "Yes, you. Please come up here.",
  ui_story_5031_50311201_26_dialog_content = "You can ask me any question, and I shall answer you using Origin Card.",
  ui_story_5031_50311201_27_dialog_content = "Anything?",
  ui_story_5031_50311201_28_dialog_content = "Anything.",
  ui_story_5031_50311201_29_dialog_content = "Then... Do you know where I come from?",
  ui_story_5031_50311201_30_dialog_content = "Oh, Origin Card, be my eyes and give me the sight of truth! Tell me where this lady is from!",
  ui_story_5031_50311201_31_dialog_content = "(The cards dance between Jeno's fingers, and then he draws one out!)",
  ui_story_5031_50311201_32_dialog_content = "The Origin Card has given me the answer. You're from Petyaburg.",
  ui_story_5031_50311201_33_dialog_content = "How did you know?!",
  ui_story_5031_50311201_34_dialog_content = "The Origin Card gave me the answer. Not only that, it also told me something else—",
  ui_story_5031_50311201_35_dialog_content = "You are a family of a viscount, and such a happy family you have.",
  ui_story_5031_50311201_36_dialog_content = "However, for some reason, you're not sitting with your partner, but you still share a strong bond with him.",
  ui_story_5031_50311201_37_dialog_content = "That is amazing...",
  ui_story_5031_50311201_38_dialog_content = "The tickets were selling like hotcakes, and we could only get separate seats.",
  ui_story_5031_50311201_39_dialog_content = "And, your partner insisted on giving the front-row seat to you.",
  ui_story_5031_50311201_40_dialog_content = "Y-Yes...",
  ui_story_5031_50311201_41_dialog_content = "The Origin Card wishes you a happy life together! You may go back to your seat now.",
  ui_story_5031_50311201_42_dialog_content = "Gosh! That's incredible!!!",
  ui_story_5031_50311201_43_dialog_content = "Pick another one! Pick me!",
  ui_story_5031_50311201_44_dialog_content = "Time is fleeting. Even the Origin Card must abide by the laws of time.",
  ui_story_5031_50311201_45_dialog_content = "And please enjoy the following performance. I look forward to the next crossing of fates.",
  ui_story_5031_50311201_46_dialog_content = "What a wonderful performance by Ringmaster Jeno!",
  ui_story_5031_50311201_47_dialog_content = "Now, please enjoy the thrilling high-flying trapeze from Merylt, Subli, and Frimet!",
  ui_story_5031_50311201_48_dialog_content = "Right... Here we go!",
  ui_story_5031_50311201_49_dialog_content = "Let's make their jaws drop!",
  ui_story_5031_50311201_50_dialog_content = "Okay!",
  ui_story_5031_50311201_51_dialog_content = "Let's do this!",
  ui_story_5031_50311201_52_dialog_content = "(Merylt climbs up the ladder and extends her hand toward the other two.)",
  ui_story_5031_50311201_53_dialog_content = "Hee!",
  ui_story_5031_50311201_54_dialog_content = "Frimet, don't drop me!",
  ui_story_5031_50311201_55_dialog_content = "Subli... You're so heavy...",
  ui_story_5031_50311201_56_dialog_content = "(That was close! Thankfully, Frimet caught Subli!)",
  ui_story_5031_50311201_57_dialog_content = "I-I'm going next!",
  ui_story_5031_50311201_58_dialog_content = "(Huh? Are they gonna...?)",
  ui_story_5031_50311201_59_dialog_content = "Yo!",
  ui_story_5031_50311201_60_dialog_content = "Right there!",
  ui_story_5031_50311201_61_dialog_content = "It's... even heavier now!",
  ui_story_5031_50311201_62_dialog_content = "It worked!",
  ui_story_5031_50311201_63_option_content = "Amazing!",
  ui_story_5031_50311201_64_dialog_content = "Ohhhhhh! That's incredible!",
  ui_story_5031_50311201_65_dialog_content = "Th-Thank you all!",
  ui_story_5031_50311201_66_dialog_content = "Are you impressed?",
  ui_story_5031_50311201_67_dialog_content = "Very impressed!",
  ui_story_5031_50311201_68_dialog_content = "It was but a simple performance...",
  ui_story_5031_50311201_69_dialog_content = "But we gladly accept your applause!",
  ui_story_5031_50311201_70_dialog_content = "Please look forward to the competition!",
  ui_story_5031_50311201_71_dialog_content = "We thank you for your wonderful performance!",
  ui_story_5031_50311201_72_dialog_content = "Now's time to announce... The last round begins—NOW!",
  ui_story_5031_50311201_73_dialog_content = "The first up is Team Illumina. Gronru and Ciel will demonstrate their special moves!",
  ui_story_5031_50311201_74_dialog_content = "I modified my mecha based on Gronru's feedback, just for this moment...",
  ui_story_5031_50311201_75_dialog_content = "It's gotta work, please!",
  ui_story_5031_50311201_76_dialog_content = "Oh! It looks like Ciel has something incredible prepared!",
  ui_story_5031_50311201_77_dialog_content = "...",
  ui_story_5031_50311201_78_dialog_content = "Huh? Fia? Are you alright? Why are you shivering?",
  ui_story_5031_50311201_79_dialog_content = "I'm so nervous...",
  ui_story_5031_50311201_80_dialog_content = "Are you nervous?",
  ui_story_5031_50311201_81_dialog_content = "N-No way!",
  ui_story_5031_50311201_82_dialog_content = "I'm an extrozoologist!, there's no way I'm—OUCH!",
  ui_story_5031_50311201_83_dialog_content = "You're so nervous that you bit your tongue?",
  ui_story_5031_50311201_84_dialog_content = "I'm not nervous!",
  ui_story_5031_50311201_85_dialog_content = "Fia, just clear your mind and take a deep breath.",
  ui_story_5031_50311201_86_dialog_content = "*Inhale*",
  ui_story_5031_50311201_87_dialog_content = "*Exhale*",
  ui_story_5031_50311201_88_dialog_content = "Feel better now?",
  ui_story_5031_50311201_89_dialog_content = "Oh no... not any better. My heart is pounding!",
  ui_story_5031_50311201_90_dialog_content = "Ciel and Gronru look incredible but I don't even know if Bica is gonna help...",
  ui_story_5031_50311201_91_dialog_content = "There's no way we'll win!",
  ui_story_5031_50311201_92_dialog_content = "Don't panic. There's no use in thinking that now.",
  ui_story_5031_50311201_93_dialog_content = "Just focus on what you need to do. Just focus on the performance itself.",
  ui_story_5031_50311201_94_dialog_content = "But what if Bica still won't collaborate?",
  ui_story_5031_50311201_95_dialog_content = "Well...",
  ui_story_5031_50311201_96_option_content = "Have you ever heard a saying?",
  ui_story_5031_50311201_97_dialog_content = "What saying?",
  ui_story_5031_50311201_98_dialog_content = "Compliments can work magic!",
  ui_story_5031_50311201_99_dialog_content = "What?!",
  ui_story_5031_50311201_100_dialog_content = "More or less what I meant. Anyway, just try to make Bica happy so it'll help.",
  ui_story_5031_50311201_101_dialog_content = "All that matters is getting the grand prize, whether or not it's the Cloudwhale. All other concerns are secondary!",
  ui_story_5031_50311201_102_dialog_content = "I-I'll give it a try!",
  ui_story_5031_50311201_103_dialog_content = "Good luck. Vice, Carleen, and I will do our best to earn points.",
  ui_story_5031_50311201_104_dialog_content = "Our final score would be our average.",
  ui_story_5031_50311201_105_dialog_content = "So, the best way to win this is that we all do our best!",
  ui_story_5031_50311201_106_dialog_content = "I-I see...",
  ui_story_5031_50311201_107_dialog_content = "Look! That was an incredible performance by Gronru and Ciel!",
  ui_story_5031_50311201_108_dialog_content = "Ciel's mecha and Gronru's throne are dancing in dazzling light!",
  ui_story_5031_50311201_109_dialog_content = "Ciel's mecha was as if without weight, performing combat-like dances with extreme skills!",
  ui_story_5031_50311201_110_dialog_content = "She stroke a perfect balance between weight and beauty!",
  ui_story_5031_50311201_111_dialog_content = "Now, it's Team Fia's turn to come up the stage!",
  ui_story_5031_50311201_112_dialog_content = "What extraordinary performance does she have in store for us?",
  ui_story_5031_50311201_113_dialog_content = "Phew... It's time. Let's go, Bica!",
  ui_story_5031_50311201_114_dialog_content = "Hai!",
  ui_story_5031_50311201_115_dialog_content = "(Good luck, Fia, Bica!)",
  ui_story_5031_50311201_116_dialog_content = "(Please, don't let anything go wrong this time...)",
  ui_story_5031_50311201_117_dialog_content = "Alright! Let's do this! Bica, come here!",
  ui_story_5031_50311201_118_dialog_content = "Hai!",
  ui_story_5031_50311201_119_dialog_content = "Just like I said, Bica. Jump and do a somersault, okay?",
  ui_story_5031_50311201_120_dialog_content = "Hai hai?",
  ui_story_5031_50311201_121_dialog_content = "(Bica is looking at Fia with a mischievous smile?!)",
  ui_story_5031_50311201_122_dialog_content = "Please... please collaborate!",
  ui_story_5031_50311201_123_dialog_content = "Hai?",
  ui_story_5031_50311201_124_dialog_content = "(Bica is playing dumb?!)",
  ui_story_5031_50311201_125_dialog_content = "What's going on?",
  ui_story_5031_50311201_126_dialog_content = "We didn't spend the money to watch you waste our time!",
  ui_story_5031_50311201_127_dialog_content = "*Sniffle*",
  ui_story_5031_50311201_128_dialog_content = "P-Please!",
  ui_story_5031_50311201_129_dialog_content = "Hai!",
  ui_story_5031_50311201_129X1_dialog_content = "Bica is the best! It must be easy for you to take care of such a small case!",
  ui_story_5031_50311201_130_dialog_content = "I'll buy you Mr. Peng's grapes right after this!",
  ui_story_5031_50311201_131_dialog_content = "Hai hai!",
  ui_story_5031_50311201_132_dialog_content = "That worked?!",
  ui_story_5031_50311201_133_dialog_content = "Hai!",
  ui_story_5031_50311201_134_dialog_content = "Yo-ho! Do another one!",
  ui_story_5031_50311201_135_dialog_content = "Now, I'll throw this ball. Please catch it!",
  ui_story_5031_50311201_136_dialog_content = "Hai hai!",
  ui_story_5031_50311201_137_dialog_content = "Hai!",
  ui_story_5031_50311201_138_dialog_content = "Nicely done!",
  ui_story_5031_50311201_139_dialog_content = "(Great, Bica is willing to help me in exchange for the grapes!)",
  ui_story_5031_50311201_140_dialog_content = "Hai?",
  ui_story_5031_50311201_141_dialog_content = "Hey, wait! That's not food!",
  ui_story_5031_50311201_142_dialog_content = "Hahahahaha!",
  ui_story_5031_50311201_143_dialog_content = "(That was close. At least the audience thought that was part of the performance.)",
  ui_story_5031_50311201_144_dialog_content = "Now, let's show the audience your secret trick, Bica!",
  ui_story_5031_50311201_145_dialog_content = "Secret trick? What secret trick?",
  ui_story_5031_50311201_146_dialog_content = "Are you gonna make Bica swallow a boulder just like the last time with the hunter?",
  ui_story_5031_50311201_147_dialog_content = "That's dangerous!",
  ui_story_5031_50311201_148_dialog_content = "I'm not gonna do anything like that!",
  ui_story_5031_50311201_149_dialog_content = "I've prepared this!",
  ui_story_5031_50311201_150_dialog_content = "Look!",
  ui_story_5031_50311201_151_dialog_content = "Bubbles?",
  ui_story_5031_50311201_152_dialog_content = "Oh! So many beautiful bubbles!",
  ui_story_5031_50311201_153_dialog_content = "But what does that have anything to do with a beast taming?",
  ui_story_5031_50311201_154_dialog_content = "It's up to Bica now!",
  ui_story_5031_50311201_155_dialog_content = "Hai hai!",
  ui_story_5031_50311201_156_dialog_content = "Hai—!",
  ui_story_5031_50311201_157_dialog_content = "(Right! The bubbles are all spheres. Just what Bica likes!)",
  ui_story_5031_50311201_158_dialog_content = "Oooh! That little guy even has that talent?!",
  ui_story_5031_50311201_159_dialog_content = "Hai!",
  ui_story_5031_50311201_160_dialog_content = "H-Hai!",
  ui_story_5031_50311201_161_dialog_content = "*Burp*",
  ui_story_5031_50311201_162_dialog_content = "(Bica swallowed too much air, and its body became bloated!)",
  ui_story_5031_50311201_163_dialog_content = "Hahahahaha! That's so adorable!",
  ui_story_5031_50311201_164_dialog_content = "That's it for our performance!",
  ui_story_5031_50311201_165_dialog_content = "Please look forward to what my teammates prepare for you next!",
  ui_story_5031_50311201_166_dialog_content = "Wow!!!",
  ui_story_5031_50311201_167_dialog_content = "After Fia's performance was done, I, Vice, and Carleen also took the stage in that order.",
  ui_story_5031_50311201_168_dialog_content = "I used my psychic abilities to read minds.",
  ui_story_5031_50311201_169_dialog_content = "Vice demonstrated her impressive marksmanship...",
  ui_story_5031_50311201_170_dialog_content = "And I can only hope that she won't put the target apple on the top of my head, the next time...",
  ui_story_5031_50311201_171_dialog_content = "Carleen was the black swan. She surprised everyone with her ballet.",
  ui_story_5031_50311201_172_dialog_content = "What's more... She even asked Jeno to put Eclipsites on the stage as part of her show!",
  ui_story_5031_50311202_1_dialog_content = "Ice Blossom!",
  ui_story_5031_50311202_2_dialog_content = "I bet Carleen is the only one who ever combined ballet and combat!",
  ui_story_5031_50311202_3_dialog_content = "Which is AMAZING!",
  ui_story_5031_50311202_4_dialog_content = "A big round of applause for Carleen's ballet! That was both thrilling and spectacular!",
  ui_story_5031_50311202_5_dialog_content = "Now, the moment everyone's waiting for...",
  ui_story_5031_50311202_6_dialog_content = "Time for the results!",
  ui_story_5031_50311202_7_dialog_content = "Hai!",
  ui_story_5031_50311202_8_dialog_content = "I'm so nervous... I can't... breathe...",
  ui_story_5031_50311202_9_dialog_content = "Hang on, Fia!",
  ui_story_5031_50311202_10_dialog_content = "Think about your Cloudwhale!",
  ui_story_5031_50311202_11_dialog_content = "Cloudwhale, yes, my Cloudwhale... My grand prize!",
  ui_story_5031_50311202_12_dialog_content = "The winner of this contest is...",
  ui_story_5031_50311202_13_dialog_content = "Team Fia!",
  ui_story_5031_50311202_14_dialog_content = "I-I won...?",
  ui_story_5031_50311202_15_dialog_content = "Oh, yeah! I won!",
  ui_story_5031_50311202_16_dialog_content = "Hai!",
  ui_story_5031_50311202_17_dialog_content = "Despite Fia's less-than-perfect performance, the teamwork between them is truly impressive.",
  ui_story_5031_50311202_18_dialog_content = "And Miss Carleen's ballet was just stellar.",
  ui_story_5031_50311202_19_dialog_content = "So, Team Fia's average score is high enough to earn them the first place!",
  ui_story_5031_50311202_20_dialog_content = "Congratulations, Fia!",
  ui_story_5031_50311202_21_dialog_content = "I never knew a little girl like you could be so amazing, Fia!",
  ui_story_5031_50311202_22_dialog_content = "You've defeated me, but I'm not going to lose to you next time!",
  ui_story_5031_50311202_23_dialog_content = "Congratulations, Fia! You finish the performance and earn a victory!",
  ui_story_5031_50311202_24_dialog_content = "But I'm really curious. What exactly is the grand prize?",
  ui_story_5031_50311202_25_dialog_content = "Could it really be the Cloudwhale that Fia's been looking for?",
  ui_story_5031_50311202_26_dialog_content = "Right! My grand prize, the one and only treasure from the depth of the sea!",
  ui_story_5031_50311202_27_dialog_content = "Of course. I have the prize with me.",
  ui_story_5031_50311202_28_dialog_content = "Here you go.",
  ui_story_5031_50311202_29_dialog_content = "Lo! Lo, lo, lo!",
  ui_story_5031_50311202_30_dialog_content = "Whaaaat?! I-Isn't this... KYLLO?!",
  ui_story_5031_50311202_31_dialog_content = "Didn't I send you to the sea to track the Cloudwhale down?",
  ui_story_5031_50311202_32_dialog_content = "No wonder I never heard back from you! You've been slacking off all this time!",
  ui_story_5031_50311202_33_dialog_content = "I captured this animal from the sea not long ago.",
  ui_story_5031_50311202_34_dialog_content = "It looks delicious, so I plan to make it into a seafood chowder for the winner.",
  ui_story_5031_50311202_35_dialog_content = "Lo, lo, lo? Lo!",
  ui_story_5031_50311202_36_dialog_content = "You can't cook Kyllo!",
  ui_story_5031_50311202_37_dialog_content = "It's my friend!",
  ui_story_5031_50311202_38_dialog_content = "A friend? And I thought it was some rare and delicious food ingredient.",
  ui_story_5031_50311202_39_dialog_content = "Well, you are the winner, and it's your prize. I'll leave it to you.",
  ui_story_5031_50311202_40_dialog_content = "Lo, lo...",
  ui_story_5031_50311202_41_dialog_content = "Phew, you careless little thing! You know you almost died?",
  ui_story_5031_50311202_42_dialog_content = "Lo... Lo, lo!",
  ui_story_5031_50311202_43_dialog_content = "Huh? You said you got caught in a net while looking for the Cloudwhale under the sea?",
  ui_story_5031_50311202_44_dialog_content = "And you got locked up in the ship for days?",
  ui_story_5031_50311202_45_dialog_content = "Then... Did you see the Cloudwhale on the ship?",
  ui_story_5031_50311202_46_dialog_content = "Lo? Lo, lo!",
  ui_story_5031_50311202_47_dialog_content = "No? How sad...",
  ui_story_5031_50311202_48_dialog_content = "Now that the winner has been announced, would everyone please come up to the deck?",
  ui_story_5031_50311202_49_dialog_content = "The banquet and fireworks are about to begin.",
  ui_story_5031_50311202_50_dialog_content = "Did you say fireworks? Let's hurry and get ourselves a good spot!",
  ui_story_5031_50311202_51_dialog_content = "No Cloudwhale... How come the grand prize isn't the Cloudwhale?!",
  ui_story_5031_50311202_52_dialog_content = "All that work for nothing!",
  ui_story_5031_50311202_53_dialog_content = "How can that be a whale?",
  ui_story_5031_50311202_54_dialog_content = "The Emerald won't be able to handle it, even if we're only talking about whale calf.",
  ui_story_5031_50311202_55_dialog_content = "Am I right to assume that you have never seen a whale, young lady?",
  ui_story_5031_50311202_56_dialog_content = "S-So what if I've never seen one?!",
  ui_story_5031_50311202_57_dialog_content = "It's an exotic. It's only normal that I haven't seen one before...",
  ui_story_5031_50311202_58_dialog_content = "Pfft...",
  ui_story_5031_50311202_59_dialog_content = "It's not funny! Stop laughing!",
  ui_story_5031_50311202_60_dialog_content = "Alright, alright. It wasn't all for nothing, you know.",
  ui_story_5031_50311202_61_option_content = "We did win the contest",
  ui_story_5031_50311202_62_dialog_content = "Fia and Bica are now friends, too, isn't that right?",
  ui_story_5031_50311202_63_dialog_content = "Hai!",
  ui_story_5031_50311202_64_dialog_content = "A-Alright! I'm gonna buy you grapes!",
  ui_story_5031_50311202_65_option_content = "At least you saved Kyllo.",
  ui_story_5031_50311202_66_dialog_content = "Lo, lo!",
  ui_story_5031_50311202_67_dialog_content = "Alas... I just didn't expect the grand prize would be Kyllo.",
  ui_story_5031_50311202_68_dialog_content = "Since you got captured by accident, then you better get back to looking for the Cloudwhale.",
  ui_story_5031_50311202_69_dialog_content = "Lo?",
  ui_story_5031_50311202_70_dialog_content = "I don't need your help here. Alright, alright, go at it!",
  ui_story_5031_50311202_71_dialog_content = "Let me give you a hand and launch you into the sea, then!",
  ui_story_5031_50311202_72_dialog_content = "Lo—!",
  ui_story_5031_50311202_73_dialog_content = "(Kyllo becomes a falling star that streaks across the sky... Fia is so terrifying!)",
  ui_story_5031_50311202_74_dialog_content = "Hmm... Are you really an extrozoologist?",
  ui_story_5031_50311202_75_dialog_content = "Of course I am!",
  ui_story_5031_50311202_76_dialog_content = "But how did your divination work, Jeno?",
  ui_story_5031_50311202_77_dialog_content = "Are you also a Caelestite who possesses psychic abilities?",
  ui_story_5031_50311202_78_dialog_content = "That wasn't divination at all, not really. It was all my observation skills.",
  ui_story_5031_50311202_79_dialog_content = "Remember that lady? Her dress may seem nothing out of the ordinary at a glance, but the fabric is specific to Petyaburg.",
  ui_story_5031_50311202_80_dialog_content = "As for her love life... the ring on her finger told me she's married.",
  ui_story_5031_50311202_81_dialog_content = "And, the way she kept on looking back meant she was likely not sitting with her partner.",
  ui_story_5031_50311202_82_dialog_content = "I just put everything together and—",
  ui_story_5031_50311202_83_dialog_content = "Sorry to intrude, Jeno, but there's something I need to speak to you about, in private, by the stage.",
  ui_story_5031_50311202_84_dialog_content = "Sure.",
  ui_story_5031_50311202_85_dialog_content = "Sorry, everyone. I'll be right back.",
  ui_story_5031_50311202_86_dialog_content = "Hey! At least finish your sentence!",
  ui_story_5031_50311202_87_dialog_content = "Geez, just walked out on a conversation like that.",
  ui_story_5031_50311202_88_dialog_content = "The fireworks have started!",
  ui_story_5031_50311202_89_dialog_content = "That is really beautiful.",
  ui_story_5031_50311202_90_dialog_content = "So there you are!",
  ui_story_5031_50311202_91_dialog_content = "E-Everyone's here...",
  ui_story_5031_50311202_92_dialog_content = "Rainbow, what's with that bowl of food in your lap? You gonna take it back to eat?",
  ui_story_5031_50311202_93_dialog_content = "You're not gonna join us?",
  ui_story_5031_50311202_94_dialog_content = "I have other plans!",
  ui_story_5031_50311202_95_dialog_content = "Sure, the fireworks are beautiful, but Ciel and I just came up with a great idea on how to modify our mecha!",
  ui_story_5031_50311202_96_dialog_content = "We can't wait to get working on it!",
  ui_story_5031_50311202_97_dialog_content = "Yeah...",
  ui_story_5031_50311202_98_dialog_content = "Sorry that we won't be able to spend time with you tonight.",
  ui_story_5031_50311202_99_dialog_content = "Oh, don't worry about it. We have lots of time in the future!",
  ui_story_5031_50311202_100_dialog_content = "We'll be going then!",
  ui_story_5031_50311202_101_dialog_content = "They seem really close. I'm a bit envious of them.",
  ui_story_5031_50311202_102_dialog_content = "Are you missing something, Carleen?",
  ui_story_5031_50311202_103_dialog_content = "You have me and PlayerName!",
  ui_story_5031_50311202_104_dialog_content = "Yeah, we've been traveling and sticking together through everything all this time!",
  ui_story_5031_50311202_105_dialog_content = "Exactly. Just like this time!",
  ui_story_5031_50311202_106_dialog_content = "We would've lost if it weren't for your extraordinary ballet that earned us so many points!",
  ui_story_5031_50311202_107_dialog_content = "That's right! It's all thanks to you!",
  ui_story_5031_50311202_108_dialog_content = "So don't start acting like a stranger, you!",
  ui_story_5031_50311202_109_dialog_content = "Is that so...? All right, all right.",
  ui_story_5031_50311202_110_dialog_content = "Thank you.",
  ui_story_5031_50311202_111_dialog_content = "Yup!",
  ui_story_5031_50311301_1_dialog_content = "I didn't notice it earlier during the day, but if you look closely, Harbor City really looks enchanting at night under the fireworks.",
  ui_story_5031_50311301_2_dialog_content = "Yeah. Its white buildings got painted by the radiant fireworks. It's even more charming than during the day!",
  ui_story_5031_50311301_3_dialog_content = "PlayerName, Vice, and Fia. I want to go talk to Elvis.",
  ui_story_5031_50311301_4_dialog_content = "Would you please wait for me for a bit?",
  ui_story_5031_50311301_5_dialog_content = "Sure thing! We'll be right here.",
  ui_story_5031_50311301_6_dialog_content = "All right. Thanks.",
  ui_story_5031_50311301_7_dialog_content = "Looks like it's finally over...",
  ui_story_5031_50311301_8_dialog_content = "But I still haven't found my Cloudwhale...",
  ui_story_5031_50311301_9_dialog_content = "Now, where could the legendary Cloudwhale be...?",
  ui_story_5031_50311301_10_dialog_content = "Don't be hasty. Some things you just can't get in a hurry.",
  ui_story_5031_50311301_11_dialog_content = "That's right. Like sometimes the more I was in a rush to find my hairpins after I woke up, the harder it was for me to find them.",
  ui_story_5031_50311301_12_dialog_content = "But when I finally gave up, I'd realize it's been next to me all along!",
  ui_story_5031_50311301_13_dialog_content = "Really?",
  ui_story_5031_50311301_14_dialog_content = "Of course.",
  ui_story_5031_50311301_15_dialog_content = "All right, I'll trust you this time.",
  ui_story_5031_50311301_16_dialog_content = "Hi, everyone.",
  ui_story_5031_50311301_17_dialog_content = "Carleen? Did you have a quick talk?",
  ui_story_5031_50311301_18_dialog_content = "No, not at all. I couldn't find Elvis anywhere.",
  ui_story_5031_50311301_19_dialog_content = "Didn't he drag Jeno to chat by the stage?",
  ui_story_5031_50311301_20_dialog_content = "I dropped by there but didn't see them.",
  ui_story_5031_50311301_21_dialog_content = "Elvis and Jeno...",
  ui_story_5031_50311301_22_dialog_content = "Could they be heading for the cabin?",
  ui_story_5031_50311301_23_dialog_content = "Cabin? Jeno never let anyone get close to it, did he?",
  ui_story_5031_50311301_24_dialog_content = "But if they're not anywhere else, that's probably where they are.",
  ui_story_5031_50311301_25_dialog_content = "Let's go check. There should be people who know where they went.",
  ui_story_5031_50311301_26_dialog_content = "How do you know the path to the cabin well, PlayerName?",
  ui_story_5031_50311301_27_dialog_content = "Because Fia and I were once pursued by Elvis and Patou right here for a long while.",
  ui_story_5031_50311301_28_dialog_content = "Elvis and Patou? How did that happen?",
  ui_story_5031_50311301_29_dialog_content = "Long story short, we...",
  ui_story_5031_50311301_30_dialog_content = "Look, PlayerName, there's someone on the ground over there!",
  ui_story_5031_50311301_31_dialog_content = "Is that... Jeno?!",
  ui_story_5031_50311301_32_dialog_content = "Really? You'd draw me a picture?",
  ui_story_5031_50311301_33_dialog_content = "Yeah, but I draw slow and not very good, either.",
  ui_story_5031_50311301_34_dialog_content = "It's okay. Your drawings are the best to me!",
  ui_story_5031_50311301_35_dialog_content = "Well... I guess I'll see you tomorrow morning at the port?",
  ui_story_5031_50311301_36_dialog_content = "Draw it for me after your work at the seaside, and I'll make seafood soup for you!",
  ui_story_5031_50311301_37_dialog_content = "Wow, seafood soup from Elvis!",
  ui_story_5031_50311301_38_dialog_content = "Awesome! It's a deal, then!",
  ui_story_5031_50311301_39_dialog_content = "See you tomorrow!",
  ui_story_5031_50311301_40_dialog_content = "S-see you tomorrow!",
  ui_story_5031_50311301_41_dialog_content = "...",
  ui_story_5031_50311301_42_dialog_content = "...",
  ui_story_5031_50311301_43_dialog_content = "We had a promise.",
  ui_story_5031_50311301_44_dialog_content = "We had a promise...",
  ui_story_5031_50311301_45_dialog_content = "<size=33>Je...</size>",
  ui_story_5031_50311301_46_dialog_content = "<size=33>Jeno...</size>",
  ui_story_5031_50311301_47_dialog_content = "Who's there?",
  ui_story_5031_50311301_48_dialog_content = "Jeno!",
  ui_story_5031_50311301_49_dialog_content = "Elvis? Is that you? Have you come back?",
  ui_story_5031_50311301_50_dialog_content = "<size=45>Wake up, Jeno!</size>",
  ui_story_5031_50311301_51_dialog_content = "Elvis!",
  ui_story_5031_50311301_52_dialog_content = "Ahhhh!",
  ui_story_5031_50311301_53_dialog_content = "Ahhhh!",
  ui_story_5031_50311301_54_dialog_content = "Why are you yelling, PlayerName? You freaked me out!",
  ui_story_5031_50311301_55_dialog_content = "S-Sorry, I was scared too.",
  ui_story_5031_50311301_56_dialog_content = "How are you feeling, Jeno? Are you hurt?",
  ui_story_5031_50311301_57_dialog_content = "What... What am I doing here?",
  ui_story_5031_50311301_58_dialog_content = "Shouldn't we be asking you that?",
  ui_story_5031_50311301_59_dialog_content = "Why are you sleeping here? We've been looking for you.",
  ui_story_5031_50311301_60_dialog_content = "Uh, Fia, that's clearly not \"sleeping\"...",
  ui_story_5031_50311301_61_dialog_content = "Here's the thing. The fireworks and celebration ended, so we wanted to say goodbye to Laird Elvis.",
  ui_story_5031_50311301_62_dialog_content = "But we couldn't find him anywhere, so we thought you two might be in the cabin.",
  ui_story_5031_50311301_63_dialog_content = "We took a chance only to see you were lying here, unconscious.",
  ui_story_5031_50311301_64_dialog_content = "Well, I... Ouch.",
  ui_story_5031_50311301_65_dialog_content = "No one will disturb us here. What do you wanna say, Elvis?",
  ui_story_5031_50311301_66_dialog_content = "I just... I just want to say thank you, Jeno.",
  ui_story_5031_50311301_67_dialog_content = "... Huh? That came out of nowhere.",
  ui_story_5031_50311301_68_dialog_content = "For what?",
  ui_story_5031_50311301_69_dialog_content = "Thank you for accepting my invitation and giving the people of Harbor City such a wonderful memory.",
  ui_story_5031_50311301_70_dialog_content = "To me, your presence is... very significant.",
  ui_story_5031_50311301_71_dialog_content = "It's not a big deal. We wander everywhere, so it makes no difference where we work.",
  ui_story_5031_50311301_72_dialog_content = "Besides, you paid us more than enough. In that case, we should express our gratitude.",
  ui_story_5031_50311301_73_dialog_content = "No, Jeno.",
  ui_story_5031_50311301_74_dialog_content = "I can never repay you what I owe.",
  ui_story_5031_50311301_75_dialog_content = "Gratitude to me? What are you talking—",
  ui_story_5031_50311301_76_dialog_content = "Argh!",
  ui_story_5031_50311301_77_dialog_content = "I'm sorry.",
  ui_story_5031_50311301_78_dialog_content = "Cough, cough... Wh-What in the world...",
  ui_story_5031_50311301_79_dialog_content = "Is this...?",
  ui_story_5031_50311301_80_dialog_content = "Jeno... I'm so sorry.",
  ui_story_5031_50311301_81_dialog_content = "You mean Laird Elvis drugged you?",
  ui_story_5031_50311301_82_dialog_content = "Yeah.",
  ui_story_5031_50311301_83_dialog_content = "Wait, Elvis is a bad guy?",
  ui_story_5031_50311301_84_dialog_content = "Don't jump to conclusions, Fia. We don't know the truth yet.",
  ui_story_5031_50311301_85_dialog_content = "<size=33>Curses, it's gone...</size>",
  ui_story_5031_50311301_86_dialog_content = "What's wrong, Jeno? What are you looking for...",
  ui_story_5031_50311301_87_dialog_content = "Wow! What's happening?",
  ui_story_5031_50311301_88_dialog_content = "The ship... is rocking?",
  ui_story_5031_50311301_89_dialog_content = "... Never thought he'd stoop to this.",
  ui_story_5031_50311301_90_dialog_content = "Wait, Jeno!",
  ui_story_5031_50311301_91_dialog_content = "Je-Jeno... Huff, puff...",
  ui_story_5031_50311301_92_dialog_content = "Mind explaining what's going on?",
  ui_story_5031_50311301_93_dialog_content = "...",
  ui_story_5031_50311301_94_dialog_content = "I'm at my wit's end.",
  ui_story_5031_50311301_95_dialog_content = "If he manages to activate that THING, I'll need all of you to help.",
  ui_story_5031_50311301_96_dialog_content = "That thing?",
  ui_story_5031_50311301_97_dialog_content = "I just discovered the key to the ship's core chamber that I carried on me is missing.",
  ui_story_5031_50311301_98_dialog_content = "Is there anything important in that room?",
  ui_story_5031_50311301_99_dialog_content = "The <color=#FFB400>Energy Core</color>.",
  ui_story_5031_50311301_100_dialog_content = "Energy core?",
  ui_story_5031_50311301_101_dialog_content = "How come all of you look like you know exactly what that is?",
  ui_story_5031_50311301_102_dialog_content = "The energy core is a creation of ancient civilizations. Think of it as a precious resource.",
  ui_story_5031_50311301_103_dialog_content = "Never imagined there would be one on the ship...",
  ui_story_5031_50311301_104_dialog_content = "Because this ship originally came from an ancient ruin.",
  ui_story_5031_50311301_105_dialog_content = "And the THING I referred to is an ancient weapon guarding the energy core...",
  ui_story_5031_50311301_106_dialog_content = "<color=#FFB400>Core Guardian</color>.",
  ui_story_5031_50311301_107_dialog_content = "When the Core Guardian is activated, it will attack any life form approaching the energy core indiscriminately.",
  ui_story_5031_50311301_108_dialog_content = "That means the whole ship is in danger.",
  ui_story_5031_50311301_109_dialog_content = "So you're saying Laird Elvis took the key away when you passed out.",
  ui_story_5031_50311301_110_dialog_content = "And now he's entered the core chamber, trying to seize energy core?",
  ui_story_5031_50311301_111_dialog_content = "Most likely, but...",
  ui_story_5031_50311301_112_dialog_content = "Jeno!",
  ui_story_5031_50311301_113_dialog_content = "It's Rainbow and Ciel!",
  ui_story_5031_50311301_114_dialog_content = "Jeno, we just got the alert that the core chamber has been opened!",
  ui_story_5031_50311301_115_dialog_content = "I know. We're heading up there right now.",
  ui_story_5031_50311301_116_dialog_content = "On the way, we noticed the mercenary guards were also passed out...",
  ui_story_5031_50311301_117_dialog_content = "Watch out, Rainbow!",
  ui_story_5031_50311301_118_dialog_content = "Agh! That was close. Thanks, Ciel.",
  ui_story_5031_50311301_119_dialog_content = "Huh? These are... Harbor City Guards?",
  ui_story_5031_50311301_120_dialog_content = "They're assigned to delay us?",
  ui_story_5031_50311301_121_dialog_content = "...",
  ui_story_5031_50311301_122_dialog_content = "Get out of the way, you foolish servant!",
  ui_story_5031_50311302_1_dialog_content = "When did Elvis...",
  ui_story_5031_50311302_2_dialog_content = "Since when have these people entered the cabin?",
  ui_story_5031_50311302_3_dialog_content = "I can sense another flow of Lumina approaching!",
  ui_story_5031_50311302_4_dialog_content = "It's a lot more than we got here now...",
  ui_story_5031_50311302_5_dialog_content = "<color=#e8d9bb>BOOM!</color>",
  ui_story_5031_50311302_6_dialog_content = "Argh! My ship!",
  ui_story_5031_50311302_7_dialog_content = "What's that Elvis doing to my ship?!",
  ui_story_5031_50311302_8_dialog_content = "We could do nothing but get stuck here if this keeps up.",
  ui_story_5031_50311302_9_dialog_content = "Everyone's in a pickle...",
  ui_story_5031_50311302_10_dialog_content = "I got to do this!",
  ui_story_5031_50311302_11_dialog_content = "Arm mech status update—Type III.",
  ui_story_5031_50311302_12_dialog_content = "Leg mech status update—Type III.",
  ui_story_5031_50311302_13_dialog_content = "Increase energy output by 70%.",
  ui_story_5031_50311302_14_dialog_content = "What?",
  ui_story_5031_50311302_15_dialog_content = "What are you doing, Ciel? Your mecha is not fully tested yet!",
  ui_story_5031_50311302_16_dialog_content = "I'll keep them busy while you guys go to the core chamber.",
  ui_story_5031_50311302_17_dialog_content = "But...",
  ui_story_5031_50311302_18_dialog_content = "Don't worry!",
  ui_story_5031_50311302_19_dialog_content = "We did the calibrations together, you remember? Styx will be fine!",
  ui_story_5031_50311302_20_dialog_content = "Ciel's right, Rainbow.",
  ui_story_5031_50311302_21_dialog_content = "We can't spend too much time here.",
  ui_story_5031_50311302_22_dialog_content = "We must trust our companions... Leave this to Ciel.",
  ui_story_5031_50311302_23_dialog_content = "Carleen...",
  ui_story_5031_50311302_24_dialog_content = "(Carleen has indeed changed.)",
  ui_story_5031_50311302_25_dialog_content = "...",
  ui_story_5031_50311302_26_dialog_content = "Don't enjoy yourself too much and wreck the mecha, Ciel!",
  ui_story_5031_50311302_27_dialog_content = "Otherwise, you can never pay me back!",
  ui_story_5031_50311302_28_dialog_content = "H-Huh?!",
  ui_story_5031_50311302_29_dialog_content = "Okay, worry not.",
  ui_story_5031_50311302_30_dialog_content = "You got this, Ciel.",
  ui_story_5031_50311302_31_dialog_content = "Be careful, Ciel!",
  ui_story_5031_50311302_32_dialog_content = "We don't want to pick on a girl. You'd better run off now.",
  ui_story_5031_50311302_33_dialog_content = "I'm more than enough to take all of you on.",
  ui_story_5031_50311302_34_dialog_content = "Well, if that's how you want it.",
  ui_story_5031_50311302_35_dialog_content = "Hmm, they're tougher and have more people.",
  ui_story_5031_50311302_36_dialog_content = "In that case, I'll have to...",
  ui_story_5031_50311302_37_dialog_content = "Increase energy output by 80%.",
  ui_story_5031_50311302_38_dialog_content = "Gosh... Her firepower improved again?",
  ui_story_5031_50311302_39_dialog_content = "This mecha is like a monster.",
  ui_story_5031_50311302_40_dialog_content = "But for the laird, we shall not fall.",
  ui_story_5031_50311302_41_dialog_content = "Squad 1! Hold your formation and press with your Lumina shields!",
  ui_story_5031_50311302_42_dialog_content = "She's done if she's out of that mecha!",
  ui_story_5031_50311302_43_dialog_content = "Yes, sir!",
  ui_story_5031_50311302_44_dialog_content = "Their shields got more durable when stacked into one?",
  ui_story_5031_50311302_45_dialog_content = "Get ready for the Lumina guns, Squad 2!",
  ui_story_5031_50311302_46_dialog_content = "Oh, no, if I can't break this shield and let them get close...",
  ui_story_5031_50311302_47_dialog_content = "Okay, got to calm down, breathe...",
  ui_story_5031_50311302_48_dialog_content = "It might be harder, but Lumina is the key if it runs on energy.",
  ui_story_5031_50311302_49_dialog_content = "So I just have to release more Lumina than it does.",
  ui_story_5031_50311302_50_dialog_content = "But Styx was already down once today...",
  ui_story_5031_50311302_51_dialog_content = "If I increase the output, Styx might...",
  ui_story_5031_50311302_52_dialog_content = "I made up my mind. I'll help people a lot after I build a dynamic mecha!",
  ui_story_5031_50311302_53_dialog_content = "Oh? So what do you want to do the most with it, Ciel?",
  ui_story_5031_50311302_54_dialog_content = "Well, I think...",
  ui_story_5031_50311302_55_dialog_content = "I think...",
  ui_story_5031_50311302_56_dialog_content = "I'll help and protect my friends and be dependable!",
  ui_story_5031_50311302_57_dialog_content = "Sorry, Rainbow. Sorry, Styx!",
  ui_story_5031_50311302_58_dialog_content = "<size=45>Increase energy output by 100%!</size>",
  ui_story_5031_50311302_59_dialog_content = "Wh-What? The shield is broken! But how...",
  ui_story_5031_50311302_60_dialog_content = "She's got to be a monster!",
  ui_story_5031_50311302_61_dialog_content = "Huff... puff...",
  ui_story_5031_50311302_62_dialog_content = "Seems like that was quite a stretch...",
  ui_story_5031_50311302_63_dialog_content = "Not only are the leg circuits fizzing out, but the Lumina is also...",
  ui_story_5031_50311302_64_dialog_content = "Do not back down!",
  ui_story_5031_50311302_65_dialog_content = "It doesn't matter if the shield's gone. She only has so much energy!",
  ui_story_5031_50311302_66_dialog_content = "Can we just let one girl hold all of us back?!",
  ui_story_5031_50311302_67_dialog_content = "... Yes, sir!",
  ui_story_5031_50311302_68_dialog_content = "Huff... I won't let you pass...",
  ui_story_5031_50311302_69_dialog_content = "Her offense is waning. Now's the time!",
  ui_story_5031_50311302_70_dialog_content = "Still can't win despite your superiority of numbers. You sure you're Harbor City's finest?",
  ui_story_5031_50311302_71_dialog_content = "That sounds like...",
  ui_story_5031_50311302_72_dialog_content = "Ah!",
  ui_story_5031_50311302_73_dialog_content = "I-It's him!",
  ui_story_5031_50311302_74_dialog_content = "Phew, didn't I tell you not to enjoy yourself too much?",
  ui_story_5031_50311302_75_dialog_content = "Styx is looking worse for wear! Jeez, I just wasted a whole afternoon fixing it!",
  ui_story_5031_50311302_76_dialog_content = "It's you, Rainbow! Why are you back?",
  ui_story_5031_50311302_77_dialog_content = "Because I'm worried about you.",
  ui_story_5031_50311302_78_dialog_content = "But what about the core chamber?",
  ui_story_5031_50311302_79_dialog_content = "Jeno and the guys are on it.",
  ui_story_5031_50311302_80_dialog_content = "Tut, how dare you sneak attack me?",
  ui_story_5031_50311302_81_dialog_content = "Ugh!",
  ui_story_5031_50311302_82_dialog_content = "...",
  ui_story_5031_50311302_83_dialog_content = "Hmm? What's wrong, Ciel? Why do you look that way?",
  ui_story_5031_50311302_84_dialog_content = "... That makes sense.",
  ui_story_5031_50311302_85_dialog_content = "Someone embarrassing themselves like me has no right to talk about trust and dependability.",
  ui_story_5031_50311302_86_dialog_content = "If you didn't come back to me, I probably...",
  ui_story_5031_50311302_87_dialog_content = "...",
  ui_story_5031_50311302_88_dialog_content = "You are kind of silly sometimes, Ciel.",
  ui_story_5031_50311302_89_dialog_content = "What?",
  ui_story_5031_50311302_90_dialog_content = "But I like the silly you!",
  ui_story_5031_50311302_91_dialog_content = "I trust you, and that's why I know you'd put 100% effort into covering for us.",
  ui_story_5031_50311302_92_dialog_content = "But no one knows what condition Styx is in better than us. I'm aware of how it would end, and here I come.",
  ui_story_5031_50311302_93_dialog_content = "...",
  ui_story_5031_50311302_94_dialog_content = "I trust Jeno too, and I believe they will defend the Emerald.",
  ui_story_5031_50311302_95_dialog_content = "So rest assured.",
  ui_story_5031_50311302_96_dialog_content = "When it's all over, I'll spruce Styx up with you.",
  ui_story_5031_50311302_97_dialog_content = "We'll make it smart, robust, and not break down even at 300% output!",
  ui_story_5031_50311302_98_dialog_content = "... Okay.",
  ui_story_5031_50311302_99_dialog_content = "But we have to get rid of these nuisances first.",
  ui_story_5031_50311302_100_dialog_content = "Come on. You launch sneak attacks even when you are vastly outnumbering us.",
  ui_story_5031_50311302_101_dialog_content = "Have you no shame?",
  ui_story_5031_50311302_102_dialog_content = "...",
  ui_story_5031_50311401_1_dialog_content = "*Cough*",
  ui_story_5031_50311401_2_dialog_content = "Well, all set to go now.",
  ui_story_5031_50311401_3_dialog_content = "Just waiting for the last piece to fall into place.",
  ui_story_5031_50311401_4_dialog_content = "Footsteps approaching, sir.",
  ui_story_5031_50311401_5_dialog_content = "All right, let them come. You should leave the ship according to plan and stop anyone else from coming near.",
  ui_story_5031_50311401_6_dialog_content = "...",
  ui_story_5031_50311401_7_dialog_content = "What's the matter?",
  ui_story_5031_50311401_8_dialog_content = "Are you sure, sir?",
  ui_story_5031_50311401_9_dialog_content = "I shouldn't leave you by yourself...",
  ui_story_5031_50311401_10_dialog_content = "You did your job. I must face what's next alone.",
  ui_story_5031_50311401_11_dialog_content = "...",
  ui_story_5031_50311401_12_dialog_content = "Or do you not believe me, Patou?",
  ui_story_5031_50311401_13_dialog_content = "I certainly believe in you! You know that's not what I meant.",
  ui_story_5031_50311401_14_dialog_content = "If you do, leave now. You'll only foul up the plan by staying here.",
  ui_story_5031_50311401_15_dialog_content = "Worry not. Everything's under my control thus far.",
  ui_story_5031_50311401_16_dialog_content = "Remember what I said... Do not come in no matter what you hear.",
  ui_story_5031_50311401_17_dialog_content = "... Yes.",
  ui_story_5031_50311401_18_dialog_content = "Please take care.",
  ui_story_5031_50311401_19_dialog_content = "Elvis!",
  ui_story_5031_50311401_20_dialog_content = "Oh? It's not Rainbow and Ciel but Her Highness and you guys?",
  ui_story_5031_50311401_21_dialog_content = "But that's all right. You're only a bit later than I thought.",
  ui_story_5031_50311401_22_dialog_content = "Everything was ready but you still didn't show up, so I was concerned if those men actually stopped you.",
  ui_story_5031_50311401_23_dialog_content = "Is he expecting us from the way he talked...?",
  ui_story_5031_50311401_24_dialog_content = "I don't see Patou. I wonder what's up his sleeve.",
  ui_story_5031_50311401_25_dialog_content = "Regardless, let's be careful.",
  ui_story_5031_50311401_26_dialog_content = "Yeah.",
  ui_story_5031_50311401_27_dialog_content = "Is that... the energy core next to him?",
  ui_story_5031_50311401_28_dialog_content = "It should be. I can sense strong, unusual energy from it.",
  ui_story_5031_50311401_29_dialog_content = "But how is he going to take something that big with him?",
  ui_story_5031_50311401_30_dialog_content = "Listen to me, Elvis.",
  ui_story_5031_50311401_31_dialog_content = "I don't know what you planned to do with the energy core.",
  ui_story_5031_50311401_32_dialog_content = "But I know your ultimate goal is to protect the people of Harbor City from Modali Syndrome.",
  ui_story_5031_50311401_33_dialog_content = "What you're doing now, however, will only endanger the city.",
  ui_story_5031_50311401_34_dialog_content = "When the energy core goes out of its normal mode, it will wake...",
  ui_story_5031_50311401_35_dialog_content = "Its Guardian.",
  ui_story_5031_50311401_36_dialog_content = "...",
  ui_story_5031_50311401_37_dialog_content = "You know about that?",
  ui_story_5031_50311401_38_dialog_content = "You'll find the information you need too, once you've perused every book in this world.",
  ui_story_5031_50311401_39_dialog_content = "Robotic weapon: Core Guardian.",
  ui_story_5031_50311401_40_dialog_content = "A product of ancient civilizations, with sufficient power to destroy a small city.",
  ui_story_5031_50311401_41_dialog_content = "When the energy core glitches, the Core Guardian is activated.",
  ui_story_5031_50311401_42_dialog_content = "If this operation continues, it will not only cause the Guardian to attack but may result in the core's self-destruction.",
  ui_story_5031_50311401_43_dialog_content = "That's why you True Order people could never get your hands on this energy core, right?",
  ui_story_5031_50311401_44_dialog_content = "...",
  ui_story_5031_50311401_45_dialog_content = "True Order...?",
  ui_story_5031_50311401_46_dialog_content = "You're with True Order, Jeno?",
  ui_story_5031_50311401_47_dialog_content = "... It's a long story. My understanding of the core indeed came from The True Order, but that's not important.",
  ui_story_5031_50311401_48_dialog_content = "Let's set the matter with Jeno and True Order aside for now.",
  ui_story_5031_50311401_49_dialog_content = "If you know so much about it, Elvis, why would you still do something that could imperil the people of Harbor City?",
  ui_story_5031_50311401_50_dialog_content = "Imperil the people of Harbor City?",
  ui_story_5031_50311401_51_dialog_content = "No, no, Your Highness, I'm not like those pampered old nobles in Lumopolis.",
  ui_story_5031_50311401_52_dialog_content = "I'd never play around with the lives of my people.",
  ui_story_5031_50311401_53_dialog_content = "I got my reasons for doing this.",
  ui_story_5031_50311401_54_dialog_content = "But I don't think you'll ever get to find out.",
  ui_story_5031_50311401_55_dialog_content = "<color=#e8d9bb>Buzz!</color>",
  ui_story_5031_50311401_56_dialog_content = "What's that noise? So loud and annoying!",
  ui_story_5031_50311401_57_dialog_content = "Yikes... What did you do, Elvis?",
  ui_story_5031_50311401_58_dialog_content = "Since all the guests are present, I can get the show on the road.",
  ui_story_5031_50311401_59_dialog_content = "I admire your character, Your Highness, but I'm more inclined to do anything for Harbor City's future.",
  ui_story_5031_50311401_60_dialog_content = "If you want to hold a grudge, let it be for me only.",
  ui_story_5031_50311401_61_dialog_content = "The seal is not stable anymore, so I must save the city any way I can.",
  ui_story_5031_50311401_62_dialog_content = "Look, the gem on his scepter is glowing!",
  ui_story_5031_50311401_63_dialog_content = "That gem...",
  ui_story_5031_50311401_64_dialog_content = "It's absorbing energy from the core!",
  ui_story_5031_50311401_65_dialog_content = "Ah, you could even sense that, Caelestite?",
  ui_story_5031_50311401_66_dialog_content = "Well, I guess that means I can't leave any of you alive.",
  ui_story_5031_50311401_67_dialog_content = "But I was planning to, anyway.",
  ui_story_5031_50311401_68_dialog_content = "\"Unusual activity detected.\"",
  ui_story_5031_50311401_69_dialog_content = "\"Auto-defense activated. Undergoing system analysis.\"",
  ui_story_5031_50311401_70_dialog_content = "Hey, that huge robot hanging below that big block is moving!",
  ui_story_5031_50311401_71_dialog_content = "Aw, the worst has happened.",
  ui_story_5031_50311401_72_dialog_content = "The Core Guardian is about to be awakened...",
  ui_story_5031_50311401_73_dialog_content = "Watch out, you guys.",
  ui_story_5031_50311401_74_dialog_content = "\"Energy Identification: Lumina.\"",
  ui_story_5031_50311401_75_dialog_content = "\"Analysis: Hostile targets.\"",
  ui_story_5031_50311401_76_dialog_content = "\"Conclusion: Initiate attack mode.\"",
  ui_story_5031_50311401_77_dialog_content = "Its energy is amplifying!",
  ui_story_5031_50311401_78_dialog_content = "Get behind me, Fia!",
  ui_story_5031_50311401_79_dialog_content = "Oh, okay!",
  ui_story_5031_50311402_1_dialog_content = "Vice, Jeno, I'll attack from the left rear.",
  ui_story_5031_50311402_2_dialog_content = "I need you to hold off the Core Guardian's advance!",
  ui_story_5031_50311402_3_dialog_content = "Got it!",
  ui_story_5031_50311402_4_dialog_content = "Watch out for the cluster of energy in its right arm, Vice!",
  ui_story_5031_50311402_5_dialog_content = "It's about to attack!",
  ui_story_5031_50311402_6_dialog_content = "Okay, got it!",
  ui_story_5031_50311402_7_dialog_content = "Ice Blossom!",
  ui_story_5031_50311402_8_dialog_content = "\"Hull struck.\"",
  ui_story_5031_50311402_9_dialog_content = "\"Begin assessing the damage.\"",
  ui_story_5031_50311402_10_dialog_content = "Wow, the big robot isn't moving!",
  ui_story_5031_50311402_11_dialog_content = "You're awesome, Carleen!",
  ui_story_5031_50311402_12_dialog_content = "Not quite. Its energy is still running normally inside it.",
  ui_story_5031_50311402_13_dialog_content = "You're very competent, even exceeding my anticipation.",
  ui_story_5031_50311402_14_dialog_content = "Although I've heard a lot about what PlayerName can do but seeing is believing.",
  ui_story_5031_50311402_15_dialog_content = "It's a shame, however...",
  ui_story_5031_50311402_16_dialog_content = "That your effort shall be for naught.",
  ui_story_5031_50311402_17_dialog_content = "\"Assessment complete, no serious damage.\"",
  ui_story_5031_50311402_18_dialog_content = "\"Update enemy data, adjust damage output.\"",
  ui_story_5031_50311402_19_dialog_content = "What is this...?",
  ui_story_5031_50311402_20_dialog_content = "Carleen, it's gathering massive energy at the chest. Duck!",
  ui_story_5031_50311402_21_dialog_content = "Ugh!",
  ui_story_5031_50311402_22_dialog_content = "That was close.",
  ui_story_5031_50311402_23_dialog_content = "Are you all right, Carleen?",
  ui_story_5031_50311402_24_dialog_content = "I'm okay. Thanks to PlayerName's warning, it's just a scratch.",
  ui_story_5031_50311402_25_dialog_content = "Good, because the power it just unleashed is horrifying...",
  ui_story_5031_50311402_26_dialog_content = "Half of the walls in the room got melted.",
  ui_story_5031_50311402_27_dialog_content = "The power of ancient civilizations weapons is indeed fearsome.",
  ui_story_5031_50311402_28_dialog_content = "Let's surround it and find a weak spot.",
  ui_story_5031_50311402_29_dialog_content = "Yeah. You be careful too.",
  ui_story_5031_50311402_30_dialog_content = "You know, have you noticed something strange?",
  ui_story_5031_50311402_31_dialog_content = "What is it?",
  ui_story_5031_50311402_32_dialog_content = "Why is the Guardian only attacking us?",
  ui_story_5031_50311402_33_dialog_content = "Elvis is obviously standing right next to the core and siphoning its energy.",
  ui_story_5031_50311402_34_dialog_content = "That's true.",
  ui_story_5031_50311402_35_dialog_content = "Because the Guardian...",
  ui_story_5031_50311402_36_dialog_content = "...",
  ui_story_5031_50311402_37_dialog_content = "Do you know why, Jeno?",
  ui_story_5031_50311402_38_dialog_content = "No, nothing.",
  ui_story_5031_50311402_39_dialog_content = "Why did you not finish what you were saying?",
  ui_story_5031_50311402_40_dialog_content = "You still care about my feelings even now?",
  ui_story_5031_50311402_41_dialog_content = "Still the same you, Jeno.",
  ui_story_5031_50311402_42_dialog_content = "It's okay. I'm used to it already, you can spit it out.",
  ui_story_5031_50311402_43_dialog_content = "Elvis...",
  ui_story_5031_50311402_44_dialog_content = "Tell them it's because the Guardian recognizes enemies through Lumina.",
  ui_story_5031_50311402_45_dialog_content = "But for me, with all my Lumina absorbed...",
  ui_story_5031_50311402_46_dialog_content = "I'm nothing more than a dead body.",
  ui_story_5031_50311402_47_dialog_content = "L-Lumina absorbed?",
  ui_story_5031_50311402_48_dialog_content = "That explains why I couldn't sense Lumina on Elvis.",
  ui_story_5031_50311402_49_dialog_content = "I thought that was because of his illness.",
  ui_story_5031_50311402_50_dialog_content = "It's the other way around. Losing Lumina led to the illness.",
  ui_story_5031_50311402_51_dialog_content = "Modali Syndrome is actually a disease resulting from the loss of Lumina over a long period of time.",
  ui_story_5031_50311402_52_dialog_content = "The victims live with the pain of Lumina constantly leaving their bodies. Severe cases would even...",
  ui_story_5031_50311402_53_dialog_content = "So, the solution is to get the energy core?",
  ui_story_5031_50311402_54_dialog_content = "I'm not sure the specifics, but that's the gist of his plan.",
  ui_story_5031_50311402_55_dialog_content = "Listen to me, Elvis.",
  ui_story_5031_50311402_56_dialog_content = "Even if you get the energy core, you can't control the Guardian.",
  ui_story_5031_50311402_57_dialog_content = "After we go down, it will turn its attention to you and Harbor City.",
  ui_story_5031_50311402_58_dialog_content = "There has to be another way. We can...",
  ui_story_5031_50311402_59_dialog_content = "There is no other way, Jeno.",
  ui_story_5031_50311402_60_dialog_content = "I've been searching for a solution ever since I first witnessed my people dying from the disease.",
  ui_story_5031_50311402_61_dialog_content = "I tried every option possible over the years, even when the chances of success were slim to none.",
  ui_story_5031_50311402_62_dialog_content = "But all that's left with is disappointment and a declining body.",
  ui_story_5031_50311402_63_dialog_content = "I must finish it even though time's run out on me.",
  ui_story_5031_50311402_64_dialog_content = "But...",
  ui_story_5031_50311402_65_dialog_content = "Quit talking, Jeno. The Guardian's coming your way!",
  ui_story_5031_50311402_66_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5031_50311402_67_dialog_content = "Jeno!",
  ui_story_5031_50311402_68_dialog_content = "Cough, cough.",
  ui_story_5031_50311402_69_dialog_content = "I'm fine...",
  ui_story_5031_50311402_70_dialog_content = "Thank goodness, that scared the wits out of me...",
  ui_story_5031_50311402_71_dialog_content = "That's low, Elvis!",
  ui_story_5031_50311402_72_dialog_content = "You distracted Jeno under the pretense of a talk!",
  ui_story_5031_50311402_73_dialog_content = "No, you misunderstood, Miss Fia.",
  ui_story_5031_50311402_74_dialog_content = "That's not my intention. On the contrary, I need all of you...",
  ui_story_5031_50311402_75_dialog_content = "You need us to keep the Guardian occupied while you absorb the energy, right?",
  ui_story_5031_50311402_76_dialog_content = "Very astute of you, Your Highness.",
  ui_story_5031_50311402_77_dialog_content = "As for the Core Guardian, I can reveal some information given you're so worried about the people of Harbor City.",
  ui_story_5031_50311402_78_dialog_content = "The difference between True Order and me is I have something they don't.",
  ui_story_5031_50311402_79_dialog_content = "I can bind the energy core to my blood and control it.",
  ui_story_5031_50311402_80_dialog_content = "Once I finish absorbing the energy core, the Guardian will obey me as well.",
  ui_story_5031_50311402_81_dialog_content = "Thus, you can rest in peace with this ship on the ocean floor, knowing my people are safe.",
  ui_story_5031_50311402_82_dialog_content = "You've made up your mind to kill us then, Laird Elvis.",
  ui_story_5031_50311402_83_dialog_content = "I'm sorry, but I can't risk the Elder Council finding this out.",
  ui_story_5031_50311402_84_dialog_content = "Well, I guess we got nothing more to discuss.",
  ui_story_5031_50311402_85_dialog_content = "But whether you meant well, I won't let you hurt my friends.",
  ui_story_5031_50311402_86_dialog_content = "Jeno, the illusions you conjure carried your Lumina, right?",
  ui_story_5031_50311402_87_dialog_content = "Yes.",
  ui_story_5031_50311402_88_dialog_content = "How many images of the soldiers can you project?",
  ui_story_5031_50311402_89_dialog_content = "I could probably control more than ten at the same time.",
  ui_story_5031_50311402_90_dialog_content = "You got a plan, Carleen?",
  ui_story_5031_50311402_91_dialog_content = "I'd like you, Vice, and Jeno, to keep the Guardian busy for me.",
  ui_story_5031_50311402_92_dialog_content = "Returning the energy core back to normal is the prerequisite to deactivating the Guardian.",
  ui_story_5031_50311402_93_dialog_content = "That should clarify our objective.",
  ui_story_5031_50311402_94_dialog_content = "I'll stop Elvis from absorbing the energy core.",
  ui_story_5031_50311501_1_dialog_content = "Rapid Torrent!",
  ui_story_5031_50311501_2_dialog_content = "Okay, we've got the Guardian's attention.",
  ui_story_5031_50311501_3_dialog_content = "Now, Carleen!",
  ui_story_5031_50311501_4_dialog_content = "Make it quick. I can't keep all these illusions up for long.",
  ui_story_5031_50311501_5_dialog_content = "All right, thanks!",
  ui_story_5031_50311501_6_dialog_content = "Cough, cough...",
  ui_story_5031_50311501_7_dialog_content = "I wouldn't expect anything less from you, Lady Carleen.",
  ui_story_5031_50311501_8_dialog_content = "Not even knowing Jeno a day and still figured out how to use his power to distract the Guardian.",
  ui_story_5031_50311501_9_dialog_content = "A highly tactical mind, coupled with PlayerName's abilities...",
  ui_story_5031_50311501_10_dialog_content = "I'm glad I never underestimated you from the beginning.",
  ui_story_5031_50311501_11_dialog_content = "Ugh!",
  ui_story_5031_50311501_12_dialog_content = "What's wrong, Carleen?!",
  ui_story_5031_50311501_13_dialog_content = "I... can't... move...",
  ui_story_5031_50311501_14_dialog_content = "My power's draining...",
  ui_story_5031_50311501_15_dialog_content = "Stay here and don't go anywhere, Fia!",
  ui_story_5031_50311501_16_dialog_content = "But that robot is going to kill you, PlayerName!",
  ui_story_5031_50311501_17_dialog_content = "Hey, how come the robot didn't react at all?",
  ui_story_5031_50311501_18_dialog_content = "Carleen!",
  ui_story_5031_50311501_19_dialog_content = "PlayerName...",
  ui_story_5031_50311501_20_dialog_content = "(The Lumina in Carleen is draining fast!)",
  ui_story_5031_50311501_21_dialog_content = "Drat...",
  ui_story_5031_50311501_22_dialog_content = "<size=45>What have you done, Elvis?!</size>",
  ui_story_5031_50311501_23_dialog_content = "Doesn't feel good to have Lumina taken out of you, does it?",
  ui_story_5031_50311501_24_dialog_content = "As a contingency, I put a <color=#FFB400>safety precaution</color> on Her Highness.",
  ui_story_5031_50311501_25_dialog_content = "Safety precaution? When?",
  ui_story_5031_50311501_26_dialog_content = "Is it the outfit she's wearing?",
  ui_story_5031_50311501_27_dialog_content = "Correct.",
  ui_story_5031_50311501_28_dialog_content = "When you asked me how to get into the cabin, I knew it might come to this.",
  ui_story_5031_50311501_29_dialog_content = "The outfit on her was specially designed.",
  ui_story_5031_50311501_30_dialog_content = "A material like <color=#FFB400>Lumothread</color> will adhere to the wearer when activated and absorb Lumina quickly.",
  ui_story_5031_50311501_31_dialog_content = "Therefore, she is better off not using Lumina at all.",
  ui_story_5031_50311501_32_dialog_content = "Why you...!",
  ui_story_5031_50311501_33_dialog_content = "I'm sorry... I underestimated him...",
  ui_story_5031_50311501_34_dialog_content = "It's not your fault. You should...",
  ui_story_5031_50311501_35_dialog_content = "Watch out, Jeno!",
  ui_story_5031_50311501_36_dialog_content = "Huh!?",
  ui_story_5031_50311501_37_dialog_content = "Are you okay, Jeno?",
  ui_story_5031_50311501_38_dialog_content = "Ouch! My arm...",
  ui_story_5031_50311501_39_dialog_content = "I can't move it.",
  ui_story_5031_50311501_40_dialog_content = "Don't move. You're bleeding!",
  ui_story_5031_50311501_41_dialog_content = "\"Enemy injured. Pursuit mode engaged.\"",
  ui_story_5031_50311501_42_dialog_content = "The Guardian is charging toward you, Vice!",
  ui_story_5031_50311501_43_dialog_content = "Oh no, it's way too fast!",
  ui_story_5031_50311501_44_dialog_content = "It's too late for me to shoot!",
  ui_story_5031_50311501_45_dialog_content = "Stop... Ugh!",
  ui_story_5031_50311501_46_dialog_content = "J-Jeno?",
  ui_story_5031_50311501_47_dialog_content = "...",
  ui_story_5031_50311501_48_dialog_content = "He passed out.",
  ui_story_5031_50311501_49_dialog_content = "Oh no, what are we going to do now?",
  ui_story_5031_50311501_50_dialog_content = "Oh yeah, I still got this!",
  ui_story_5031_50311501_51_dialog_content = "<color=#e8d9bb>Bang, bang!</color>",
  ui_story_5031_50311501_52_dialog_content = "\"?\"",
  ui_story_5031_50311501_53_dialog_content = "Gotcha! Luckily I still got the gun master gave me!",
  ui_story_5031_50311501_54_dialog_content = "How do you like that, robot?",
  ui_story_5031_50311501_55_dialog_content = "\"Under unknown attack, damage suffered: 0.\"",
  ui_story_5031_50311501_56_dialog_content = "\"Target spent no Lumina. Analysis: Priority elimination.\"",
  ui_story_5031_50311501_57_dialog_content = "Waaah! Why is it charging me now?!",
  ui_story_5031_50311501_58_dialog_content = "Aaaah!",
  ui_story_5031_50311501_59_dialog_content = "Fia!",
  ui_story_5031_50311501_60_dialog_content = "...",
  ui_story_5031_50311501_61_dialog_content = "We're done for if this keeps up.",
  ui_story_5031_50311501_62_dialog_content = "I'm the only one left now, so don't panic.",
  ui_story_5031_50311501_63_dialog_content = "I have to stop Elvis first to stop the Guardian.",
  ui_story_5031_50311501_64_dialog_content = "...",
  ui_story_5031_50311501_65_dialog_content = "Lie down for a bit, Carleen, and don't use Lumina again.",
  ui_story_5031_50311501_66_dialog_content = "What are you up to, PlayerName?",
  ui_story_5031_50311501_67_dialog_content = "I'm going to stop Elvis.",
  ui_story_5031_50311501_68_dialog_content = "I guess it's time I put the training from Sinsa and others to good use.",
  ui_story_5031_50311501_69_dialog_content = "But...",
  ui_story_5031_50311501_70_dialog_content = "Relax, Carleen.",
  ui_story_5031_50311501_71_dialog_content = "I might not have Lumina, but against a sickly man like Elvis...",
  ui_story_5031_50311501_72_dialog_content = "I won't lose.",
  ui_story_5031_50311501_73_dialog_content = "Be very careful.",
  ui_story_5031_50311501_74_dialog_content = "Very stirring speech. Impressive.",
  ui_story_5031_50311501_75_dialog_content = "But calling someone a sickly man is incredibly rude.",
  ui_story_5031_50311501_76_dialog_content = "Cut the nonsense.",
  ui_story_5031_50311501_77_dialog_content = "Shut up and—",
  ui_story_5031_50311501_78_dialog_content = "Go down!",
  ui_story_5031_50311501_79_dialog_content = "Heh.",
  ui_story_5031_50311501_80_dialog_content = "<size=45>PlayerName! Watch out!</size>",
  ui_story_5031_50311501_81_dialog_content = "\"Switching command priority, overwriting default command. Switch target.\"",
  ui_story_5031_50311501_82_dialog_content = "Ugh!!",
  ui_story_5031_50311501_83_dialog_content = "PlayerName!",
  ui_story_5031_50311501_84_dialog_content = "No way...",
  ui_story_5031_50311501_85_dialog_content = "This is impossible...",
  ui_story_5031_50311501_86_dialog_content = "You came so close, PlayerName.",
  ui_story_5031_50311501_87_dialog_content = "Too bad I've absorbed all the energy from the core.",
  ui_story_5031_50311501_88_dialog_content = "Now, I am in control of the Core Guardian.",
  ui_story_5031_50311501_89_dialog_content = "Otherwise, someone without Lumina like you would really be a nuisance.",
  ui_story_5031_50311501_90_dialog_content = "\"Highest priority command updated, switched to manual control mode.\"",
  ui_story_5031_50311501_91_dialog_content = "\"Auto-defense system shut off.\"",
  ui_story_5031_50311501_92_dialog_content = "(That hurts!)",
  ui_story_5031_50311501_93_dialog_content = "(I can't feel my legs.)",
  ui_story_5031_50311501_94_dialog_content = "Let me see, the only one left who can still move is...",
  ui_story_5031_50311501_95_dialog_content = "Miss Vice, I guess.",
  ui_story_5031_50311501_96_dialog_content = "Go finish her, and then we'll head for the next location.",
  ui_story_5031_50311501_97_dialog_content = "\"New command received. Switching target.\"",
  ui_story_5031_50311501_98_dialog_content = "(No, Vice!)",
  ui_story_5031_50311501_99_dialog_content = "<size=33>Run, Vice...</size>",
  ui_story_5031_50311501_100_dialog_content = "Oh? Still able to stand, huh?",
  ui_story_5031_50311501_101_dialog_content = "<size=33>Huh?</size>",
  ui_story_5031_50311501_102_dialog_content = "I respect you, for still being capable of such strength in these circumstances.",
  ui_story_5031_50311501_103_dialog_content = "However—and do forgive me for my bluntness—this will only accelerate your demise.",
  ui_story_5031_50311501_104_dialog_content = "<size=33>Carleen...?</size>",
  ui_story_5031_50311501_105_dialog_content = "It's all because of me...",
  ui_story_5031_50311501_106_dialog_content = "Your Highness?",
  ui_story_5031_50311501_107_dialog_content = "It's all... because of me...",
  ui_story_5031_50311501_108_dialog_content = "Ah, she's delirious from losing Lumina...",
  ui_story_5031_50311501_109_dialog_content = "Very commendable how you're still trying to protect your friends when you're in such a sorry state.",
  ui_story_5031_50311501_110_dialog_content = "\"New target detected. Commence attack?\"",
  ui_story_5031_50311501_111_dialog_content = "No need. She's no threat.",
  ui_story_5031_50311501_112_dialog_content = "<size=45>Stop it, Carleen!</size>",
  ui_story_5031_50311501_113_dialog_content = "(Drat, I can't even make a sound.)",
  ui_story_5031_50311501_114_dialog_content = "(I've gotta do something...)",
  ui_story_5031_50311501_115_option_content = "Forced Control!",
  ui_story_5031_50311501_116_dialog_content = "What are you prepared to do if one day, your city comes under Eclipsite attack?",
  ui_story_5031_50311501_117_dialog_content = "(Is that... Schwartz?)",
  ui_story_5031_50311501_118_dialog_content = "(Is this a dream? Is it because Carleen is about to lose consciousness?)",
  ui_story_5031_50311501_119_dialog_content = "I'd immediately assemble an army to defend it.",
  ui_story_5031_50311501_120_dialog_content = "And if an Eclipsite force makes it through your defense?",
  ui_story_5031_50311501_121_dialog_content = "I'd rush over with reserve troops.",
  ui_story_5031_50311501_122_dialog_content = "And then Eclipsites who've been digging a tunnel underground emerge in the city center.",
  ui_story_5031_50311501_123_dialog_content = "I'd order the soldiers to hold their ground, and then I—",
  ui_story_5031_50311501_124_dialog_content = "Now the rampart is starting to fall.",
  ui_story_5031_50311501_125_dialog_content = "...",
  ui_story_5031_50311501_126_dialog_content = "I-I'd defeat all the Eclipsites.",
  ui_story_5031_50311501_127_dialog_content = "You and I both know they cannot be wiped out.",
  ui_story_5031_50311501_128_dialog_content = "...",
  ui_story_5031_50311501_129_dialog_content = "It seems to me you're still far off from becoming an excellent ruler...",
  ui_story_5031_50311501_130_dialog_content = "Lumopolis cannot depend on you yet.",
  ui_story_5031_50311501_131_dialog_content = "F-Father?",
  ui_story_5031_50311501_132_dialog_content = "I sent you to Northland to study under Bethlehem, but I see no evidence of progress.",
  ui_story_5031_50311501_133_dialog_content = "Your strength is insufficient and you lack mind power.",
  ui_story_5031_50311501_134_dialog_content = "That's why you lost your friends.",
  ui_story_5031_50311501_135_dialog_content = "They got hurt, even died, all because of you, Your Highness.",
  ui_story_5031_50311501_136_dialog_content = "I, I...",
  ui_story_5031_50311501_137_dialog_content = "I trusted you, and I followed your battle plan, Carleen.",
  ui_story_5031_50311501_138_dialog_content = "But what did that get me?",
  ui_story_5031_50311501_139_dialog_content = "PlayerName and I are about to die because of you.",
  ui_story_5031_50311501_140_dialog_content = "I'm sorry, Vice...",
  ui_story_5031_50311501_141_dialog_content = "Focus, Carleen, that's not Vice!",
  ui_story_5031_50311501_142_dialog_content = "Is that...",
  ui_story_5031_50311501_143_dialog_content = "PlayerName?",
  ui_story_5031_50311501_144_dialog_content = "Yes, it's me!",
  ui_story_5031_50311501_145_dialog_content = "I'm sorry for never noticing how much internal conflict you were experiencing, Carleen.",
  ui_story_5031_50311501_146_dialog_content = "But Vice would never say that. What you're seeing isn't real but illusions!",
  ui_story_5031_50311501_147_dialog_content = "Are you trying to run from your responsibilities?",
  ui_story_5031_50311501_148_dialog_content = "What a pity. Keep spouting how you will protect others when you're actually weak.",
  ui_story_5031_50311501_149_dialog_content = "You're not cut out to rule.",
  ui_story_5031_50311501_150_dialog_content = "I...",
  ui_story_5031_50311501_151_dialog_content = "Listen to me, Carleen.",
  ui_story_5031_50311501_152_dialog_content = "You don't have to bear the weight of being a ruler all the time!",
  ui_story_5031_50311501_153_dialog_content = "To me and Vice, you're Carleen and only Carleen!",
  ui_story_5031_50311501_154_dialog_content = "Mm?",
  ui_story_5031_50311501_154X1_dialog_content = "Do you remember that thing Vice said, Carleen?",
  ui_story_5031_50311501_154X2_dialog_content = "You must not give in to your obsession!",
  ui_story_5031_50311501_154X3_dialog_content = "My obsession...",
  ui_story_5031_50311501_154X4_dialog_content = "I was in such a slumber during the process. I thought I'd never wake up.",
  ui_story_5031_50311501_154X5_dialog_content = "I kept holding fast to the image of the old me, afraid I'd lose myself if I relaxed even for a second.",
  ui_story_5031_50311501_154X6_dialog_content = "I saw a lot of marvelous things, too, I experienced them as if I was there.",
  ui_story_5031_50311501_154X7_dialog_content = "Those illusions felt so real, like a test for me.",
  ui_story_5031_50311501_154X8_dialog_content = "Luckily, I clung to a gleam of consciousness and preserved to the end.",
  ui_story_5031_50311501_154X9_dialog_content = "Gleam? I remember you mentioned it. What was it?",
  ui_story_5031_50311501_154X10_dialog_content = "Um... I thought about the fun stuff I did with you and PlayerName.",
  ui_story_5031_50311501_154X11_dialog_content = "And before I knew it, there was silence inside me.",
  ui_story_5031_50311501_154X12_dialog_content = "Yes, Carleen, don't give up and don't lose yourself!",
  ui_story_5031_50311501_155_dialog_content = "We fight together and retreat together.",
  ui_story_5031_50311501_156_dialog_content = "We'll always have each other's backs.",
  ui_story_5031_50311501_157_dialog_content = "We don't hold you responsible when we're in trouble.",
  ui_story_5031_50311501_158_dialog_content = "You don't have to protect us all on your own.",
  ui_story_5031_50311501_159_dialog_content = "We should be working as a team and facing problems as a team!",
  ui_story_5031_50311501_160_dialog_content = "PlayerName...",
  ui_story_5031_50311501_161_dialog_content = "Whatever happens, Vice and I would never EVER blame you!",
  ui_story_5031_50311501_162_dialog_content = "So pull yourself together, Carleen! Don't be misled by the illusions!",
  ui_story_5031_50311501_163_dialog_content = "The real Vice didn't give up and is still fighting for us.",
  ui_story_5031_50311501_164_dialog_content = "She needs you!",
  ui_story_5031_50311501_165_dialog_content = "...",
  ui_story_5031_50311501_166_dialog_content = "You're right, PlayerName.",
  ui_story_5031_50311501_167_dialog_content = "My friends are still fighting, how can I waste time getting down on myself?",
  ui_story_5031_50311501_168_dialog_content = "So, you're just going to overlook the mistake you made?",
  ui_story_5031_50311501_169_dialog_content = "It's obvious that your underestimation and incompetence...",
  ui_story_5031_50311501_170_dialog_content = "Led to the current predicament.",
  ui_story_5031_50311501_171_dialog_content = "Yes, but I won't be a prisoner of my own decisions, right or wrong.",
  ui_story_5031_50311501_172_dialog_content = "...",
  ui_story_5031_50311501_173_dialog_content = "Because that's meaningless. If I make a mistake...",
  ui_story_5031_50311501_174_dialog_content = "I'll endeavor to rectify it.",
  ui_story_5031_50311501_175_dialog_content = "If that's how you defined the \"way of the ruler\"...",
  ui_story_5031_50311501_176_dialog_content = "I hope you'll remain adamant in that belief.",
  ui_story_5031_50311501_176X1_dialog_content = "I will.",
  ui_story_5031_50311501_176X2_dialog_content = "Because I...",
  ui_story_5031_50311501_176X3_dialog_content = "I've found that something I can hold on to.",
  ui_story_5031_50311501_177_dialog_content = "Ah, the image is—",
  ui_story_5031_50311501_178_dialog_content = "Sorry to keep you waiting, Vice.",
  ui_story_5031_50311501_179_dialog_content = "Carleen!",
  ui_story_5031_50311501_180_dialog_content = "\"Warning: Massive Lumina detected, threat level high.\"",
  ui_story_5031_50311501_181_dialog_content = "\"Eliminate target immediately.\"",
  ui_story_5031_50311501_182_dialog_content = "Splendid Glow!",
  ui_story_5031_50311501_183_dialog_content = "How is this possible?",
  ui_story_5031_50311501_184_dialog_content = "But the <color=#FFB400>Lumothread</color> is still absorbing her Lumina?!",
  ui_story_5031_50311501_185_dialog_content = "Carleen is bathing in Lumina!",
  ui_story_5031_50311501_186_dialog_content = "What is going on here?",
  ui_story_5031_50311501_187_dialog_content = "Unnecessary self-doubt and anxiety will only serve to detract.",
  ui_story_5031_50311501_188_dialog_content = "A battle is ever-changing. One must focus on what's unfolding, not internal fear.",
  ui_story_5031_50311501_189_dialog_content = "I'll now fight the battle with you, Vice.",
  ui_story_5031_50311501_190_dialog_content = "Are you okay physically, Carleen?",
  ui_story_5031_50311501_191_dialog_content = "I don't know why, but I'm feeling nonstop energy.",
  ui_story_5031_50311501_192_dialog_content = "Regardless, I have but one objective right now...",
  ui_story_5031_50311501_193_dialog_content = "And that is to defeat the enemy with you.",
  ui_story_5031_50311501_194_dialog_content = "Right!",
  ui_story_5031_50311501_195_dialog_content = "\"Warning: Massive Lumina detected, highest threat level.\"",
  ui_story_5031_50311501_196_dialog_content = "\"Switch to Ultimate Combat Mode.\"",
  ui_story_5031_50311502_1_dialog_content = "\"Warning... Hull damage over 70%.\"",
  ui_story_5031_50311502_2_dialog_content = "\"Right arm disconnected and cannot be auto-repaired.\"",
  ui_story_5031_50311502_3_dialog_content = "Are you holding up all right, Vice?",
  ui_story_5031_50311502_4_dialog_content = "Yeah. Long-range suppression isn't going to run me too much energy!",
  ui_story_5031_50311502_5_dialog_content = "Okay, let's concentrate fire on its right.",
  ui_story_5031_50311502_6_dialog_content = "The right arm is down, so that will impact its offense and defense.",
  ui_story_5031_50311502_7_dialog_content = "Got it!",
  ui_story_5031_50311502_8_dialog_content = "I must say, you exceeded my expectations, Carleen.",
  ui_story_5031_50311502_9_dialog_content = "I admire that, even if we're on opposite sides.",
  ui_story_5031_50311502_10_dialog_content = "However, I have reasons not to fail.",
  ui_story_5031_50311502_11_dialog_content = "Therefore, please excuse me for not staying to see the finale of this performance.",
  ui_story_5031_50311502_12_dialog_content = "You're not going anywhere, Elvis!",
  ui_story_5031_50311502_13_dialog_content = "Stop them.",
  ui_story_5031_50311502_14_dialog_content = "Look out, Vice, don't turn your back on the Guardian!",
  ui_story_5031_50311502_15_dialog_content = "Aghhh!",
  ui_story_5031_50311502_16_dialog_content = "...",
  ui_story_5031_50311502_17_dialog_content = "Rats, he got away.",
  ui_story_5031_50311502_18_dialog_content = "It's okay. We'll figure it out when we're done here.",
  ui_story_5031_50311502_19_dialog_content = "You're right.",
  ui_story_5031_50311502_20_dialog_content = "Now, the Guardian problem.",
  ui_story_5031_50311502_21_dialog_content = "So, we should... Hmm?",
  ui_story_5031_50311502_22_dialog_content = "What is it, Carleen?",
  ui_story_5031_50311502_23_dialog_content = "(Carleen's Lumina just got stronger?)",
  ui_story_5031_50311502_24_dialog_content = "This outfit isn't siphoning my Lumina anymore.",
  ui_story_5031_50311502_25_dialog_content = "Is it because Elvis left?",
  ui_story_5031_50311502_26_dialog_content = "That would explain why you were fine in that before.",
  ui_story_5031_50311502_27_dialog_content = "I guess Elvis has to maintain it in person for it to work.",
  ui_story_5031_50311502_28_dialog_content = "In that case, I don't have to hold back.",
  ui_story_5031_50311502_29_dialog_content = "Let's deal the final blow to this stupid, indiscriminate machine before it wrecks the ship.",
  ui_story_5031_50311502_30_dialog_content = "Yes! Jeno is better to be grateful once he wakes up.",
  ui_story_5031_50311502_31_dialog_content = "Are you defying me?",
  ui_story_5031_50311502_32_dialog_content = "The laird is meeting with the circus owner, and no one may board the ship.",
  ui_story_5031_50311502_33_dialog_content = "We're just carrying out orders, so please understand.",
  ui_story_5031_50311502_34_dialog_content = "All of you don't look like you're just watching the premises.",
  ui_story_5031_50311502_35_dialog_content = "Not to mention the sounds of explosions coming from the ship.",
  ui_story_5031_50311502_36_dialog_content = "Meeting? More like a grudge to me.",
  ui_story_5031_50311502_37_dialog_content = "Aren't you worried about your master? He's too scrawny to fight Jeno.",
  ui_story_5031_50311502_38_dialog_content = "Please leave.",
  ui_story_5031_50311502_39_dialog_content = "Oh? Are you going to make me?",
  ui_story_5031_50311502_40_dialog_content = "Then you better be ready for consequences, since I'll report it to...",
  ui_story_5031_50311502_41_dialog_content = "Do not be insolent, Patou.",
  ui_story_5031_50311502_42_dialog_content = "Laird!",
  ui_story_5031_50311502_43_dialog_content = "Oh, isn't it Laird Elvis? Is the meeting over?",
  ui_story_5031_50311502_44_dialog_content = "Sorry to keep you waiting, Matthieu, but I had important business with an old friend.",
  ui_story_5031_50311502_45_dialog_content = "Patou and his men are just following orders. Please forgive them.",
  ui_story_5031_50311502_46_dialog_content = "I see. May we board the ship now?",
  ui_story_5031_50311502_47_dialog_content = "Please, feel free.",
  ui_story_5031_50311502_48_dialog_content = "<size=33>Are we going to let him in just like this, sir?</size>",
  ui_story_5031_50311502_49_dialog_content = "<size=33>Doesn't matter. The ship will detonate soon, anyway.</size>",
  ui_story_5031_50311502_50_dialog_content = "<size=33>I'd much prefer to head for...</size>",
  ui_story_5031_50311502_51_dialog_content = "A moment, Laird Elvis.",
  ui_story_5031_50311502_52_dialog_content = "What is it?",
  ui_story_5031_50311502_53_dialog_content = "Did you see Her Highness Carleen aboard?",
  ui_story_5031_50311502_54_dialog_content = "No. Were she and her friends on board?",
  ui_story_5031_50311502_55_dialog_content = "That's odd. I've been waiting since the celebration was over but never saw Her Highness.",
  ui_story_5031_50311502_56_dialog_content = "She didn't disembark or see you, so why would she stay on the ship?",
  ui_story_5031_50311502_57_dialog_content = "Perhaps she's bidding farewell to the new friends she made.",
  ui_story_5031_50311502_58_dialog_content = "Since they probably got acquainted quite well over the course of the day.",
  ui_story_5031_50311502_59_dialog_content = "I was assigned to Her Highness as a bodyguard. So I basically babysat her for the whole day, afraid she might get hurt.",
  ui_story_5031_50311502_60_dialog_content = "I believe she didn't have much to do with the circus people, from my observations.",
  ui_story_5031_50311502_61_dialog_content = "But Miss Vice and Miss Ciel are old friends.",
  ui_story_5031_50311502_62_dialog_content = "And PlayerName gets along swimmingly with Miss Rainbow...",
  ui_story_5031_50311502_63_dialog_content = "Allow me to interject, Laird Elvis.",
  ui_story_5031_50311502_64_dialog_content = "Yes?",
  ui_story_5031_50311502_65_dialog_content = "I believe I didn't mention anyone else.",
  ui_story_5031_50311502_66_dialog_content = "If you did not see her, how can you be so sure she is with them?",
  ui_story_5031_50311502_67_dialog_content = "...",
  ui_story_5031_50311502_68_dialog_content = "That's because all four of them are close and always hang out together.",
  ui_story_5031_50311502_69_dialog_content = "You seem to know a lot for knowing them for only a day.",
  ui_story_5031_50311502_70_dialog_content = "I'm close to that tightly-wrapped partner of mine, yet he's not here.",
  ui_story_5031_50311502_71_dialog_content = "...",
  ui_story_5031_50311502_72_dialog_content = "Patou.",
  ui_story_5031_50311502_73_dialog_content = "Yes, laird.",
  ui_story_5031_50311502_74_dialog_content = "I see we're proceeding into the \"no witnesses\" phase.",
  ui_story_5031_50311502_75_dialog_content = "Not a bad fighting pose there.",
  ui_story_5031_50311502_76_dialog_content = "But you might not know that underneath our City Lord's icy exterior, he's extremely protective of his daughter.",
  ui_story_5031_50311502_77_dialog_content = "So do you think that I, as her bodyguard, could be easily dealt with?",
  ui_story_5031_50311502_78_dialog_content = "Time to make your entrance, Loewe!",
  ui_story_5031_50311502_79_dialog_content = "What?",
  ui_story_5031_50311502_80_dialog_content = "You talk too much, Matthieu.",
  ui_story_5031_50311502_81_dialog_content = "That's your business how?",
  ui_story_5031_50311502_82_dialog_content = "Just two of you?",
  ui_story_5031_50311502_83_dialog_content = "You hope to fight my men with just you two?",
  ui_story_5031_50311502_84_dialog_content = "Wrong, just one.",
  ui_story_5031_50311502_85_dialog_content = "You got this, Loewe. I'm going in for a rescue.",
  ui_story_5031_50311502_86_dialog_content = "...",
  ui_story_5031_50311502_87_dialog_content = "That won't be necessary.",
  ui_story_5031_50311502_88_dialog_content = "Hey, that sounds like...",
  ui_story_5031_50311502_89_dialog_content = "What?!",
  ui_story_5031_50311502_90_dialog_content = "Thank you for keeping Elvis busy.",
  ui_story_5031_50311502_91_dialog_content = "That's very helpful.",
  ui_story_5031_50311502_92_dialog_content = "Your Highness! It's great to see you still alive!",
  ui_story_5031_50311502_93_dialog_content = "Impossible!",
  ui_story_5031_50311502_94_dialog_content = "Where is the Guardian? How come the ship didn't blow up?",
  ui_story_5031_50311502_95_dialog_content = "Carleen hit it with full power, and it's a pile of scrap metal now.",
  ui_story_5031_50311502_96_dialog_content = "Though I got to say that robot was fantastically built!",
  ui_story_5031_50311502_97_dialog_content = "Too bad it stopped moving when we got there.",
  ui_story_5031_50311502_98_dialog_content = "It's okay. It's still good for research.",
  ui_story_5031_50311502_99_dialog_content = "You're right!",
  ui_story_5031_50311502_100_dialog_content = "But how? How could you still exert such power under restraint?",
  ui_story_5031_50311502_101_dialog_content = "Wait, did the Lumothread stop absorbing?",
  ui_story_5031_50311502_102_dialog_content = "Don't you control that, Elvis?",
  ui_story_5031_50311502_103_dialog_content = "Don't tell me it reached maximum capacity?",
  ui_story_5031_50311502_104_dialog_content = "That can't be... The outfit should be able to absorb Lumina from two, even three Aurorians!",
  ui_story_5031_50311502_105_dialog_content = "That is not important.",
  ui_story_5031_50311502_106_dialog_content = "What is, is that your plan failed, Elvis.",
  ui_story_5031_50311502_107_dialog_content = "Give up. You can't get away now.",
  ui_story_5031_50311502_108_dialog_content = "No, no... I can't fail! I must not fail!",
  ui_story_5031_50311502_109_dialog_content = "The <color=#FFB400>seal</color> will soon...",
  ui_story_5031_50311502_110_dialog_content = "Patou!",
  ui_story_5031_50311502_111_dialog_content = "Yes, sir!",
  ui_story_5031_50311502_112_dialog_content = "Resistance is pointless.",
  ui_story_5031_50311502_113_dialog_content = "Urgh...",
  ui_story_5031_50311502_114_dialog_content = "Now, Laird!",
  ui_story_5031_50311502_115_dialog_content = "I'll be a laughingstock if you get away. Think I'll let that happen?",
  ui_story_5031_50311502_116_dialog_content = "Ugh!",
  ui_story_5031_50311502_117_dialog_content = "Come on! I just \"nudged\" him, and he's done?",
  ui_story_5031_50311502_118_dialog_content = "How feeble is the man?",
  ui_story_5031_50311502_119_dialog_content = "Laird!",
  ui_story_5031_50311502_120_dialog_content = "I'm who you're fighting.",
  ui_story_5031_50311502_121_dialog_content = "Dammit!",
  ui_story_5031_50311502_122_dialog_content = "None of you are getting away.",
  ui_story_5031_50311601_1_dialog_content = "You got Ciel, right, Rainbow?",
  ui_story_5031_50311601_2_dialog_content = "Yes! I'll take good care of her, officer!",
  ui_story_5031_50311601_3_dialog_content = "Frimet will help too!",
  ui_story_5031_50311601_4_dialog_content = "And Subli!",
  ui_story_5031_50311601_5_dialog_content = "M-Merylt too.",
  ui_story_5031_50311601_6_dialog_content = "Oh, very good!",
  ui_story_5031_50311601_7_dialog_content = "Thank you, Officer Gronru, for letting me stay.",
  ui_story_5031_50311601_8_dialog_content = "It's all good. Nothing much is going on lately.",
  ui_story_5031_50311601_9_dialog_content = "You can take it easy here, Ciel.",
  ui_story_5031_50311601_10_dialog_content = "... Seriously? Just leave that energy core like that?",
  ui_story_5031_50311601_11_dialog_content = "Oh, it's just a small power core. It's not precious to Illumina.",
  ui_story_5031_50311601_12_dialog_content = "Although it's very similar to the energy core, it is worse in many aspects, and the purity of the outputted energy is no good.",
  ui_story_5031_50311601_13_dialog_content = "Moreover, after the senseless handling by that laird, it is basically a piece of scrap.",
  ui_story_5031_50311601_14_dialog_content = "Speaking of research value... Maybe it'll give you some inspiration for upgrading your \"Styx.\"",
  ui_story_5031_50311601_15_dialog_content = "Damn, I haven't studied this ship enough yet. Why must I be recalled at this time!",
  ui_story_5031_50311601_15X1_dialog_content = "Ciel, you must pay extra attention to the transmission system when you fix the core for them!",
  ui_story_5031_50311601_15X2_dialog_content = "Take good notes! I'll read them when you come back!",
  ui_story_5031_50311601_15X3_dialog_content = "I, I understand...",
  ui_story_5031_50311601_16_dialog_content = "Hey, what are you whispering about?",
  ui_story_5031_50311601_17_dialog_content = "I want to hear it too!",
  ui_story_5031_50311601_18_dialog_content = "Uh, i-if it was for us, they wouldn't have to whisper...",
  ui_story_5031_50311601_19_dialog_content = "Hmm, that made sense.",
  ui_story_5031_50311601_20_dialog_content = "Forget it, then.",
  ui_story_5031_50311601_21_dialog_content = "There you go.",
  ui_story_5031_50311601_22_dialog_content = "What did you say?",
  ui_story_5031_50311601_23_dialog_content = "Who's making all that noise?",
  ui_story_5031_50311601_24_dialog_content = "Are you sure, Your Highness?",
  ui_story_5031_50311601_25_dialog_content = "Are you really staying here to run the place?",
  ui_story_5031_50311601_26_dialog_content = "Yes.",
  ui_story_5031_50311601_27_dialog_content = "But Elvis took up arms against you. That's treason!",
  ui_story_5031_50311601_28_dialog_content = "Lord Schwartz wouldn't stand for that!",
  ui_story_5031_50311601_29_dialog_content = "That's exactly why I need help from you two.",
  ui_story_5031_50311601_30_dialog_content = "Why do I get a bad feeling about this?",
  ui_story_5031_50311601_31_dialog_content = "I hope you and Mr. Loewe will keep parts of this incident secret.",
  ui_story_5031_50311601_32_dialog_content = "Also, I'd like you both to stay with me in Harbor City for a while.",
  ui_story_5031_50311601_33_dialog_content = "I'm afraid not.",
  ui_story_5031_50311601_34_dialog_content = "Sorry, Your Highness, it came directly from Lady Irridon.",
  ui_story_5031_50311601_35_dialog_content = "I'm obligated to honor that.",
  ui_story_5031_50311601_36_dialog_content = "...",
  ui_story_5031_50311601_37_dialog_content = "I understand, Mr. Matthieu. I do not question your loyalty at all.",
  ui_story_5031_50311601_38_dialog_content = "But I'd rather not to cause trouble for you and Loewe.",
  ui_story_5031_50311601_39_dialog_content = "After all, I got 17 stitches for my wounds, not to mention the inability to use Lumina from over exhaustion.",
  ui_story_5031_50311601_40_dialog_content = "That could be problematic should either Lady Irridon or Lord Schwartz find out about it.",
  ui_story_5031_50311601_41_dialog_content = "Sure, but...",
  ui_story_5031_50311601_42_dialog_content = "Of course, it stemmed from my own negligence, and I'm okay now.",
  ui_story_5031_50311601_43_dialog_content = "The doctor also told me I should recover fully, given time.",
  ui_story_5031_50311601_44_dialog_content = "So if you'd like to avert unnecessary finger-pointing, I'd be happy to comply.",
  ui_story_5031_50311601_45_dialog_content = "...",
  ui_story_5031_50311601_46_dialog_content = "Why?",
  ui_story_5031_50311601_47_dialog_content = "Why what?",
  ui_story_5031_50311601_48_dialog_content = "Why do you insist on staying behind, Your Highness?",
  ui_story_5031_50311601_49_dialog_content = "Why cover up Elvis's transgression?",
  ui_story_5031_50311601_50_dialog_content = "Because, first of all, he did it for the good of the people of Harbor City.",
  ui_story_5031_50311601_51_dialog_content = "Second, Harbor City has always been a vassal of Lumopolis, and Laird Elvis even studied in Lumopolis before.",
  ui_story_5031_50311601_52_dialog_content = "Yet, he didn't request help from Lumopolis but sought a solution on his own and even kept it from Lumopolis.",
  ui_story_5031_50311601_53_dialog_content = "Why do you think that is?",
  ui_story_5031_50311601_54_dialog_content = "...",
  ui_story_5031_50311601_55_dialog_content = "It's because he didn't believe Lumopolis could or would help him.",
  ui_story_5031_50311601_56_dialog_content = "A laird unwilling to trust us is the root cause.",
  ui_story_5031_50311601_57_dialog_content = "We can't guarantee the next laird will not make the same choice Elvis made.",
  ui_story_5031_50311601_58_dialog_content = "If we don't get to the root of the problem and just ignore it, it will grow deeper.",
  ui_story_5031_50311601_59_dialog_content = "Thus, I'd like to find out Elvis's true intent.",
  ui_story_5031_50311601_60_dialog_content = "And uproot it before it's dug in too deep.",
  ui_story_5031_50311601_61_dialog_content = "...",
  ui_story_5031_50311601_62_dialog_content = "Heh, to me, you've always been nothing more than a naive, sheltered princess.",
  ui_story_5031_50311601_63_dialog_content = "...?",
  ui_story_5031_50311601_64_dialog_content = "But...",
  ui_story_5031_50311601_65_dialog_content = "I got to admit, that was a sensible speech.",
  ui_story_5031_50311601_66_dialog_content = "Isn't that right, Loewe?",
  ui_story_5031_50311601_67_dialog_content = "Yes.",
  ui_story_5031_50311601_68_dialog_content = "So...",
  ui_story_5031_50311601_69_dialog_content = "However!",
  ui_story_5031_50311601_70_dialog_content = "...",
  ui_story_5031_50311601_71_dialog_content = "We would never lie to Lady Irridon.",
  ui_story_5031_50311601_72_dialog_content = "Therefore, we'll still report everything via the Courier Union to her tonight.",
  ui_story_5031_50311601_73_dialog_content = "Where's that Courier Union at again?",
  ui_story_5031_50311601_74_dialog_content = "W-What was that? Loewe?",
  ui_story_5031_50311601_75_dialog_content = "...",
  ui_story_5031_50311601_76_dialog_content = "White Pearl Street, next to the Lucky Garden Restaurant.",
  ui_story_5031_50311601_77_dialog_content = "That's the one.",
  ui_story_5031_50311601_78_dialog_content = "It's on you, then.",
  ui_story_5031_50311601_79_dialog_content = "...",
  ui_story_5031_50311601_80_dialog_content = "Why aren't you doing it?",
  ui_story_5031_50311601_81_dialog_content = "Because I still have to secure the vicinity.",
  ui_story_5031_50311601_82_dialog_content = "Such a dangerous situation calls for an overall stronger person to ensure Her Highness' safety.",
  ui_story_5031_50311601_83_dialog_content = "...",
  ui_story_5031_50311601_84_dialog_content = "What, you want to fight me?",
  ui_story_5031_50311601_85_dialog_content = "Let's do it.",
  ui_story_5031_50311601_86_dialog_content = "Come on, let's get it on that lot over there. I'll beat you up today.",
  ui_story_5031_50311601_87_dialog_content = "In your dreams.",
  ui_story_5031_50311601_88_dialog_content = "...",
  ui_story_5031_50311601_89_dialog_content = "Have you reached an accord, Carleen?",
  ui_story_5031_50311601_90_dialog_content = "How come they started bickering?",
  ui_story_5031_50311601_91_dialog_content = "That's how they are. They bicker and fight but never split up.",
  ui_story_5031_50311601_92_dialog_content = "As for the incident report...",
  ui_story_5031_50311601_93_dialog_content = "I believe we have a neutral understanding.",
  ui_story_5031_50311601_94_dialog_content = "That's great!",
  ui_story_5031_50311601_95_dialog_content = "They might seem weird but turned out to be surprisingly nice.",
  ui_story_5031_50311601_96_dialog_content = "Are you sure you two aren't hurt?",
  ui_story_5031_50311601_97_dialog_content = "You don't have to keep me company here.",
  ui_story_5031_50311601_98_dialog_content = "How can we leave you alone in your present condition?",
  ui_story_5031_50311601_98X1_dialog_content = "Your Lumina was radiating like it was out of control, and you passed out shortly after we escaped...",
  ui_story_5031_50311601_98X2_dialog_content = "That really freaked us out!",
  ui_story_5031_50311601_98X3_dialog_content = "Apologies, for worrying everyone.",
  ui_story_5031_50311601_98X4_dialog_content = "How did you achieve the breakthrough all of a sudden, Carleen? That was amazing.",
  ui_story_5031_50311601_98X5_dialog_content = "At the time... I sensed what you described, Vice.",
  ui_story_5031_50311601_98X6_dialog_content = "I met all those anxieties that have been bothering me.",
  ui_story_5031_50311601_98X7_dialog_content = "They were so real, overbearing, and suffocating.",
  ui_story_5031_50311601_98X8_dialog_content = "Oh, Carleen...",
  ui_story_5031_50311601_98X9_dialog_content = "Fortunately, PlayerName got in touch with my mind and pulled me back from the abyss.",
  ui_story_5031_50311601_98X10_dialog_content = "It made me aware that you two are the \"something\" I needed...",
  ui_story_5031_50311601_98X11_dialog_content = "Thank you, PlayerName. And you too, Vice.",
  ui_story_5031_50311601_98X12_dialog_content = "You did it on your own, Carleen. You overcame the emotional baggage and mastered your own mind.",
  ui_story_5031_50311601_98X13_dialog_content = "That's true, but PlayerName always has a verbal chicken soup for the soul ready!",
  ui_story_5031_50311601_98X14_dialog_content = "Which is kind of marvelous!",
  ui_story_5031_50311601_98X15_dialog_content = "I-Is it real?",
  ui_story_5031_50311601_98X16_dialog_content = "I'm only speaking how I feel.",
  ui_story_5031_50311601_98X17_dialog_content = "That's very good in itself.",
  ui_story_5031_50311601_98X18_dialog_content = "Yes.",
  ui_story_5031_50311601_98X19_dialog_content = "But you should take it easy for a while, Carleen. Don't rush your recovery.",
  ui_story_5031_50311601_98X20_dialog_content = "Passing out from Lumina leaks can happen if you're not acclimated yet.",
  ui_story_5031_50311601_98X21_dialog_content = "So don't force yourself with the new power before you've recovered!",
  ui_story_5031_50311601_98X22_dialog_content = "That does sound like something Carleen would do.",
  ui_story_5031_50311601_98X23_dialog_content = "Okay, I got it.",
  ui_story_5031_50311601_98X24_dialog_content = "I'll take care of myself. Rest assured.",
  ui_story_5031_50311601_98X25_dialog_content = "As for the breakthrough, I'll search for the best way with Vice after I'm completely recuperated.",
  ui_story_5031_50311601_98X26_dialog_content = "No problem!",
  ui_story_5031_50311601_99_dialog_content = "You don't have to worry about us. PlayerName and I are tough, right?",
  ui_story_5031_50311601_100_dialog_content = "Yeah. You can lean on us once in a while, Carleen.",
  ui_story_5031_50311601_101_dialog_content = "So let us watch over you this time!",
  ui_story_5031_50311601_102_dialog_content = "Well then, thank you so much.",
  ui_story_5031_50311601_103_dialog_content = "No problem!",
  ui_story_5031_50311601_104_dialog_content = "What should we do next?",
  ui_story_5031_50311601_105_dialog_content = "Given the big mess, there are a lot of things to deal with in Harbor City.",
  ui_story_5031_50311601_106_dialog_content = "Carleen will be very busy as the interim laird.",
  ui_story_5031_50311601_107_dialog_content = "Indeed. But before that becomes official, I got someone I want to see.",
  ui_story_5031_50311601_108_dialog_content = "Who is it?",
  ui_story_5031_50311601_109_dialog_content = "Elvis.",
  ui_story_5031_50311601_110_dialog_content = "<color=#e8d9bb>To be continued...</color>"
}
return config
